58	/// Entry point: parse a single file and collect all extractable data.
59	/// Completely pure — no I/O, no side effects, no cross-file dependencies.
60	pub fn parse_file(path: &Utf8Path, source: &str) -> SourceData {
61	    let allocator = Allocator::default();
62	    let source_type = SourceType::from_path(path).unwrap_or_default();
63	    let ret = Parser::new(&allocator, source, source_type).parse();
64	
65	    let is_tsx = source_type.is_jsx();
66	    let mut collector = SourceDataCollector::new(path, source, is_tsx);
67	    collector.visit_program(&ret.program);
68	    collector.finish()
69	}
