71	struct SourceDataCollector<'src> {
72	    file_path: Utf8PathBuf,
73	    source: &'src str,
74	    is_tsx: bool,
75	    data: SourceData,
76	    /// Names that came from imports — used to classify ExtendsRef
77	    imported_names: FxHashSet<CompactString>,
78	}
