80	impl<'src> SourceDataCollector<'src> {
81	    fn new(path: &Utf8Path, source: &'src str, is_tsx: bool) -> Self { ... }
82	    
83	    fn scoped_key(&self, name: &str) -> String {
84	        format!("{}:{}", self.file_path, name)
85	    }
86	    
87	    fn finish(self) -> SourceData { self.data }
88	    
89	    fn classify_extends(&self, name: &str, type_args: Vec<String>) -> ExtendsRef {
90	        // Check against baked-in React type names first
91	        if let Some(element) = crate::react_types::html_element_for(name) {
92	            return ExtendsRef::Builtin {
93	                name: name.into(),
94	                element: Some(element.to_owned()),
95	                type_args,
96	            };
97	        }
98	        if crate::react_types::is_react_builtin(name) {
99	            return ExtendsRef::Builtin { name: name.into(), element: None, type_args };
100	        }
101	        // Check if imported
102	        if self.imported_names.contains(name) {
103	            return ExtendsRef::Imported {
104	                local_name: name.into(),
105	                type_args,
106	                source_specifier: self.find_import_specifier(name),
107	            };
108	        }
109	        ExtendsRef::SameFile { name: name.into(), type_args }
110	    }
111	}
