114	    fn visit_import_declaration(&mut self, node: &ImportDeclaration<'a>) {
115	        // Collect ImportBinding for each imported name
116	        // Record all imported names into self.imported_names
117	        let specifier = node.source.value.as_str().to_owned();
118	        let is_type_only = node.import_kind.is_type();
119	        
120	        if let Some(specifiers) = &node.specifiers {
121	            for spec in specifiers {
122	                match spec {
123	                    ImportDeclarationSpecifier::ImportSpecifier(s) => {
124	                        let local = s.local.name.as_str();
125	                        let imported = s.imported.name().as_str();
126	                        self.imported_names.insert(local.into());
127	                        self.data.imports.push(ImportBinding {
128	                            local_name: local.into(),
129	                            exported_name: imported.into(),
130	                            specifier: specifier.clone(),
131	                            is_type_only: is_type_only || s.import_kind.is_type(),
132	                        });
133	                    }
134	                    // Handle namespace and default imports similarly
135	                    _ => {}
