215	## Component Detection — The Three Patterns
216	
217	```rust
218	impl<'src> SourceDataCollector<'src> {
219	    fn try_collect_component(&mut self, decl: &VariableDeclarator<'a>) {
220	        let name = self.extract_pascal_name(decl)?;
221	        
222	        // Pattern 1: const Button: FC<ButtonProps> = ...
223	        if let Some(mapping) = self.try_fc_annotation(decl, &name) {
224	            self.data.component_mappings.push(mapping);
225	            return;
226	        }
227	        
228	        // Pattern 2: const Button = forwardRef<HTMLButtonElement, ButtonProps>(...)
229	        if let Some(mapping) = self.try_forward_ref(decl, &name) {
230	            self.data.component_mappings.push(mapping);
231	            return;
232	        }
233	        
234	        // Pattern 3: const Button = anyHOC(function Button(props: ButtonProps) {...})
235	        // or: const Button = anyHOC(function Button(props: ButtonProps, ref: R) {...})
236	        if let Some(mapping) = self.try_hoc_wrapped(decl, &name) {
237	            self.data.component_mappings.push(mapping);
238	            return;
239	        }
240	        
241	        // Pattern 4: function Button(props: ButtonProps) { ... }  [arrow not needed]
242	        // Handled in visit_function_declaration
243	    }
244	    
245	    fn try_fc_annotation(
246	        &self,
247	        decl: &VariableDeclarator<'a>,
248	        name: &str,
249	    ) -> Option<ComponentMapping> {
250	        // type annotation on the variable: Button: FC<ButtonProps>
251	        let type_ann = decl.id.type_annotation.as_ref()?;
252	        self.extract_props_from_type_annotation(&type_ann.type_annotation, name)
253	    }
254	    
255	    fn extract_props_from_type_annotation(
256	        &self,
257	        ty: &TSType<'a>,
258	        name: &str,
259	    ) -> Option<ComponentMapping> {
260	        match ty {
261	            TSType::TSTypeReference(tr) => {
262	                let type_name = self.extract_type_ref_name(tr);
263	                // FC, FunctionComponent, ComponentType, React.FC, React.FunctionComponent
264	                if !matches!(
265	                    type_name.as_str(),
266	                    "FC" | "FunctionComponent" | "ComponentType"
267	                    | "React.FC" | "React.FunctionComponent" | "React.ComponentType"
268	                    | "VFC" | "VoidFunctionComponent"
269	                ) {
270	                    return None;
271	                }
272	                // Unwrap PropsWithChildren<P> and Readonly<P>
273	                let (props_name, type_args) = self.extract_props_arg(&tr.type_parameters)?;
274	                Some(ComponentMapping {
275	                    component_name: name.to_owned(),
276	                    props_type_name: props_name,
277	                    props_type_args: type_args,
278	                    file_path: self.file_path.clone(),
279	                    description: self.find_jsdoc(decl.span.start),
280	                    tags: self.extract_jsdoc_tags(decl.span.start),
281	                    span_start: decl.span.start,
282	                    span_end: decl.span.end,
283	                })
284	            }
285	            _ => None,
286	        }
287	    }
288	    
289	    fn try_forward_ref(
290	        &self,
291	        decl: &VariableDeclarator<'a>,
292	        name: &str,
293	    ) -> Option<ComponentMapping> {
294	        let init = decl.init.as_ref()?;
295	        let call = init.as_call_expression()?;
296	        let callee_name = self.extract_callee_name(call)?;
297	        
298	        if !matches!(callee_name.as_str(), "forwardRef" | "React.forwardRef") {
299	            return None;
300	        }
301	        
302	        // forwardRef<RefType, PropsType>(fn)
303	        // PropsType is the second type parameter
304	        let type_params = call.type_parameters.as_ref()?;
305	        if type_params.params.len() < 2 {
306	            return None;
307	        }
308	        let props_type = &type_params.params[1];
309	        let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
310	        
311	        Some(ComponentMapping {
312	            component_name: name.to_owned(),
313	            props_type_name: props_name,
314	            props_type_args: type_args,
315	            file_path: self.file_path.clone(),
316	            description: self.find_jsdoc(decl.span.start),
317	            tags: BTreeMap::new(),
318	            span_start: decl.span.start,
319	            span_end: decl.span.end,
320	        })
321	    }
322	    
323	    fn try_hoc_wrapped(
324	        &self,
325	        decl: &VariableDeclarator<'a>,
326	        name: &str,
327	    ) -> Option<ComponentMapping> {
328	        let init = decl.init.as_ref()?;
329	        let call = init.as_call_expression()?;
330	        
331	        // First arg should be a function with a typed props param
332	        let first_arg = call.arguments.first()?;
333	        let fn_expr = self.extract_function_from_arg(first_arg)?;
334	        
335	        // Must be PascalCase — not anonymous utility functions
336	        if let Some(fn_name) = fn_expr.name {
337	            if !is_pascal_case(fn_name.name.as_str()) {
338	                return None;
339	            }
340	        }
341	        
342	        // Extract props type from first parameter annotation
343	        let first_param = fn_expr.params.items.first()?;
344	        let type_ann = first_param.pattern.type_annotation.as_ref()?;
345	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
346	        
347	        Some(ComponentMapping {
348	            component_name: name.to_owned(),
349	            props_type_name: props_name,
350	            props_type_args: type_args,
351	            file_path: self.file_path.clone(),
352	            description: self.find_jsdoc(decl.span.start),
353	            tags: BTreeMap::new(),
354	            span_start: decl.span.start,
355	            span_end: decl.span.end,
356	        })
357	    }
358	}
359	
360	fn is_pascal_case(s: &str) -> bool {
361	    s.starts_with(|c: char| c.is_uppercase())
362	}
