425	## JSDoc Extraction — Keep Simple
426	
427	```rust
428	/// Find JSDoc comment immediately preceding the given byte offset.
429	/// Returns empty string if none found.
430	fn find_jsdoc(comments: &[Comment], source: &str, span_start: u32) -> String {
431	    const PROXIMITY_THRESHOLD: u32 = 50; // bytes
432	    
433	    let comment = comments.iter()
434	        .rev()  // search backwards
435	        .find(|c| {
436	            c.is_block()
437	            && c.span.end <= span_start
438	            && span_start - c.span.end <= PROXIMITY_THRESHOLD
439	        })?;
440	    
441	    parse_jsdoc_text(&source[comment.span.start as usize..comment.span.end as usize])
442	}
443	
444	fn parse_jsdoc_text(raw: &str) -> String {
445	    // Strip /** */ markers
446	    // Strip leading " * " per line
447	    // Stop at @tag lines
448	    // Handle triple-backtick code blocks (toggle skip)
449	    raw.trim_start_matches("/**")
450	       .trim_end_matches("*/")
451	       .lines()
452	       .map(|l| l.trim().trim_start_matches("* ").trim_start_matches('*'))
453	       .take_while(|l| !l.starts_with('@'))
454	       .collect::<Vec<_>>()
455	       .join("\n")
456	       .trim()
457	       .to_owned()
458	}
