31	/// Where a type name actually lives.
32	#[derive(Debug, Clone)]
33	pub struct CanonicalRef {
34	    /// Absolute path of the file containing the declaration
35	    pub file_path: Utf8PathBuf,
36	    /// The name in that file (may differ after `as` rename)
37	    pub name: CompactString,
38	    /// Scoped key: "${file_path}:${name}" — for GlobalSourceData lookup
39	    pub scoped_key: String,
