96	                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } => {
97	                    if local_name == exported_name {
98	                        // Found the re-export — recurse to follow the chain
99	                        // source_specifier needs to be resolved to absolute path
100	                        // by the caller (which has access to oxc_resolver)
101	                        return Some(CanonicalRef {
102	                            file_path: Utf8PathBuf::from(source_specifier),
103	                            name: source_name.as_str().into(),
104	                            scoped_key: format!("{}:{}", source_specifier, source_name),
105	                        });
106	                    }
107	                }
108	                LexedExport::ReExportAll { source_specifier, .. } => {
109	                    // Check if the name exists in this wildcard source
110	                    // Caller handles recursive resolution
111	                }
112	                _ => {}
113	            }
114	        }
115	        None
116	    }
117	}
