159	//! Resolution of known generic type patterns.
160	//!
161	//! These are types that appear across many libraries and need special handling
162	//! because static analysis alone cannot fully resolve them, OR because their
163	//! full expansion is noise for docgen purposes.
164	//!
165	//! To add a new pattern: add a match arm. That's it.
166	
167	use crate::types::*;
168	
169	/// Result of recognizing a known type pattern.
170	pub enum KnownPatternResult {
171	    /// Pattern resolves to a set of props
172	    Props(Vec<ParsedProp>),
173	    /// Pattern is opaque — use this PropType directly
174	    Type(PropType),
175	    /// Pattern transparently delegates to another type name
176	    Alias { name: String, args: Vec<PropType> },
177	}
178	
179	/// Attempt to resolve a named generic type as a known pattern.
180	///
181	/// Called by the resolver when it encounters a type like `SxProps<Theme>`
182	/// or `VariantProps<typeof buttonVariants>`.
183	///
184	/// Returns `None` if this type is not recognized — caller should continue
185	/// with normal resolution.
186	pub fn resolve_known(
187	    name: &str,
188	    args: &[PropType],
189	    global: &GlobalSourceData,
190	) -> Option<KnownPatternResult> {
191	    match name {
192	        // ── Variant systems ──────────────────────────────────────────────────
193	        // class-variance-authority: VariantProps<typeof buttonVariants>
194	        // PandaCSS: RecipeVariantProps<typeof buttonStyle>
195	        "VariantProps" | "RecipeVariantProps" => {
196	            resolve_cva_variant_props(args, global)
197	        }
198	        
199	        // ── MUI styling ──────────────────────────────────────────────────────
200	        // SxProps is a massive conditional type — surface as opaque
201	        "SxProps" | "SystemStyleObject" | "SystemCssProperties" => {
202	            Some(KnownPatternResult::Type(PropType::SxProps))
203	        }
204	        
205	        // ── React Aria ───────────────────────────────────────────────────────
206	        // RenderProps<ButtonRenderProps> → simplify to scalar className/style/children
207	        "RenderProps" => Some(KnownPatternResult::Props(render_props())),
208	        // SlotProps → { slot?: string | null }
209	        "SlotProps" => Some(KnownPatternResult::Props(vec![slot_prop()])),
210	        
211	        // ── Chakra / Ark ─────────────────────────────────────────────────────
212	        // HTMLChakraProps<'button'> → same as ComponentPropsWithoutRef<'button'>
213	        "HTMLChakraProps" | "HTMLArkProps" | "HTMLStyledProps" => {
214	            html_attrs_from_first_arg(args)
215	        }
216	        
217	        // ── React standard ───────────────────────────────────────────────────
218	        "PropsWithChildren" => props_with_children(args),
219	        "PropsWithRef" => props_with_ref(args),
220	        
221	        // ComponentPropsWithoutRef<'button'> or ComponentPropsWithoutRef<typeof X>
222	        "ComponentPropsWithoutRef" | "ComponentProps" => component_props(args, false),
223	        "ComponentPropsWithRef" => component_props(args, true),
224	        
225	        // ElementRef<typeof X> → opaque Ref
226	        "ElementRef" => {
227	            Some(KnownPatternResult::Type(PropType::Ref { element: None }))
228	        }
229	        
230	        // ── Transparent utility types (handled by resolver, but shortcircuit here)
231	        // These are already handled in the resolver's Omit/Pick logic,
232	        // but if seen as standalone names, pass through:
233	        "Partial" | "Required" | "Readonly" | "NonNullable" => {
234	            None // let resolver handle
235	        }
236	        
237	        // ── MUI-specific ─────────────────────────────────────────────────────
238	        // OverridableStringUnion requires type checker — degrade gracefully
239	        "OverridableStringUnion" => {
240	            // First arg is the base union, second is the Overrides interface
241	            // We can use the base union and note the extension is opaque
242	            if let Some(base) = args.first() {
243	                Some(KnownPatternResult::Type(PropType::Union(vec![
244	                    base.clone(),
245	                    PropType::Opaque {
246	                        raw: "/* module augmentation */".into(),
247	                        reason: OpaqueReason::ModuleAugmentation,
248	                    },
249	                ])))
250	            } else {
251	                Some(KnownPatternResult::Type(PropType::Opaque {
252	                    raw: "OverridableStringUnion".into(),
253	                    reason: OpaqueReason::ModuleAugmentation,
254	                }))
255	            }
256	        }
257	        
258	        _ => None,
259	    }
260	}
261	
262	fn resolve_cva_variant_props(args: &[PropType], global: &GlobalSourceData) -> Option<KnownPatternResult> {
263	    // The arg is typeof buttonVariants — a Named type reference to a cva() call result.
264	    // We stored the cva() call variants in global.enums during extraction.
265	    // Look them up and return as individual props.
266	    //
267	    // If we can't find the variants (e.g. they're imported from elsewhere),
268	    // return an Opaque rather than failing.
269	    
270	    match args.first() {
271	        Some(PropType::Named { name, .. }) => {
272	            // Look for "${scoped_key}:${name}" in global enums
273	            // If found: create one LiteralUnion prop per variant key
274	            // If not found: opaque with good diagnostic message
275	            None // TODO: implement lookup
276	        }
277	        _ => Some(KnownPatternResult::Type(PropType::Opaque {
278	            raw: "VariantProps<...>".into(),
279	            reason: OpaqueReason::RuntimeDependent {
280	                function_name: "cva".into(),
281	            },
282	        })),
283	    }
284	}
285	
286	fn render_props() -> Vec<ParsedProp> {
287	    // React Aria RenderProps<T> → simplify to these three props
288	    // Omit the function overload — noise for docgen
289	    vec![
290	        simple_prop("className", PropType::String, false,
291	            "CSS class name. Accepts a function receiving render state."),
292	        simple_prop("style", PropType::CssProperties, false,
293	            "Inline styles. Accepts a function receiving render state."),
294	        // children handled separately — always comes from ReactNode
295	    ]
296	}
297	
298	fn slot_prop() -> ParsedProp {
299	    simple_prop(
300	        "slot",
301	        PropType::Union(vec![PropType::String, PropType::Null]),
302	        false,
303	        "Slot name for component context composition.",
304	    )
305	}
306	
307	fn props_with_children(args: &[PropType]) -> Option<KnownPatternResult> {
308	    // PropsWithChildren<T> = T & { children?: ReactNode }
309	    // Delegate to T (first arg), children prop comes from resolver's HTML table
310	    match args.first() {
311	        Some(inner) => Some(KnownPatternResult::Alias {
312	            name: inner.raw_string(),
313	            args: vec![],
314	        }),
315	        None => None,
316	    }
317	}
318	
319	fn props_with_ref(args: &[PropType]) -> Option<KnownPatternResult> {
320	    match args.first() {
321	        Some(inner) => Some(KnownPatternResult::Alias {
322	            name: inner.raw_string(),
323	            args: vec![],
324	        }),
325	        None => None,
326	    }
327	}
328	
329	fn html_attrs_from_first_arg(args: &[PropType]) -> Option<KnownPatternResult> {
330	    // HTMLChakraProps<'button'> → HtmlAttributes { element: "button" }
331	    match args.first() {
332	        Some(PropType::StringLiteral(element)) => {
333	            Some(KnownPatternResult::Type(PropType::HtmlAttributes {
334	                element: element.to_lowercase(),
335	                omitted: vec![],
336	            }))
337	        }
338	        _ => None,
339	    }
340	}
341	
342	fn component_props(args: &[PropType], _include_ref: bool) -> Option<KnownPatternResult> {
343	    match args.first() {
344	        Some(PropType::StringLiteral(element)) => {
345	            // ComponentPropsWithoutRef<'button'>
346	            Some(KnownPatternResult::Type(PropType::HtmlAttributes {
347	                element: element.to_lowercase(),
348	                omitted: vec![],
349	            }))
350	        }
351	        Some(PropType::Named { name, .. }) => {
352	            // ComponentPropsWithoutRef<typeof X> — delegate to X's props
353	            Some(KnownPatternResult::Alias { name: name.to_string(), args: vec![] })
354	        }
355	        _ => None,
356	    }
357	}
358	
359	fn simple_prop(name: &str, prop_type: PropType, required: bool, description: &str) -> ParsedProp {
360	    ParsedProp {
361	        name: name.to_owned(),
362	        prop_type,
363	        required,
364	        default_value: None,
365	        description: description.to_owned(),
366	        tags: Default::default(),
367	        parent: None,
368	        declarations: vec![],
369	    }
370	}
