431	/// Resolve a component mapping to a complete ComponentEntry.
432	/// Called in parallel via rayon — must be Send + Sync.
433	pub fn resolve_component(
434	    mapping: &ComponentMapping,
435	    ctx: &ResolutionContext,
436	) -> (ComponentEntry, Vec<Diagnostic>) {
437	    let mut diagnostics = Vec::new();
438	    let mut visited = FxHashSet::default();
439	    
440	    let chain = resolve_props_chain(
441	        &mapping.props_type_name,
442	        &mapping.props_type_args,
443	        &mapping.file_path,
444	        ctx,
445	        &mut visited,
446	        0,
447	        &mut diagnostics,
448	    );
449	    
450	    let props: BTreeMap<String, ParsedProp> = chain.props
451	        .into_iter()
452	        .map(|p| (p.name.clone(), p))
453	        .collect();
454	    
455	    (
456	        ComponentEntry {
457	            display_name: mapping.component_name.clone(),
458	            file_path: mapping.file_path.clone(),
459	            description: mapping.description.clone(),
460	            props,
461	            html_element: chain.html_element,
462	            omitted_html_props: chain.omitted_html_props,
463	            composes: chain.composes,
464	            tags: mapping.tags.clone(),
465	            methods: vec![],
466	        },
467	        diagnostics,
