471	/// Intermediate result of chain resolution.
472	struct ResolvedChain {
473	    props: Vec<ParsedProp>,
474	    html_element: Option<String>,
475	    omitted_html_props: Vec<String>,
476	    composes: Vec<String>,
477	}
478	
479	fn resolve_props_chain(
480	    type_name: &str,
481	    type_args: &[String],
482	    consuming_file: &Utf8Path,
483	    ctx: &ResolutionContext,
484	    visited: &mut FxHashSet<String>,
485	    depth: u8,
486	    diagnostics: &mut Vec<Diagnostic>,
487	) -> ResolvedChain {
488	    if depth > MAX_DEPTH {
489	        diagnostics.push(Diagnostic {
490	            severity: DiagnosticSeverity::Warning,
491	            message: format!("Max resolution depth exceeded for type '{}'", type_name),
492	            file: Some(consuming_file.to_string()),
493	            line: None, column: None,
494	            help: Some("This may indicate a circular type reference".into()),
495	            code: DiagnosticCode::MaxDepthExceeded,
496	        });
497	        return ResolvedChain::empty_with_compose(type_name.to_owned());
498	    }
499	    
500	    // Dedup — prevent infinite recursion on circular extends
501	    let visit_key = format!("{}:{}", consuming_file, type_name);
502	    if !visited.insert(visit_key) {
503	        return ResolvedChain::default();
504	    }
505	    
506	    // Step 1: Try known pattern resolution (cva, SxProps, RenderProps, etc.)
507	    let prop_type = parse_raw_type(type_name, type_args);
508	    if let PropType::Named { name, args } = &prop_type {
509	        if let Some(result) = resolve_known(name, args, &ctx.global) {
510	            return match result {
511	                KnownPatternResult::Props(props) => ResolvedChain { props, ..Default::default() },
512	                KnownPatternResult::Type(pt) => ResolvedChain::from_opaque_type(type_name, pt),
513	                KnownPatternResult::Alias { name, args } => {
514	                    resolve_props_chain(&name, &args.iter().map(|a| a.raw_string()).collect::<Vec<_>>(),
515	                        consuming_file, ctx, visited, depth + 1, diagnostics)
516	                }
517	            };
518	        }
519	    }
520	    
521	    // Step 2: Resolve import to find the canonical file
522	    let (canonical_file, canonical_name) = resolve_to_canonical(
523	        type_name, consuming_file, ctx, diagnostics
524	    ).unwrap_or_else(|| (consuming_file.to_owned(), type_name.to_owned()));
525	    
526	    let scoped_key = format!("{}:{}", canonical_file, canonical_name);
527	    
528	    // Step 3: Handle type aliases (Omit, Pick, Partial, etc.)
529	    if let Some(alias) = ctx.global.type_aliases.get(&scoped_key) {
530	        return resolve_type_alias(alias, consuming_file, ctx, visited, depth, diagnostics);
531	    }
532	    
533	    // Step 4: Handle interfaces (primary case)
534	    if let Some(iface) = ctx.global.interfaces.get(&scoped_key) {
535	        return resolve_interface(iface, type_args, consuming_file, ctx, visited, depth, diagnostics);
536	    }
537	    
538	    // Step 5: Unresolvable — degrade gracefully
539	    diagnostics.push(Diagnostic {
540	        severity: DiagnosticSeverity::Warning,
541	        message: format!("Cannot resolve type '{}' in '{}'", type_name, consuming_file),
542	        file: Some(consuming_file.to_string()),
543	        line: None, column: None,
544	        help: Some("Type may be in an unresolvable cross-package location".into()),
545	        code: DiagnosticCode::UnresolvableImport,
546	    });
547	    ResolvedChain::empty_with_compose(type_name.to_owned())
548	}
549	
550	fn resolve_interface(
551	    iface: &CollectedInterface,
552	    type_args: &[String],
553	    consuming_file: &Utf8Path,
554	    ctx: &ResolutionContext,
555	    visited: &mut FxHashSet<String>,
556	    depth: u8,
557	    diagnostics: &mut Vec<Diagnostic>,
558	) -> ResolvedChain {
559	    let mut chain = ResolvedChain::default();
560	    
561	    // Resolve extends first (parent props come before own props)
562	    for extends_ref in &iface.extends {
563	        let extends_chain = resolve_extends_ref(
564	            extends_ref, &iface.file_path, ctx, visited, depth + 1, diagnostics
565	        );
566	        // Smart merge: if same prop name exists, own prop wins
567	        chain.merge_parent(extends_chain, &iface.name, &iface.file_path);
568	    }
569	    
570	    // Resolve own props
571	    for raw_prop in &iface.props {
572	        let prop_type = resolve_raw_type(&raw_prop.raw_type, type_args, &iface.file_path, ctx, visited, depth, diagnostics);
573	        chain.props.push(ParsedProp {
574	            name: raw_prop.name.clone(),
575	            prop_type,
576	            required: raw_prop.required,
577	            default_value: None, // set by pipeline from destructured params
578	            description: raw_prop.description.clone(),
579	            tags: raw_prop.tags.clone(),
580	            parent: Some(PropParent {
581	                name: iface.name.to_string(),
582	                file_name: iface.file_path.to_string(),
583	            }),
584	            declarations: vec![PropParent {
585	                name: iface.name.to_string(),
586	                file_name: iface.file_path.to_string(),
587	            }],
588	        });
589	    }
590	    
591	    chain
592	}
593	
594	fn resolve_extends_ref(
595	    extends_ref: &ExtendsRef,
596	    iface_file: &Utf8Path,
597	    ctx: &ResolutionContext,
598	    visited: &mut FxHashSet<String>,
599	    depth: u8,
600	    diagnostics: &mut Vec<Diagnostic>,
601	) -> ResolvedChain {
602	    match extends_ref {
603	        ExtendsRef::Builtin { name, element, type_args } => {
604	            // HTML element attrs — look up in react_types tables
605	            if let Some(element) = element {
606	                ResolvedChain {
607	                    props: vec![], // HTML attrs resolved at serialization time
608	                    html_element: Some(element.clone()),
609	                    omitted_html_props: vec![],
610	                    composes: vec![],
611	                }
612	            } else {
613	                // Other builtins (AriaAttributes etc.) — get from baked-in table
614	                resolve_props_chain(name, type_args, iface_file, ctx, visited, depth, diagnostics)
615	            }
616	        }
617	        ExtendsRef::SameFile { name, type_args } => {
618	            resolve_props_chain(name, type_args, iface_file, ctx, visited, depth, diagnostics)
619	        }
620	        ExtendsRef::Imported { local_name, type_args, source_specifier } => {
621	            // Use oxc_resolver to find the actual file
622	            let resolved_file = resolve_import_specifier(
623	                source_specifier.as_deref().unwrap_or(local_name),
624	                iface_file,
625	                ctx,
626	                diagnostics,
627	            );
628	            let file = resolved_file.as_deref().unwrap_or(iface_file);
629	            resolve_props_chain(local_name, type_args, file, ctx, visited, depth, diagnostics)
630	        }
631	    }
632	}
633	
634	fn resolve_import_specifier(
635	    specifier: &str,
636	    from_file: &Utf8Path,
637	    ctx: &ResolutionContext,
638	    diagnostics: &mut Vec<Diagnostic>,
639	) -> Option<Utf8PathBuf> {
640	    let from_dir = from_file.parent()?;
641	    match ctx.oxc_resolver.resolve(from_dir.as_std_path(), specifier) {
642	        Ok(resolved) => Utf8PathBuf::from_path_buf(resolved.path().to_owned()).ok(),
643	        Err(e) => {
644	            diagnostics.push(Diagnostic {
645	                severity: DiagnosticSeverity::Warning,
646	                message: format!("Cannot resolve '{}' from '{}'", specifier, from_file),
647	                file: Some(from_file.to_string()),
648	                line: None, column: None,
649	                help: Some(format!("Resolution error: {}", e)),
650	                code: DiagnosticCode::UnresolvableImport,
651	            });
652	            None
653	        }
654	    }
655	}
