```rust
use camino::{Utf8Path, Utf8PathBuf};
use dashmap::DashMap;
use serde::{Deserialize, Serialize};
use std::time::SystemTime;

use crate::types::SourceData;

const CACHE_SCHEMA_VERSION: u32 = 1;

#[derive(Hash, Eq, PartialEq, Clone)]
struct CacheKey {
    path: Utf8PathBuf,
    size: u64,
    mtime_ns: u128,
}

pub struct DtsCache {
    store: DashMap<CacheKey, SourceData>,
    cache_dir: Utf8PathBuf,
}

impl DtsCache {
    /// Load from disk. Returns empty cache on any error (never fails).
    /// Cache dir defaults to {cwd}/node_modules/.cache/oxc-react-docgen/
    pub fn load_from_disk(cache_dir: Option<&Utf8Path>) -> Self {
        let dir = cache_dir
            .map(|p| p.to_owned())
            .unwrap_or_else(|| {
                Utf8PathBuf::from("node_modules/.cache/oxc-react-docgen")
            });

        let store = Self::try_load(&dir).unwrap_or_default();
        Self { store, cache_dir: dir }
    }

    fn try_load(dir: &Utf8Path) -> Option<DashMap<CacheKey, SourceData>> {
        // Read manifest first to check schema version
        let manifest_path = dir.join("manifest.json");
        let manifest: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(manifest_path).ok()?
        ).ok()?;

        if manifest["schema"].as_u64()? != CACHE_SCHEMA_VERSION as u64 {
            return None; // Schema changed, discard
        }

        let data_path = dir.join("dts-v1.msgpack");
        let bytes = std::fs::read(data_path).ok()?;
        // Deserialize as Vec<(CacheKey, SourceData)> then collect into DashMap
        let entries: Vec<(SerializableCacheKey, SourceData)> = rmp_serde::from_slice(&bytes).ok()?;
        let map = DashMap::with_capacity(entries.len());
        for (k, v) in entries {
            map.insert(k.into(), v);
        }
        Some(map)
    }

    /// Try to get cached SourceData for a file. Checks mtime+size for validity.
    pub fn get(&self, path: &Utf8Path) -> Option<SourceData> {
        let meta = std::fs::metadata(path.as_std_path()).ok()?;
        let key = CacheKey {
            path: path.to_owned(),
            size: meta.len(),
            mtime_ns: meta.modified().ok()
                .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
                .map(|d| d.as_nanos())
                .unwrap_or(0),
        };
        self.store.get(&key).map(|v| v.clone())
    }

    /// Insert parsed SourceData. Reads current mtime+size from filesystem.
    pub fn insert(&self, path: &Utf8Path, data: SourceData) {
        let Ok(meta) = std::fs::metadata(path.as_std_path()) else { return };
        let key = CacheKey {
            path: path.to_owned(),
            size: meta.len(),
            mtime_ns: meta.modified().ok()
                .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
                .map(|d| d.as_nanos())
                .unwrap_or(0),
        };
        self.store.insert(key, data);
    }

    /// Save to disk atomically. Never panics.
    pub fn save_to_disk(&self) {
        let _ = self.try_save();
    }

    fn try_save(&self) -> Option<()> {
        std::fs::create_dir_all(self.cache_dir.as_std_path()).ok()?;

        // Collect entries to serialize
        let entries: Vec<(SerializableCacheKey, SourceData)> = self.store
            .iter()
            .map(|r| (SerializableCacheKey::from(r.key()), r.value().clone()))
            .collect();

        let bytes = rmp_serde::to_vec(&entries).ok()?;

        // Atomic write: temp file → rename
        let tmp_path = self.cache_dir.join("dts-v1.msgpack.tmp");
        let final_path = self.cache_dir.join("dts-v1.msgpack");
        std::fs::write(tmp_path.as_std_path(), &bytes).ok()?;
        std::fs::rename(tmp_path.as_std_path(), final_path.as_std_path()).ok()?;

        // Write manifest
        let manifest = serde_json::json!({
            "schema": CACHE_SCHEMA_VERSION,
            "entry_count": entries.len(),
        });
        std::fs::write(
            self.cache_dir.join("manifest.json").as_std_path(),
            serde_json::to_string_pretty(&manifest).ok()?.as_bytes(),
        ).ok()?;

        Some(())
    }
}

// Serializable version of CacheKey (CacheKey itself has u128 which rmp-serde may not handle)
#[derive(Serialize, Deserialize)]
struct SerializableCacheKey {
    path: String,
    size: u64,
    mtime_ns: u64, // truncated to u64 nanoseconds (sufficient for decades)
}

impl From<&CacheKey> for SerializableCacheKey {
    fn from(k: &CacheKey) -> Self {
        Self { path: k.path.to_string(), size: k.size, mtime_ns: k.mtime_ns as u64 }
    }
}

impl From<SerializableCacheKey> for CacheKey {
    fn from(k: SerializableCacheKey) -> Self {
        Self {
            path: Utf8PathBuf::from(k.path),
            size: k.size,
            mtime_ns: k.mtime_ns as u128,
        }
    }
}
