## resolver.rs — the full implementation

The resolver takes a `ComponentMapping` and produces a `ComponentEntry` with fully resolved `PropType` props. Read the spec in docs/04-PHASE2B2C-3A3B.md carefully for the full structure.

### Key implementation points

**1. Central dispatch: `resolve_collected_type`**

The main function that converts `CollectedType` → `PropType`. Never re-parses strings. Example structure:
```rust
fn resolve_collected_type(
    ct: &CollectedType,
    consuming_file: &Utf8Path,
    ctx: &ResolutionContext,
    visited: &mut FxHashSet<String>,
    depth: u8,
    diagnostics: &mut Vec<Diagnostic>,
) -> PropType {
    match ct {
        CollectedType::String => PropType::String,
        CollectedType::Number => PropType::Number,
        CollectedType::Boolean => PropType::Boolean,
        CollectedType::Null => PropType::Null,
        CollectedType::Undefined => PropType::Undefined,
        CollectedType::Any => PropType::Any,
        CollectedType::Never => PropType::Never,
        CollectedType::Unknown => PropType::Unknown,
        CollectedType::Void => PropType::Void,
        CollectedType::BigInt | CollectedType::Symbol => PropType::Named { name: ct.to_raw_string().into(), args: vec![] },
        CollectedType::StringLiteral(s) => PropType::StringLiteral(s.to_string()),
        CollectedType::NumberLiteral(n) => PropType::NumberLiteral(*n),
        CollectedType::BoolLiteral(b) => PropType::BoolLiteral(*b),
        CollectedType::Union(members) => resolve_union(members, consuming_file, ctx, visited, depth, diagnostics),
        CollectedType::Intersection(members) => resolve_intersection(members, consuming_file, ctx, visited, depth, diagnostics),
        CollectedType::Array(inner) => PropType::Array(Box::new(resolve_collected_type(inner, consuming_file, ctx, visited, depth + 1, diagnostics))),
        CollectedType::Tuple(members) => PropType::Tuple(members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, visited, depth + 1, diagnostics)).collect()),
        CollectedType::Object(fields) => PropType::Object(fields.iter().map(|f| ObjectField {
            name: f.name.clone(),
            prop_type: resolve_collected_type(&f.collected_type, consuming_file, ctx, visited, depth + 1, diagnostics),
            required: f.required,
            description: f.description.clone(),
        }).collect()),
        CollectedType::Named { name, args } => resolve_named(name, args, consuming_file, ctx, visited, depth, diagnostics),
        CollectedType::TypeOf(name) => resolve_typeof(name, consuming_file, ctx, diagnostics),
        CollectedType::IndexedAccess { obj, key } => resolve_indexed_access(obj, key, consuming_file, ctx, visited, depth, diagnostics),
        CollectedType::TemplateLiteral(parts) => resolve_template_literal(parts, consuming_file, ctx, visited, depth, diagnostics),
        CollectedType::Function { params, return_type } => resolve_function_type(params, return_type, consuming_file, ctx, visited, depth, diagnostics),
        CollectedType::Conditional { .. } => PropType::Opaque {
            raw: ct.to_raw_string(),
            reason: OpaqueReason::ConditionalType,
        },
        CollectedType::Mapped { .. } => PropType::Opaque {
            raw: ct.to_raw_string(),
            reason: OpaqueReason::MappedType,
        },
        CollectedType::Raw(s) => {
            // Last resort: attempt to parse as a Named type
            if !s.contains(' ') && !s.contains('|') && !s.contains('&') {
                PropType::Named { name: s.as_str().into(), args: vec![] }
            } else {
                PropType::Opaque { raw: s.clone(), reason: OpaqueReason::DepthExceeded }
            }
        }
        CollectedType::TypeOf(_) => PropType::Opaque { raw: ct.to_raw_string(), reason: OpaqueReason::DepthExceeded },
    }
}
```

**2. `resolve_named` — the core lookup**

```rust
fn resolve_named(name: &CompactString, args: &[CollectedType], consuming_file: &Utf8Path, ctx: &ResolutionContext, visited: &mut FxHashSet<String>, depth: u8, diagnostics: &mut Vec<Diagnostic>) -> PropType {
    if depth > MAX_DEPTH { ... emit diagnostic, return Opaque }

    // 1. React builtin check
    if react_types::is_react_builtin(name, &ctx.extra_builtins) {
        return react_type_to_prop_type(name, args, ctx, visited, depth, diagnostics);
    }

    // 2. Known pattern check
    let resolved_args: Vec<PropType> = args.iter()
        .map(|a| resolve_collected_type(a, consuming_file, ctx, visited, depth + 1, diagnostics))
        .collect();
    if let Some(result) = known::resolve_known(name, &resolved_args, &ctx.global) {
        return match result {
            KnownPatternResult::Type(pt) => pt,
            KnownPatternResult::Props(props) => ... // handled differently for prop-level
            KnownPatternResult::Alias { name: alias_name, args: alias_args } => {
                // Follow the alias
                resolve_named(&alias_name.as_str().into(), &alias_args.iter().map(|a| CollectedType::Raw(a.raw_string())).collect::<Vec<_>>(), consuming_file, ctx, visited, depth + 1, diagnostics)
            }
        };
    }

    // 3. Import resolution
    let (canonical_file, canonical_name) = resolve_to_canonical(name, consuming_file, ctx, diagnostics)
        .unwrap_or_else(|| (consuming_file.to_owned(), name.to_string()));

    let scoped_key = format!("{}:{}", canonical_file, canonical_name);

    // 4. Type alias lookup
    if let Some(alias) = ctx.global.type_aliases.get(&scoped_key) {
        return resolve_type_alias(alias, consuming_file, ctx, visited, depth, diagnostics);
    }

    // 5. Interface lookup
    if let Some(iface) = ctx.global.interfaces.get(&scoped_key) {
        // clone to avoid borrow issues
        let iface = iface.clone();
        return PropType::Named { name: name.clone(), args: resolved_args }; // let caller handle as interface
        // Actually: resolve the interface and return its props merged — but for a prop TYPE we return Named
        // The prop-level handling (build ParsedProp vec) happens in resolve_interface_for_component
    }

    // 6. Unresolvable
    diagnostics.push(Diagnostic { code: DiagnosticCode::UnresolvableImport, ... });
    PropType::Named { name: name.clone(), args: resolved_args }
}
```

Note: When a prop's type is itself an interface name (e.g., `ButtonProps`), we return `PropType::Named` — we don't recursively expand all props. Expansion only happens at the COMPONENT level (resolve_component_props_chain), not at the prop-type level.

**3. `(string & {})` normalization in resolve_intersection**

```rust
fn resolve_intersection(members: &[CollectedType], ...) -> PropType {
    // Normalize (string & {}) → String
    // {} is CollectedType::Object([]) (empty object type)
    let non_empty: Vec<&CollectedType> = members.iter()
        .filter(|m| !matches!(m, CollectedType::Object(f) if f.is_empty()))
        .collect();
    if non_empty.len() == 1 && matches!(non_empty[0], CollectedType::String) {
        return PropType::String;
    }

    let resolved: Vec<PropType> = members.iter()
        .map(|m| resolve_collected_type(m, ...))
        .collect();
    PropType::Intersection(resolved)
}
```

**4. Indexed access resolution**

```rust
fn resolve_indexed_access(obj: &CollectedType, key: &CollectedType, ...) -> PropType {
    // Try known table first
    let obj_name = match obj { CollectedType::Named { name, .. } => name.as_str(), _ => "" };
    let key_str = match key { CollectedType::StringLiteral(s) => s.as_str(), _ => "" };

    let known = match (obj_name, key_str) {
        ("CSSProperties" | "React.CSSProperties", "zIndex" | "opacity" | "order" | "flexGrow" | "flexShrink") => Some(PropType::Number),
        ("CSSProperties" | "React.CSSProperties", _) if !key_str.is_empty() => Some(PropType::String),
        ("HTMLAttributes" | "React.HTMLAttributes" | "DOMAttributes" | "React.DOMAttributes", "className" | "id" | "slot" | "title") => Some(PropType::String),
        ("HTMLAttributes" | "React.HTMLAttributes", "tabIndex") => Some(PropType::Number),
        ("HTMLAttributes" | "React.HTMLAttributes", "style") => Some(PropType::CssProperties),
        _ => None,
    };

    if let Some(pt) = known { return pt; }

    // Degrade gracefully
    diagnostics.push(Diagnostic { code: DiagnosticCode::OpaqueType, ... });
    PropType::Opaque {
        raw: format!("{}[{}]", obj.to_raw_string(), key.to_raw_string()),
        reason: OpaqueReason::IndexedAccess { expression: format!("{}[{}]", obj.to_raw_string(), key.to_raw_string()) },
    }
}
```

