**6. Function type → render prop or event handler detection**

```rust
fn resolve_function_type(params: &[CollectedType], return_type: &CollectedType, ...) -> PropType {
    // Check if return type is ReactNode/ReactElement/JSX.Element → it's a render prop or event handler
    let returns_react = matches!(return_type,
        CollectedType::Named { name, .. } if matches!(name.as_str(), "ReactNode" | "ReactElement" | "JSX.Element" | "Element")
    );

    if returns_react && params.len() == 1 {
        if let CollectedType::Named { name: state_type, .. } = &params[0] {
            // (renderProps: ButtonRenderProps) => ReactNode
            return PropType::EventHandler { event_type: state_type.to_string() };
        }
    }

    // Generic event handler: (e: MouseEvent) => void
    if params.len() == 1 {
        let event_type = params[0].to_raw_string();
        return PropType::EventHandler { event_type };
    }

    // Complex function type
    PropType::Opaque { raw: "(...) => ...".into(), reason: OpaqueReason::ConditionalType }
}
```

