**10. tsconfig path reading**

```rust
fn read_tsconfig_paths(tsconfig: Option<&Utf8Path>) -> Vec<(String, Vec<std::path::PathBuf>)> {
    let Some(path) = tsconfig else { return vec![] };
    let Ok(content) = std::fs::read_to_string(path.as_std_path()) else { return vec![] };
    // Strip comments (tsconfigs allow comments)
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&strip_json_comments(&content)) else { return vec![] };

    let base_url = value["compilerOptions"]["baseUrl"].as_str()
        .map(|b| path.parent().unwrap_or(path).join(b));

    let paths = value["compilerOptions"]["paths"].as_object();
    let Some(paths) = paths else { return vec![] };

    paths.iter().filter_map(|(pattern, targets)| {
        let resolved: Vec<std::path::PathBuf> = targets.as_array()?
            .iter()
            .filter_map(|t| t.as_str())
            .map(|t| {
                let t = t.trim_end_matches("/*").trim_end_matches("*");
                let p = if let Some(base) = &base_url {
                    base.join(t).into_std_path_buf()
                } else {
                    path.parent().unwrap_or(path).join(t).into_std_path_buf()
                };
                p
            })
            .collect();
        let pattern = pattern.trim_end_matches("/*").to_owned();
        Some((pattern, resolved))
    }).collect()
}

fn strip_json_comments(s: &str) -> String {
    // Simple line-comment stripper for tsconfig
    s.lines()
        .map(|line| {
            if let Some(idx) = line.find("//") {
                // Only strip if not inside a string (simple heuristic)
                if line[..idx].chars().filter(|&c| c == '"').count() % 2 == 0 {
                    return &line[..idx];
                }
            }
            line
        })
        .collect::<Vec<_>>()
        .join("\n")
}
```

**11. `react_type_to_prop_type` helper**

```rust
fn react_type_to_prop_type(name: &str, args: &[CollectedType], ctx: &ResolutionContext, visited: &mut FxHashSet<String>, depth: u8, diagnostics: &mut Vec<Diagnostic>) -> PropType {
    let strip = name.strip_prefix("React.").unwrap_or(name);
    match strip {
        "ReactNode" | "ReactElement" | "JSX.Element" | "ReactPortal" | "ReactFragment" | "ReactChild" => PropType::ReactNode,
        "CSSProperties" | "CSSObject" => PropType::CssProperties,
        n if n.ends_with("EventHandler") || n.ends_with("Handler") => {
            PropType::EventHandler { event_type: name.to_owned() }
        }
        "Ref" | "RefObject" | "ForwardedRef" | "MutableRefObject" | "RefCallback" | "LegacyRef" => {
            let element = args.first().map(|a| a.to_raw_string());
            PropType::Ref { element }
        }
        "ElementType" => PropType::ElementType,
        "FC" | "FunctionComponent" | "VFC" | "VoidFunctionComponent" | "ComponentType" => {
            // FC<P> — if there's a type arg, that's the props type
            PropType::Named { name: name.into(), args: args.iter().map(|a| {
                resolve_collected_type(a, Utf8Path::new(""), ctx, visited, depth + 1, diagnostics)
            }).collect() }
        }
        "ComponentPropsWithoutRef" | "ComponentProps" => {
            if let Some(first) = args.first() {
                match first {
                    CollectedType::StringLiteral(el) => PropType::HtmlAttributes { element: el.to_lowercase(), omitted: vec![] },
                    other => PropType::Named { name: name.into(), args: vec![resolve_collected_type(other, Utf8Path::new(""), ctx, visited, depth + 1, diagnostics)] },
                }
            } else { PropType::Any }
        }
        _ => PropType::Named { name: name.into(), args: args.iter().map(|a| resolve_collected_type(a, Utf8Path::new(""), ctx, visited, depth + 1, diagnostics)).collect() }
    }
}
```

