### `extract()` — the main cold extraction function

Follow the pipeline spec closely:
```rust
pub fn extract(options: &PipelineOptions) -> ExtractionOutput {
    let start = Instant::now();
    let mut diagnostics = Vec::new();

    // Load DTS cache
    let cache = DtsCache::load_from_disk(options.cache_dir.as_deref());

    // Phase 1: Discover source files
    let src_files = discover_files(&options.src_dirs, &options.exclude_patterns);

    // Phase 2: Parallel parse with rayon
    let source_data_vec: Vec<(Utf8PathBuf, SourceData)> = src_files
        .par_iter()
        .map(|path| {
            let source = std::fs::read_to_string(path).unwrap_or_default();
            (path.clone(), crate::extractor::parse_file(path, &source))
        })
        .collect();

    let files_parsed = source_data_vec.len() as u32;

    // Phase 3: Merge into GlobalSourceData (sequential)
    let mut global = GlobalSourceData::default();
    for (path, data) in source_data_vec {
        global.merge(&path, data);
    }
    let global = Arc::new(global);

    // Phase 4: Build resolution context
    let ctx = Arc::new(ResolutionContext::new(global.clone(), options));

    // Phase 5: Parallel resolve
    let mappings: Vec<ComponentMapping> = global.component_mappings
        .iter()
        .filter(|m| !should_skip(&m.component_name, &options.exclude_prefixes))
        .cloned()
        .collect();

    let results: Vec<(ComponentEntry, Vec<Diagnostic>)> = mappings
        .par_iter()
        .map(|mapping| crate::resolver::resolve_component(mapping, &ctx))
        .collect();

    // Phase 6: Collect output
    let mut components = std::collections::BTreeMap::new();
    for (entry, diags) in results {
        components.insert(entry.display_name.clone(), entry);
        diagnostics.extend(diags);
    }

    // Collect public enums (exported from source files)
    let enums = collect_public_enums(&global);

    // Save cache
    cache.save_to_disk();

    let duration_ms = start.elapsed().as_millis() as u64;
    let components_extracted = components.len() as u32;

    ExtractionOutput {
        components,
        enums,
        diagnostics,
        stats: ExtractionStats {
            components_extracted,
            files_parsed,
            duration_ms,
            ..Default::default()
        },
    }
}
```

### `discover_files()` — use the `ignore` crate

```rust
fn discover_files(src_dirs: &[Utf8PathBuf], extra_excludes: &[String]) -> Vec<Utf8PathBuf> {
    let mut files = Vec::new();

    for dir in src_dirs {
        let walker = ignore::WalkBuilder::new(dir.as_std_path())
            .hidden(false)
            .git_ignore(true)
            .build();

        for entry in walker.flatten() {
            let path = entry.path();
            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
            if !matches!(ext, "ts" | "tsx") { continue; }

            let path_str = path.to_str().unwrap_or("");

            // Built-in excludes
            if path_str.contains(".stories.")
                || path_str.contains(".test.")
                || path_str.contains(".spec.")
                || path_str.contains("__snapshots__")
                || path_str.contains("node_modules")
            { continue; }

            // User excludes
            if extra_excludes.iter().any(|p| path_str.contains(p.as_str())) { continue; }

            if let Ok(utf8) = Utf8PathBuf::from_path_buf(path.to_owned()) {
                files.push(utf8);
            }
        }
    }

