### `collect_public_enums()` — only exported enums

```rust
fn collect_public_enums(global: &GlobalSourceData) -> std::collections::BTreeMap<String, Vec<EnumEntry>> {
    let mut result = std::collections::BTreeMap::new();

    // Only include enums that are in re_export_map (i.e., exported from the file)
    for (scoped_key, entries) in &global.enums {
        // scoped_key = "file_path:name"
        if let Some((file_path, name)) = scoped_key.split_once(':') {
            let file_path = Utf8Path::new(file_path);
            // Check if this name is exported from its file
            let is_exported = global.re_export_map.get(file_path)
                .map(|exports| exports.iter().any(|e| match e {
                    LexedExport::LocalDeclaration { name: n, .. } => n == name,
                    _ => false,
                }))
                .unwrap_or(false);

            if is_exported {
                result.insert(name.to_owned(), entries.clone());
            }
        }
    }
    result
}
```

### `WatchSession` and `IncrementalUpdate`

```rust
use arc_swap::ArcSwap;
use dashmap::DashMap;

pub struct IncrementalUpdate {
    pub updated_components: Vec<ComponentEntry>,
    pub affected_files: Vec<Utf8PathBuf>,
    pub diagnostics: Vec<Diagnostic>,
    pub duration_ms: u64,
}

pub struct ReverseDeps {
    /// file → list of files that import from it (by specifier, not resolved path for now)
    inner: rustc_hash::FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>>,
}

impl ReverseDeps {
    pub fn build(global: &GlobalSourceData) -> Self {
        let mut inner: rustc_hash::FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>> = Default::default();

        // For each file's imports, record reverse dependency
        // Note: specifiers aren't resolved here — we just track file → importing files
        for (consumer_file, imports) in &global.import_map {
            for import in imports {
                // Try to resolve relative imports only (absolute/package imports can't be easily reversed here)
                if import.specifier.starts_with('.') {
                    if let Some(parent) = consumer_file.parent() {
                        let target = parent.join(&import.specifier);
                        // Normalize extensions (rough approximation)
                        for ext in &[".ts", ".tsx", "/index.ts", "/index.tsx"] {
                            let candidate = Utf8PathBuf::from(format!("{}{}", target, ext));
                            inner.entry(candidate).or_default().push(consumer_file.clone());
                        }
                    }
                }
            }
        }

        Self { inner }
    }

    /// BFS: find all files transitively affected by a change to `changed`.
    pub fn affected(&self, changed: &Utf8Path) -> rustc_hash::FxHashSet<Utf8PathBuf> {
        let mut visited = rustc_hash::FxHashSet::default();
        let mut queue = std::collections::VecDeque::new();
        queue.push_back(changed.to_owned());

        while let Some(file) = queue.pop_front() {
            if visited.insert(file.clone()) {
                for dep in self.inner.get(&file).into_iter().flatten() {
                    queue.push_back(dep.clone());
                }
            }
        }
        visited
    }
}

pub struct WatchSession {
    pub options: PipelineOptions,
    pub global: ArcSwap<GlobalSourceData>,
    pub reverse_deps: Arc<ReverseDeps>,
    pub source_cache: DashMap<Utf8PathBuf, SourceData>,
    pub component_cache: DashMap<String, ComponentEntry>,
}

impl WatchSession {
    pub fn new(options: PipelineOptions) -> Self {
        Self {
            options,
            global: ArcSwap::new(Arc::new(GlobalSourceData::default())),
            reverse_deps: Arc::new(ReverseDeps { inner: Default::default() }),
            source_cache: DashMap::new(),
            component_cache: DashMap::new(),
        }
    }

    /// Initialize by running a full extraction, populating global and reverse deps.
    pub fn initialize(&self) -> ExtractionOutput {
        let output = extract(&self.options);

        // Rebuild global from scratch using the source cache
        // (extract() builds its own GlobalSourceData — we need to repopulate ours)
        // For now: run extract() which populates the static data, then rebuild global separately
        // TODO: thread the GlobalSourceData through from extract() for efficiency

        let src_files = discover_files(&self.options.src_dirs, &self.options.exclude_patterns);
        let mut global = GlobalSourceData::default();

        for path in &src_files {
            let source = std::fs::read_to_string(path).unwrap_or_default();
            let data = crate::extractor::parse_file(path, &source);
            self.source_cache.insert(path.clone(), data.clone());
            global.merge(path, data);
        }

        let new_reverse_deps = ReverseDeps::build(&global);

        // Atomic swap
        self.global.store(Arc::new(global));
        // Note: reverse_deps is Arc, can't swap atomically without ArcSwap
        // For watch mode v1, rebuild reverse_deps in new WatchSession on structural changes

        output
    }

    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
        let start = Instant::now();

        // 1. Re-parse
        let source = std::fs::read_to_string(changed).unwrap_or_default();
        let new_data = crate::extractor::parse_file(changed, &source);
        self.source_cache.insert(changed.to_owned(), new_data.clone());

        // 2. Patch global
        let old_global = self.global.load_full();
        let mut new_global = (*old_global).clone();
        new_global.remove_file(changed);
        new_global.merge(changed, new_data);
        let new_global = Arc::new(new_global);

        // 3. Find affected files
        let affected = self.reverse_deps.affected(changed);

        // 4. Re-resolve affected components
        let ctx = Arc::new(ResolutionContext::new(new_global.clone(), &self.options));

        let affected_mappings: Vec<ComponentMapping> = new_global.component_mappings
            .iter()
            .filter(|m| affected.contains(&m.file_path))
            .cloned()
            .collect();

        let results: Vec<(ComponentEntry, Vec<Diagnostic>)> = affected_mappings
            .par_iter()
            .map(|m| crate::resolver::resolve_component(m, &ctx))
            .collect();

        let mut updated_components = Vec::new();
        let mut diagnostics = Vec::new();

        for (entry, diags) in results {
            self.component_cache.insert(entry.display_name.clone(), entry.clone());
            updated_components.push(entry);
            diagnostics.extend(diags);
        }

        // 5. Atomic global swap
        self.global.store(new_global);

        IncrementalUpdate {
            updated_components,
            affected_files: affected.into_iter().collect(),
            diagnostics,
            duration_ms: start.elapsed().as_millis() as u64,
        }
    }
}
```

