### watch subcommand — uses watchexec 8.x and crossterm

```rust
#[derive(clap::Args)]
struct WatchArgs {
    #[arg(long, short, value_delimiter = ',')]
    src: Vec<String>,
    #[arg(long, short)]
    out: Option<String>,
}

fn cmd_watch(args: WatchArgs, quiet: bool, config_path: Option<&str>) -> Result<()> {
    use indicatif::{ProgressBar, ProgressStyle};
    use owo_colors::OwoColorize;

    let options = build_options(&args.src, false, None, None, config_path);

    if !quiet {
        println!();
        println!("  {}  {} watching {}  {}", 
            "⚡".yellow(),
            "oxc-react-docgen".bold(),
            options.src_dirs.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(", ").cyan(),
            "(press q to quit, r to re-extract)".dimmed()
        );
        println!();
    }

    // Initial extraction
    let pb = if !quiet {
        let pb = ProgressBar::new_spinner();
        pb.set_style(ProgressStyle::default_spinner()
            .template("{spinner:.cyan} {msg}").unwrap());
        pb.set_message("Extracting...");
        pb.enable_steady_tick(std::time::Duration::from_millis(80));
        Some(pb)
    } else { None };

    let session = std::sync::Arc::new(
        oxc_react_docgen_core::pipeline::WatchSession::new(options.clone())
    );
    let first = session.initialize();

    if let Some(ref pb) = pb { pb.finish_and_clear(); }
    if !quiet { print_summary(&first, quiet); }

    // Keyboard input thread (q=quit, r=re-extract)
    let running = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
    let running_clone = running.clone();
    let session_clone = session.clone();

    std::thread::spawn(move || {
        use crossterm::event::{self, Event, KeyCode};
        let _ = crossterm::terminal::enable_raw_mode();
        while running_clone.load(std::sync::atomic::Ordering::Relaxed) {
            if let Ok(Event::Key(key)) = event::read() {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Char('c') => {
                        let _ = crossterm::terminal::disable_raw_mode();
                        std::process::exit(0);
                    }
                    KeyCode::Char('r') => {
                        session_clone.initialize();
                    }
                    _ => {}
                }
            }
        }
        let _ = crossterm::terminal::disable_raw_mode();
    });

    // File watcher using watchexec 8.x
    let src_dirs: Vec<std::path::PathBuf> = options.src_dirs.iter()
        .map(|p| p.as_std_path().to_owned())
        .collect();

    // watchexec 8.x: use tokio runtime
    let rt = tokio::runtime::Runtime::new().into_diagnostic()?;
    rt.block_on(async move {
        use watchexec::Watchexec;

        let session_inner = session.clone();
        let quiet_inner = quiet;
        let out_path = args.out.clone();

        let wx = Watchexec::new_async(move |mut action| {
            let session = session_inner.clone();
            let out = out_path.clone();
            async move {
                for event in action.events.iter() {
                    for (path, _) in event.paths() {
                        let ext = path.extension()
                            .and_then(|e| e.to_str())
                            .unwrap_or("");
                        if !matches!(ext, "ts" | "tsx") { continue; }
                        if let Ok(utf8) = camino::Utf8PathBuf::from_path_buf(path.to_owned()) {
                            let update = session.update_file(&utf8);
                            if !quiet_inner {
                                use owo_colors::OwoColorize;
                                let names: Vec<_> = update.updated_components.iter()
                                    .map(|c| c.display_name.as_str())
                                    .collect();
                                if !names.is_empty() {
                                    println!("  {}  {}",
                                        utf8.file_name().unwrap_or("?").dimmed(),
                                        names.join(", ").bold()
                                    );
                                }
                            }
                            if let Some(ref p) = out {
                                // Write updated components to file
                                // (full re-extract needed for complete output)
                                let _ = std::fs::write(p, "{}");
                            }
                        }
                    }
                }
                action
            }
        }).await.into_diagnostic()?;

        wx.config.pathset(src_dirs);
        wx.main().await.into_diagnostic()??;
        Ok::<(), miette::Error>(())
    })?;

    running.store(false, std::sync::atomic::Ordering::Relaxed);
    Ok(())
}
