## Fix 3: Command injection in CLI config loading

In `crates/cli/src/main.rs`, the config path is interpolated directly into JS source code:

```rust
let script = format!(
    "import cfg from '{}'; process.stdout.write(JSON.stringify(cfg.default ?? cfg))",
    path.display()
);
```

Fix: pass the path as a CLI argument or environment variable, not embedded in the script:

```rust
fn try_load_config(path: &std::path::Path) -> Option<PipelineOptions> {
    // Pass the config path via environment variable to avoid JS injection
    let script = "import { pathToFileURL } from 'node:url'; \
                  const p = process.env.__DOCGEN_CONFIG_PATH; \
                  const cfg = (await import(pathToFileURL(p).href)); \
                  process.stdout.write(JSON.stringify(cfg.default ?? cfg));";

    let output = std::process::Command::new("node")
        .args(["--input-type=module"])
        .env("__DOCGEN_CONFIG_PATH", path)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null())
        .spawn()
        .ok()?
        .wait_with_output()  // This approach needs stdin write
        .ok()?;
    ...
}
```

Actually, since we pipe stdin, we need to write the script first. Use `std::process::Child` and write to stdin:

```rust
fn try_load_config(path: &std::path::Path) -> Option<PipelineOptions> {
    use std::io::Write;

    // Pass path via env var to prevent any path content from being interpreted as JS
    let script = "import { pathToFileURL } from 'node:url';\
        const p = process.env.__DOCGEN_CONFIG_PATH;\
        const m = await import(pathToFileURL(p).href);\
        process.stdout.write(JSON.stringify(m.default ?? m));";

    let mut child = std::process::Command::new("node")
        .args(["--input-type=module"])
        .env("__DOCGEN_CONFIG_PATH", path)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null())
        .spawn()
        .ok()?;

    child.stdin.as_mut()?.write_all(script.as_bytes()).ok()?;
    drop(child.stdin.take()); // close stdin to signal EOF

    let output = child.wait_with_output().ok()?;
    if !output.status.success() { return None; }

    // TODO: map JSON fields to PipelineOptions — returns None until implemented
    serde_json::from_slice::<serde_json::Value>(&output.stdout).ok()?;
    None
}
```

