4	//! Rules:
5	//! - `CompactString` for names/type strings (avoids heap alloc for short strings)
6	//! - `BTreeMap` for JSON-facing output (deterministic key ordering)
7	//! - `FxHashMap` for internal lookup maps (performance)
8	//! - All types are `Send + Sync` — required for rayon and NAPI
9	
10	use camino::{Utf8Path, Utf8PathBuf};
11	use compact_str::CompactString;
12	use rustc_hash::FxHashMap;
13	use serde::{Deserialize, Serialize};
14	use std::collections::BTreeMap;
15	
16	// ─── Type Aliases ────────────────────────────────────────────────────────────
17	
18	/// Compact string used for names, type strings — avoids heap alloc under 24 bytes
19	pub type TypeName = CompactString;
20	
21	// ─── CollectedType ───────────────────────────────────────────────────────────
22	
23	/// A structured representation of a TypeScript type as collected from the AST.
24	/// This is the extractor's output — NOT yet resolved to a semantic PropType.
25	/// The resolver pattern-matches on this to produce PropType.
26	#[derive(Debug, Clone)]
27	pub enum CollectedType {
28	    // ── Primitives
29	    String,
30	    Number,
31	    Boolean,
32	    Null,
33	    Undefined,
34	    Any,
35	    Never,
36	    Unknown,
37	    Void,
38	    BigInt,
39	    Symbol,
40	
41	    // ── Literals
42	    StringLiteral(CompactString),
43	    NumberLiteral(f64),
44	    BoolLiteral(bool),
45	
46	    // ── Structural
47	    Union(Vec<CollectedType>),
48	    Intersection(Vec<CollectedType>),
49	    Array(Box<CollectedType>),
50	    Tuple(Vec<CollectedType>),
51	    Object(Vec<CollectedObjectField>),
52	
53	    // ── Named type reference (possibly generic, possibly not yet resolved)
54	    Named {
55	        name: CompactString,
56	        args: Vec<CollectedType>,
57	    },
58	
59	    // ── `typeof X` — reference to the type of a value
60	    TypeOf(CompactString),
61	
62	    // ── Indexed access: Type["key"] or Type[K]
63	    IndexedAccess {
64	        obj: Box<CollectedType>,
65	        key: Box<CollectedType>,
66	    },
67	
68	    // ── Template literal: `compact-${Size}` → parts = [Str("compact-"), Named("Size", [])]
69	    TemplateLiteral(Vec<CollectedType>),
70	
71	    // ── Function type: (props: P) => ReactNode
72	    Function {
73	        params: Vec<CollectedType>,
74	        return_type: Box<CollectedType>,
75	    },
76	
77	    // ── Conditional: T extends U ? X : Y — cannot resolve statically, tag for typescript-go
78	    Conditional {
79	        check: Box<CollectedType>,
80	        extends_type: Box<CollectedType>,
81	        true_type: Box<CollectedType>,
82	        false_type: Box<CollectedType>,
83	    },
84	
85	    // ── Mapped: { [K in Keys]: Value } — cannot resolve statically
86	    Mapped {
87	        key_type: Box<CollectedType>,
88	        value_type: Box<CollectedType>,
89	    },
90	
91	    // ── Fallback for syntax we don't recognise
92	    Raw(String),
93	}
94	
95	impl CollectedType {
96	    /// True if this type requires the TypeScript type checker to resolve.
97	    pub fn needs_type_checker(&self) -> bool {
98	        matches!(self, CollectedType::Conditional { .. } | CollectedType::Mapped { .. })
99	    }
100	
101	    /// Produce a raw string representation for diagnostics and fallback display.
102	    pub fn to_raw_string(&self) -> String {
103	        match self {
104	            CollectedType::String => "string".into(),
105	            CollectedType::Number => "number".into(),
106	            CollectedType::Boolean => "boolean".into(),
107	            CollectedType::Null => "null".into(),
108	            CollectedType::Undefined => "undefined".into(),
109	            CollectedType::Any => "any".into(),
110	            CollectedType::Never => "never".into(),
111	            CollectedType::Unknown => "unknown".into(),
112	            CollectedType::Void => "void".into(),
113	            CollectedType::BigInt => "bigint".into(),
114	            CollectedType::Symbol => "symbol".into(),
115	            CollectedType::StringLiteral(s) => format!("\"{}\"", s),
116	            CollectedType::NumberLiteral(n) => n.to_string(),
117	            CollectedType::BoolLiteral(b) => b.to_string(),
118	            CollectedType::Union(members) => {
119	                members.iter().map(|m| m.to_raw_string()).collect::<Vec<_>>().join(" | ")
120	            }
121	            CollectedType::Intersection(members) => {
122	                members.iter().map(|m| m.to_raw_string()).collect::<Vec<_>>().join(" & ")
123	            }
124	            CollectedType::Array(inner) => format!("{}[]", inner.to_raw_string()),
125	            CollectedType::Named { name, args } if args.is_empty() => name.to_string(),
126	            CollectedType::Named { name, args } => format!(
127	                "{}<{}>",
128	                name,
129	                args.iter().map(|a| a.to_raw_string()).collect::<Vec<_>>().join(", ")
130	            ),
131	            CollectedType::TypeOf(name) => format!("typeof {}", name),
132	            CollectedType::IndexedAccess { obj, key } => {
133	                format!("{}[{}]", obj.to_raw_string(), key.to_raw_string())
134	            }
135	            CollectedType::TemplateLiteral(parts) => format!(
136	                "`{}`",
137	                parts
138	                    .iter()
139	                    .map(|p| match p {
140	                        CollectedType::StringLiteral(s) => s.to_string(),
141	                        other => format!("${{{}}}", other.to_raw_string()),
142	                    })
143	                    .collect::<Vec<_>>()
144	                    .join("")
145	            ),
146	            CollectedType::Function { params, return_type } => format!(
147	                "({}) => {}",
148	                params.iter().map(|p| p.to_raw_string()).collect::<Vec<_>>().join(", "),
149	                return_type.to_raw_string()
150	            ),
151	            CollectedType::Conditional { check, extends_type, true_type, false_type } => format!(
152	                "{} extends {} ? {} : {}",
153	                check.to_raw_string(),
154	                extends_type.to_raw_string(),
155	                true_type.to_raw_string(),
156	                false_type.to_raw_string()
157	            ),
158	            CollectedType::Mapped { key_type, value_type } => {
159	                format!("{{ [K in {}]: {} }}", key_type.to_raw_string(), value_type.to_raw_string())
160	            }
161	            CollectedType::Tuple(members) => format!(
162	                "[{}]",
163	                members.iter().map(|m| m.to_raw_string()).collect::<Vec<_>>().join(", ")
164	            ),
165	            CollectedType::Object(_) => "{ ... }".into(),
166	            CollectedType::Raw(s) => s.clone(),
167	        }
168	    }
169	
170	    fn to_json_value(&self) -> serde_json::Value {
171	        match self {
172	            // Primitives: serialize as short string tags
173	            CollectedType::String    => serde_json::json!("str"),
174	            CollectedType::Number    => serde_json::json!("num"),
175	            CollectedType::Boolean   => serde_json::json!("bool"),
176	            CollectedType::Null      => serde_json::json!("null"),
177	            CollectedType::Undefined => serde_json::json!("undef"),
178	            CollectedType::Any       => serde_json::json!("any"),
179	            CollectedType::Never     => serde_json::json!("never"),
180	            CollectedType::Unknown   => serde_json::json!("unknown"),
181	            CollectedType::Void      => serde_json::json!("void"),
182	            CollectedType::BigInt    => serde_json::json!("bigint"),
183	            CollectedType::Symbol    => serde_json::json!("symbol"),
184	            // Literals
185	            CollectedType::StringLiteral(s) => serde_json::json!({"sl": s.as_str()}),
186	            CollectedType::NumberLiteral(n) => serde_json::json!({"nl": n}),
187	            CollectedType::BoolLiteral(b)   => serde_json::json!({"bl": b}),
188	            // Named: {"n": name, "a": [args...]}
189	            CollectedType::Named { name, args } => serde_json::json!({
190	                "n": name.as_str(),
191	                "a": args.iter().map(|a| a.to_json_value()).collect::<Vec<_>>()
192	            }),
193	            // Union: {"u": [members...]}
194	            CollectedType::Union(members) => serde_json::json!({
195	                "u": members.iter().map(|m| m.to_json_value()).collect::<Vec<_>>()
196	            }),
197	            // Intersection: {"i": [members...]}
198	            CollectedType::Intersection(members) => serde_json::json!({
199	                "i": members.iter().map(|m| m.to_json_value()).collect::<Vec<_>>()
200	            }),
201	            // Array: {"arr": inner}
202	            CollectedType::Array(inner) => serde_json::json!({"arr": inner.to_json_value()}),
203	            // Tuple: {"tup": [members...]}
204	            CollectedType::Tuple(members) => serde_json::json!({
205	                "tup": members.iter().map(|m| m.to_json_value()).collect::<Vec<_>>()
206	            }),
207	            // Object: {"obj": [{name, t, req, desc}...]}
208	            CollectedType::Object(fields) => serde_json::json!({
209	                "obj": fields.iter().map(|f| serde_json::json!({
210	                    "name": f.name,
211	                    "t": f.collected_type.to_json_value(),
212	                    "req": f.required,
213	                    "desc": f.description,
214	                })).collect::<Vec<_>>()
215	            }),
216	            // TypeOf: {"to": name}
217	            CollectedType::TypeOf(name) => serde_json::json!({"to": name.as_str()}),
218	            // IndexedAccess: {"ia": {o, k}}
219	            CollectedType::IndexedAccess { obj, key } => serde_json::json!({
220	                "ia": {"o": obj.to_json_value(), "k": key.to_json_value()}
221	            }),
222	            // TemplateLiteral: {"tl": [parts...]}
223	            CollectedType::TemplateLiteral(parts) => serde_json::json!({
224	                "tl": parts.iter().map(|p| p.to_json_value()).collect::<Vec<_>>()
225	            }),
226	            // Function: {"fn": {p: [params], r: return_type}}
227	            CollectedType::Function { params, return_type } => serde_json::json!({
228	                "fn": {
229	                    "p": params.iter().map(|p| p.to_json_value()).collect::<Vec<_>>(),
230	                    "r": return_type.to_json_value()
231	                }
232	            }),
233	            // Conditional: {"cond": {c, e, t, f}}
234	            CollectedType::Conditional { check, extends_type, true_type, false_type } => serde_json::json!({
235	                "cond": {
236	                    "c": check.to_json_value(),
237	                    "e": extends_type.to_json_value(),
238	                    "t": true_type.to_json_value(),
239	                    "f": false_type.to_json_value(),
240	                }
241	            }),
242	            // Mapped: {"mapped": {k, v}}
243	            CollectedType::Mapped { key_type, value_type } => serde_json::json!({
244	                "mapped": {"k": key_type.to_json_value(), "v": value_type.to_json_value()}
245	            }),
246	            // Raw fallback: {"raw": s}
247	            CollectedType::Raw(s) => serde_json::json!({"raw": s}),
248	        }
249	    }
250	
251	    fn from_json_value(v: &serde_json::Value) -> Result<Self, String> {
252	        match v {
253	            serde_json::Value::String(s) => Ok(match s.as_str() {
254	                "str"     => CollectedType::String,
255	                "num"     => CollectedType::Number,
256	                "bool"    => CollectedType::Boolean,
257	                "null"    => CollectedType::Null,
258	                "undef"   => CollectedType::Undefined,
259	                "any"     => CollectedType::Any,
260	                "never"   => CollectedType::Never,
261	                "unknown" => CollectedType::Unknown,
262	                "void"    => CollectedType::Void,
263	                "bigint"  => CollectedType::BigInt,
264	                "symbol"  => CollectedType::Symbol,
265	                other     => CollectedType::Raw(other.to_string()),
266	            }),
267	            serde_json::Value::Object(map) => {
268	                if let Some(s) = map.get("sl").and_then(|v| v.as_str()) {
269	                    return Ok(CollectedType::StringLiteral(s.into()));
270	                }
271	                if let Some(n) = map.get("nl").and_then(|v| v.as_f64()) {
272	                    return Ok(CollectedType::NumberLiteral(n));
273	                }
274	                if let Some(b) = map.get("bl").and_then(|v| v.as_bool()) {
275	                    return Ok(CollectedType::BoolLiteral(b));
276	                }
277	                if let Some(name) = map.get("n").and_then(|v| v.as_str()) {
278	                    let args = map.get("a")
279	                        .and_then(|v| v.as_array())
280	                        .map(|arr| arr.iter().map(Self::from_json_value).collect::<Result<Vec<_>, _>>())
281	                        .unwrap_or(Ok(vec![]))?;
282	                    return Ok(CollectedType::Named { name: name.into(), args });
283	                }
284	                if let Some(arr) = map.get("u").and_then(|v| v.as_array()) {
285	                    return Ok(CollectedType::Union(
286	                        arr.iter().map(Self::from_json_value).collect::<Result<_, _>>()?
287	                    ));
288	                }
289	                if let Some(arr) = map.get("i").and_then(|v| v.as_array()) {
290	                    return Ok(CollectedType::Intersection(
291	                        arr.iter().map(Self::from_json_value).collect::<Result<_, _>>()?
292	                    ));
293	                }
294	                if let Some(inner) = map.get("arr") {
295	                    return Ok(CollectedType::Array(Box::new(Self::from_json_value(inner)?)));
296	                }
297	                if let Some(arr) = map.get("tup").and_then(|v| v.as_array()) {
298	                    return Ok(CollectedType::Tuple(
299	                        arr.iter().map(Self::from_json_value).collect::<Result<_, _>>()?
300	                    ));
301	                }
302	                if let Some(arr) = map.get("obj").and_then(|v| v.as_array()) {
303	                    let fields: Vec<CollectedObjectField> = arr.iter().map(|f| {
304	                        let o = f.as_object().ok_or_else(|| "expected object for field".to_string())?;
305	                        Ok(CollectedObjectField {
306	                            name: o.get("name").and_then(|v| v.as_str()).unwrap_or("").to_owned(),
307	                            collected_type: Self::from_json_value(o.get("t").unwrap_or(&serde_json::Value::Null))?,
308	                            required: o.get("req").and_then(|v| v.as_bool()).unwrap_or(false),
309	                            description: o.get("desc").and_then(|v| v.as_str()).unwrap_or("").to_owned(),
310	                        })
311	                    }).collect::<Result<_, String>>()?;
312	                    return Ok(CollectedType::Object(fields));
313	                }
314	                if let Some(name) = map.get("to").and_then(|v| v.as_str()) {
315	                    return Ok(CollectedType::TypeOf(name.into()));
316	                }
317	                if let Some(inner) = map.get("ia") {
318	                    let obj = Self::from_json_value(inner.get("o").unwrap_or(&serde_json::Value::Null))?;
319	                    let key = Self::from_json_value(inner.get("k").unwrap_or(&serde_json::Value::Null))?;
320	                    return Ok(CollectedType::IndexedAccess { obj: Box::new(obj), key: Box::new(key) });
321	                }
322	                if let Some(arr) = map.get("tl").and_then(|v| v.as_array()) {
323	                    return Ok(CollectedType::TemplateLiteral(
324	                        arr.iter().map(Self::from_json_value).collect::<Result<_, _>>()?
325	                    ));
326	                }
327	                if let Some(inner) = map.get("fn") {
328	                    let params = inner.get("p").and_then(|v| v.as_array())
329	                        .map(|arr| arr.iter().map(Self::from_json_value).collect::<Result<Vec<_>, _>>())
330	                        .unwrap_or(Ok(vec![]))?;
331	                    let rt = Self::from_json_value(inner.get("r").unwrap_or(&serde_json::Value::Null))?;
332	                    return Ok(CollectedType::Function { params, return_type: Box::new(rt) });
333	                }
334	                if let Some(inner) = map.get("cond") {
335	                    let check = Self::from_json_value(inner.get("c").unwrap_or(&serde_json::Value::Null))?;
336	                    let ext   = Self::from_json_value(inner.get("e").unwrap_or(&serde_json::Value::Null))?;
337	                    let tt    = Self::from_json_value(inner.get("t").unwrap_or(&serde_json::Value::Null))?;
338	                    let ft    = Self::from_json_value(inner.get("f").unwrap_or(&serde_json::Value::Null))?;
339	                    return Ok(CollectedType::Conditional {
340	                        check: Box::new(check),
341	                        extends_type: Box::new(ext),
342	                        true_type: Box::new(tt),
343	                        false_type: Box::new(ft),
344	                    });
345	                }
346	                if let Some(inner) = map.get("mapped") {
347	                    let k = Self::from_json_value(inner.get("k").unwrap_or(&serde_json::Value::Null))?;
348	                    let vt = Self::from_json_value(inner.get("v").unwrap_or(&serde_json::Value::Null))?;
349	                    return Ok(CollectedType::Mapped { key_type: Box::new(k), value_type: Box::new(vt) });
350	                }
351	                if let Some(s) = map.get("raw").and_then(|v| v.as_str()) {
352	                    return Ok(CollectedType::Raw(s.to_owned()));
353	                }
354	                // Unknown shape — fall back to raw
355	                Ok(CollectedType::Raw(v.to_string()))
356	            }
357	            _ => Ok(CollectedType::Raw(v.to_string())),
358	        }
359	    }
360	}
