362	impl serde::Serialize for CollectedType {
363	    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
364	        let v = self.to_json_value();
365	        v.serialize(serializer)
366	    }
367	}
