369	impl<'de> serde::Deserialize<'de> for CollectedType {
370	    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
371	        use serde::de::Error as _;
372	        let v = serde_json::Value::deserialize(deserializer)?;
373	        Self::from_json_value(&v).map_err(D::Error::custom)
374	    }
