722	impl PropType {
723	    fn to_tagged_value(&self) -> serde_json::Value {
724	        match self {
725	            // Unit variants (primitives)
726	            PropType::String    => serde_json::json!({"kind": "string"}),
727	            PropType::Number    => serde_json::json!({"kind": "number"}),
728	            PropType::Boolean   => serde_json::json!({"kind": "boolean"}),
729	            PropType::Null      => serde_json::json!({"kind": "null"}),
730	            PropType::Undefined => serde_json::json!({"kind": "undefined"}),
731	            PropType::Any       => serde_json::json!({"kind": "any"}),
732	            PropType::Never     => serde_json::json!({"kind": "never"}),
733	            PropType::Unknown   => serde_json::json!({"kind": "unknown"}),
734	            PropType::Void      => serde_json::json!({"kind": "void"}),
735	            PropType::ReactNode    => serde_json::json!({"kind": "reactNode"}),
736	            PropType::CssProperties => serde_json::json!({"kind": "cssProperties"}),
737	            PropType::ElementType  => serde_json::json!({"kind": "elementType"}),
738	            PropType::SxProps      => serde_json::json!({"kind": "sxProps"}),
739	            // Newtype/tuple variants — inner is not a map, so wrap as "0"
740	            PropType::StringLiteral(s) => serde_json::json!({"kind": "stringLiteral", "0": s}),
741	            PropType::NumberLiteral(n) => serde_json::json!({"kind": "numberLiteral", "0": n}),
742	            PropType::BoolLiteral(b)   => serde_json::json!({"kind": "boolLiteral", "0": b}),
743	            PropType::Union(members) => serde_json::json!({
744	                "kind": "union",
745	                "0": members.iter().map(|m| m.to_tagged_value()).collect::<Vec<_>>()
746	            }),
747	            PropType::Intersection(members) => serde_json::json!({
748	                "kind": "intersection",
749	                "0": members.iter().map(|m| m.to_tagged_value()).collect::<Vec<_>>()
750	            }),
751	            PropType::Array(inner) => serde_json::json!({
752	                "kind": "array",
753	                "0": inner.to_tagged_value()
754	            }),
755	            PropType::Tuple(members) => serde_json::json!({
756	                "kind": "tuple",
757	                "0": members.iter().map(|m| m.to_tagged_value()).collect::<Vec<_>>()
758	            }),
759	            PropType::Object(fields) => serde_json::json!({
760	                "kind": "object",
761	                "0": fields.iter().map(|f| serde_json::json!({
762	                    "name": f.name,
763	                    "propType": f.prop_type.to_tagged_value(),
764	                    "required": f.required,
765	                    "description": f.description,
766	                })).collect::<Vec<_>>()
767	            }),
768	            // Struct variants — fields merge directly with kind
769	            PropType::Named { name, args } => serde_json::json!({
770	                "kind": "named",
771	                "name": name.as_str(),
772	                "args": args.iter().map(|a| a.to_tagged_value()).collect::<Vec<_>>()
773	            }),
774	            PropType::EventHandler { event_type } => serde_json::json!({
775	                "kind": "eventHandler",
776	                "eventType": event_type
777	            }),
778	            PropType::Ref { element } => serde_json::json!({
779	                "kind": "ref",
780	                "element": element
781	            }),
782	            PropType::HtmlAttributes { element, omitted } => serde_json::json!({
783	                "kind": "htmlAttributes",
784	                "element": element,
785	                "omitted": omitted
786	            }),
787	            PropType::LiteralUnion { members, has_default } => serde_json::json!({
788	                "kind": "literalUnion",
789	                "members": members,
790	                "hasDefault": has_default
791	            }),
792	            PropType::Opaque { raw, reason } => {
793	                let reason_val = match reason {
794	                    OpaqueReason::ConditionalType => serde_json::json!({"type": "conditionalType"}),
795	                    OpaqueReason::MappedType => serde_json::json!({"type": "mappedType"}),
796	                    OpaqueReason::ModuleAugmentation => serde_json::json!({"type": "moduleAugmentation"}),
797	                    OpaqueReason::RuntimeDependent { function_name } => serde_json::json!({"type": "runtimeDependent", "functionName": function_name}),
798	                    OpaqueReason::UnresolvableImport { specifier } => serde_json::json!({"type": "unresolvableImport", "specifier": specifier}),
799	                    OpaqueReason::PandaCodegenMissing => serde_json::json!({"type": "pandaCodegenMissing"}),
800	                    OpaqueReason::DepthExceeded => serde_json::json!({"type": "depthExceeded"}),
801	                    OpaqueReason::IndexedAccess { expression } => serde_json::json!({"type": "indexedAccess", "expression": expression}),
802	                    OpaqueReason::TemplateLiteral { expression } => serde_json::json!({"type": "templateLiteral", "expression": expression}),
803	                };
804	                serde_json::json!({"kind": "opaque", "raw": raw, "reason": reason_val})
805	            }
806	        }
807	    }
808	
809	    fn from_tagged_value(v: &serde_json::Value) -> Result<Self, String> {
810	        let kind = v.get("kind").and_then(|k| k.as_str())
811	            .ok_or_else(|| "missing 'kind' field in PropType JSON".to_string())?;
812	        match kind {
813	            "string"    => Ok(PropType::String),
814	            "number"    => Ok(PropType::Number),
815	            "boolean"   => Ok(PropType::Boolean),
816	            "null"      => Ok(PropType::Null),
817	            "undefined" => Ok(PropType::Undefined),
818	            "any"       => Ok(PropType::Any),
819	            "never"     => Ok(PropType::Never),
820	            "unknown"   => Ok(PropType::Unknown),
821	            "void"      => Ok(PropType::Void),
822	            "reactNode" | "react_node" => Ok(PropType::ReactNode),
823	            "cssProperties" | "css_properties" => Ok(PropType::CssProperties),
824	            "elementType" | "element_type" => Ok(PropType::ElementType),
825	            "sxProps" | "sx_props" => Ok(PropType::SxProps),
826	            "stringLiteral" | "string_literal" => {
827	                let s = v["0"].as_str().unwrap_or("").to_owned();
828	                Ok(PropType::StringLiteral(s))
829	            }
830	            "numberLiteral" | "number_literal" => {
831	                let n = v["0"].as_f64().unwrap_or(0.0);
832	                Ok(PropType::NumberLiteral(n))
833	            }
834	            "boolLiteral" | "bool_literal" => {
835	                let b = v["0"].as_bool().unwrap_or(false);
836	                Ok(PropType::BoolLiteral(b))
837	            }
838	            "union" => {
839	                let members = v["0"].as_array()
840	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
841	                    .unwrap_or(Ok(vec![]))?;
842	                Ok(PropType::Union(members))
843	            }
844	            "intersection" => {
845	                let members = v["0"].as_array()
846	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
847	                    .unwrap_or(Ok(vec![]))?;
848	                Ok(PropType::Intersection(members))
849	            }
850	            "array" => {
851	                let inner = Self::from_tagged_value(&v["0"])?;
852	                Ok(PropType::Array(Box::new(inner)))
853	            }
854	            "tuple" => {
855	                let members = v["0"].as_array()
856	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
857	                    .unwrap_or(Ok(vec![]))?;
858	                Ok(PropType::Tuple(members))
859	            }
860	            "object" => {
861	                let fields = v["0"].as_array()
862	                    .map(|a| a.iter().map(|f| {
863	                        Ok(ObjectField {
864	                            name: f["name"].as_str().unwrap_or("").to_owned(),
865	                            prop_type: Self::from_tagged_value(&f["propType"])?,
866	                            required: f["required"].as_bool().unwrap_or(false),
867	                            description: f["description"].as_str().unwrap_or("").to_owned(),
868	                        })
869	                    }).collect::<Result<Vec<_>, String>>())
870	                    .unwrap_or(Ok(vec![]))?;
871	                Ok(PropType::Object(fields))
872	            }
873	            "named" => {
874	                let name = v["name"].as_str().unwrap_or("").into();
875	                let args = v["args"].as_array()
876	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
877	                    .unwrap_or(Ok(vec![]))?;
878	                Ok(PropType::Named { name, args })
879	            }
880	            "eventHandler" | "event_handler" => {
881	                let event_type = v["eventType"].as_str()
882	                    .or_else(|| v["event_type"].as_str())
883	                    .unwrap_or("").to_owned();
884	                Ok(PropType::EventHandler { event_type })
885	            }
886	            "ref" => {
887	                let element = v["element"].as_str().map(|s| s.to_owned());
888	                Ok(PropType::Ref { element })
889	            }
890	            "htmlAttributes" | "html_attributes" => {
891	                let element = v["element"].as_str().unwrap_or("div").to_owned();
892	                let omitted = v["omitted"].as_array()
893	                    .map(|a| a.iter().filter_map(|v| v.as_str()).map(|s| s.to_owned()).collect())
894	                    .unwrap_or_default();
895	                Ok(PropType::HtmlAttributes { element, omitted })
896	            }
897	            "literalUnion" | "literal_union" => {
898	                let members = v["members"].as_array()
899	                    .map(|a| a.iter().filter_map(|v| v.as_str()).map(|s| s.to_owned()).collect())
900	                    .unwrap_or_default();
901	                let has_default = v["hasDefault"].as_bool()
902	                    .or_else(|| v["has_default"].as_bool())
903	                    .unwrap_or(false);
904	                Ok(PropType::LiteralUnion { members, has_default })
905	            }
906	            "opaque" => {
907	                let raw = v["raw"].as_str().unwrap_or("").to_owned();
908	                let reason = match v["reason"]["type"].as_str().unwrap_or("depthExceeded") {
909	                    "conditionalType" => OpaqueReason::ConditionalType,
910	                    "mappedType" => OpaqueReason::MappedType,
911	                    "moduleAugmentation" => OpaqueReason::ModuleAugmentation,
912	                    "runtimeDependent" => OpaqueReason::RuntimeDependent {
913	                        function_name: v["reason"]["functionName"].as_str().unwrap_or("").to_owned(),
914	                    },
915	                    "unresolvableImport" => OpaqueReason::UnresolvableImport {
916	                        specifier: v["reason"]["specifier"].as_str().unwrap_or("").to_owned(),
917	                    },
918	                    "pandaCodegenMissing" => OpaqueReason::PandaCodegenMissing,
919	                    "indexedAccess" => OpaqueReason::IndexedAccess {
920	                        expression: v["reason"]["expression"].as_str().unwrap_or("").to_owned(),
921	                    },
922	                    "templateLiteral" => OpaqueReason::TemplateLiteral {
923	                        expression: v["reason"]["expression"].as_str().unwrap_or("").to_owned(),
924	                    },
925	                    _ => OpaqueReason::DepthExceeded,
926	                };
927	                Ok(PropType::Opaque { raw, reason })
928	            }
929	            other => Ok(PropType::Opaque {
930	                raw: format!("unknown PropType kind: {}", other),
931	                reason: OpaqueReason::DepthExceeded,
932	            }),
933	        }
934	    }
935	}
