940	        "input" => "Input",
941	        "textarea" => "Textarea",
942	        "select" => "Select",
943	        "a" => "Anchor",
944	        "form" => "Form",
945	        "label" => "Label",
946	        "img" => "Img",
947	        "div" | "span" | "p" | "h1" | "h2" | "h3" => "HTML",
948	        _ => "HTML",
949	    }
