399	            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
400	                formatter.write_str("struct CollectedObjectField")
401	            }
402	
403	            fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<CollectedObjectField, A::Error> {
404	                let mut name: Option<String> = None;
405	                let mut collected_type: Option<CollectedType> = None;
406	                let mut required: Option<bool> = None;
407	                let mut description: Option<String> = None;
408	
409	                while let Some(key) = map.next_key::<String>()? {
410	                    match key.as_str() {
411	                        "name" => { name = Some(map.next_value()?); }
412	                        "collected_type" => { collected_type = Some(map.next_value()?); }
413	                        "required" => { required = Some(map.next_value()?); }
414	                        "description" => { description = Some(map.next_value()?); }
415	                        _ => { let _ = map.next_value::<serde::de::IgnoredAny>()?; }
416	                    }
417	                }
418	
419	                Ok(CollectedObjectField {
420	                    name: name.ok_or_else(|| de::Error::missing_field("name"))?,
421	                    collected_type: collected_type.ok_or_else(|| de::Error::missing_field("collected_type"))?,
422	                    required: required.ok_or_else(|| de::Error::missing_field("required"))?,
423	                    description: description.ok_or_else(|| de::Error::missing_field("description"))?,
424	                })
425	            }
426	        }
427	
428	        deserializer.deserialize_struct(
429	            "CollectedObjectField",
430	            &["name", "collected_type", "required", "description"],
431	            FieldVisitor,
432	        )
433	    }
