557	
558	/// Semantic type of a prop. Rich enough to produce any output format.
559	/// Use match exhaustively — no `_` fallthrough in serializers.
560	#[derive(Debug, Clone, PartialEq)]
561	pub enum PropType {
562	    // ── Primitives
563	    String,
564	    Number,
565	    Boolean,
566	    Null,
567	    Undefined,
568	    Any,
569	    Never,
570	    Unknown,
571	    Void,
572	
573	    // ── Literals
574	    StringLiteral(String),
575	    NumberLiteral(f64),
576	    BoolLiteral(bool),
577	
578	    // ── Composites
579	    Union(Vec<PropType>),
580	    Intersection(Vec<PropType>),
581	    Array(Box<PropType>),
582	    Tuple(Vec<PropType>),
583	    Object(Vec<ObjectField>),
584	
585	    // ── Named reference (post-resolution)
586	    Named {
587	        name: TypeName,
588	        /// Generic args, already resolved to PropType
589	        args: Vec<PropType>,
590	    },
591	
592	    // ── React-specific terminals
593	    /// ReactNode, ReactElement, JSX.Element — all treated the same for docgen
594	    ReactNode,
595	    /// React.CSSProperties
596	    CssProperties,
597	    /// Event handler: (e: MouseEvent) => void etc.
598	    EventHandler {
599	        /// "MouseEvent", "ChangeEvent<HTMLInputElement>", etc.
600	        event_type: String,
601	    },
602	    /// Ref<T> / RefObject<T> / ForwardedRef<T>
603	    Ref {
604	        /// Inner element type if known
605	        element: Option<String>,
606	    },
607	    /// React.ElementType — component can render as any element
608	    /// Used for: `as?: ElementType`, `component?: ElementType`
609	    ElementType,
610	
611	    // ── HTML attribute inheritance
612	    /// All attributes of an HTML element, minus omitted keys.
613	    /// Produced when we see ComponentPropsWithoutRef<'button'> etc.
614	    HtmlAttributes {
615	        element: String,
616	        omitted: Vec<String>,
617	    },
618	
619	    // ── Variant systems (statically resolved)
620	    /// Result of CvaVariantPropsHandler — the wrapper is fully dissolved.
621	    /// Each member is a string literal value.
622	    LiteralUnion {
623	        members: Vec<String>,
624	        /// true if this prop has a defaultVariant
625	        has_default: bool,
626	    },
627	
628	    // ── Known opaque patterns (cannot/should not be expanded)
629	    /// MUI SxProps, SystemStyleObject etc. — complex, not user-facing props
630	    SxProps,
631	
632	    // ── Unresolvable — graceful degradation
633	    Opaque {
634	        /// Original type string as written in source
635	        raw: String,
636	        reason: OpaqueReason,
637	    },
638	}
