640	impl PropType {
641	    /// True if this type is a pure literal union (all members are literals).
642	    /// Used by serializers to choose between "enum" and "union" in RDT output.
643	    pub fn is_literal_union(&self) -> bool {
644	        match self {
645	            PropType::Union(members) => members.iter().all(|m| {
646	                matches!(
647	                    m,
648	                    PropType::StringLiteral(_)
649	                        | PropType::NumberLiteral(_)
650	                        | PropType::BoolLiteral(_)
651	                )
652	            }),
653	            PropType::LiteralUnion { .. } => true,
654	            _ => false,
655	        }
656	    }
657	
658	    /// Raw type string for display (e.g. in RDT PropItemType.raw)
659	    pub fn raw_string(&self) -> String {
660	        match self {
661	            PropType::String => "string".into(),
662	            PropType::Number => "number".into(),
663	            PropType::Boolean => "boolean".into(),
664	            PropType::Null => "null".into(),
665	            PropType::Undefined => "undefined".into(),
666	            PropType::Any => "any".into(),
667	            PropType::Never => "never".into(),
668	            PropType::Unknown => "unknown".into(),
669	            PropType::Void => "void".into(),
670	            PropType::StringLiteral(s) => format!("\"{}\"", s),
671	            PropType::NumberLiteral(n) => n.to_string(),
672	            PropType::BoolLiteral(b) => b.to_string(),
673	            PropType::Union(members) => {
674	                members.iter().map(|m| m.raw_string()).collect::<Vec<_>>().join(" | ")
675	            }
676	            PropType::Intersection(members) => {
677	                members.iter().map(|m| m.raw_string()).collect::<Vec<_>>().join(" & ")
678	            }
679	            PropType::Array(inner) => format!("{}[]", inner.raw_string()),
680	            PropType::Tuple(_) => "tuple".into(),
681	            PropType::Object(_) => "object".into(),
682	            PropType::LiteralUnion { members, .. } => {
683	                members.iter().map(|m| format!(r#""{}""#, m)).collect::<Vec<_>>().join(" | ")
684	            }
685	            PropType::Named { name, args } if args.is_empty() => name.to_string(),
686	            PropType::Named { name, args } => {
687	                let args_str =
688	                    args.iter().map(|a| a.raw_string()).collect::<Vec<_>>().join(", ");
689	                format!("{}<{}>", name, args_str)
690	            }
691	            PropType::ReactNode => "ReactNode".into(),
692	            PropType::CssProperties => "CSSProperties".into(),
693	            PropType::EventHandler { event_type } => {
694	                format!("({}: {}) => void", "e", event_type)
695	            }
696	            PropType::Ref { element: Some(e) } => format!("Ref<{}>", e),
697	            PropType::Ref { element: None } => "Ref<unknown>".into(),
698	            PropType::ElementType => "ElementType".into(),
699	            PropType::HtmlAttributes { element, .. } => {
700	                format!("{}HTMLAttributes", element_to_type_name(element))
701	            }
702	            PropType::SxProps => "SxProps".into(),
703	            PropType::Opaque { raw, .. } => raw.clone(),
704	        }
705	    }
706	}
