1272	impl GlobalSourceData {
1273	    /// Merge a single file's SourceData into the global data.
1274	    pub fn merge(&mut self, file_path: &Utf8Path, data: SourceData) {
1275	        for (key, iface) in data.interfaces {
1276	            match self.interfaces.entry(key) {
1277	                std::collections::hash_map::Entry::Occupied(mut e) => {
1278	                    // Declaration merging: combine props and extends
1279	                    let existing = e.get_mut();
1280	                    existing.props.extend(iface.props);
1281	                    existing.extends.extend(iface.extends);
1282	                }
1283	                std::collections::hash_map::Entry::Vacant(e) => {
1284	                    e.insert(iface);
1285	                }
1286	            }
1287	        }
1288	        self.type_aliases.extend(data.type_aliases);
1289	        self.enums.extend(data.enums);
1290	        self.import_map.insert(file_path.to_owned(), data.imports);
1291	        self.re_export_map.insert(file_path.to_owned(), data.exports);
1292	        self.component_mappings.extend(data.component_mappings);
1293	    }
1294	
1295	    /// Remove all entries contributed by `file_path`. Called before re-merging an updated file.
1296	    pub fn remove_file(&mut self, file_path: &Utf8Path) {
1297	        let prefix = format!("{}:", file_path);
1298	        self.interfaces.retain(|k, _| !k.starts_with(&prefix));
1299	        self.type_aliases.retain(|k, _| !k.starts_with(&prefix));
1300	        self.enums.retain(|k, _| !k.starts_with(&prefix));
1301	        self.import_map.remove(file_path);
1302	        self.re_export_map.remove(file_path);
1303	        self.component_mappings.retain(|m| m.file_path != file_path);
1304	    }
1305	}
