477	    /// Handle a single file change — re-resolve only affected components.
478	    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
479	        let start = Instant::now();
480	
481	        // 1. Re-parse the changed file.
482	        let source = std::fs::read_to_string(changed).unwrap_or_default();

483	        let new_data = crate::extractor::parse_file(changed, &source);
484	        self.source_cache.insert(changed.to_owned(), new_data.clone());
485	
486	        // 2. Patch GlobalSourceData atomically using rcu (read-copy-update).
487	        // rcu retries if the pointer was swapped by a concurrent update_file call,
488	        // preventing lost-update races under parallel file change events.
489	        let new_global = self.global.rcu(|old| {
