501	            .component_mappings
502	            .iter()
503	            .filter(|m| affected.contains(&m.file_path))
504	            .cloned()
505	            .collect();
506	
507	        let ctx = ResolutionContext::new(new_global.clone(), &self.options);
508	        let results: Vec<(ComponentEntry, Vec<Diagnostic>)> = affected_mappings
509	            .par_iter()
510	            .map(|m| resolve_component(m, &ctx))
511	            .collect();
512	
513	        let mut updated_components = Vec::new();
514	        let mut diagnostics = Vec::new();
515	
516	        for (entry, diags) in results {
517	            self.component_cache
518	                .insert(entry.display_name.clone(), entry.clone());
519	            updated_components.push(entry);
520	            diagnostics.extend(diags);
521	        }
522	
523	        IncrementalUpdate {
524	            updated_components,
525	            affected_files: affected.into_iter().collect(),
526	            diagnostics,
527	            duration_ms: start.elapsed().as_millis() as u64,
528	        }
