54	    pub fn build(global: &GlobalSourceData) -> Self {
55	        let mut bindings: FxHashMap<(Utf8PathBuf, CompactString), ImportRef> = FxHashMap::default();
56	        let mut wildcard_sources: FxHashMap<Utf8PathBuf, Vec<String>> = FxHashMap::default();
