72	impl GlobalSourceData {
73	    /// Merge a single file's SourceData into the global data.
74	    pub fn merge(&mut self, file_path: &Utf8Path, data: SourceData) {
75	        for (key, iface) in data.interfaces {
76	            match self.interfaces.entry(key) {
77	                std::collections::hash_map::Entry::Occupied(mut e) => {
78	                    // Declaration merging: combine props and extends
79	                    let existing = e.get_mut();
80	                    existing.props.extend(iface.props);
81	                    existing.extends.extend(iface.extends);
82	                }
83	                std::collections::hash_map::Entry::Vacant(e) => {
84	                    e.insert(iface);
85	                }
86	            }
87	        }
88	        self.type_aliases.extend(data.type_aliases);
89	        self.enums.extend(data.enums);
90	        self.import_map.insert(file_path.to_owned(), data.imports);
91	        self.re_export_map.insert(file_path.to_owned(), data.exports);
92	        self.component_mappings.extend(data.component_mappings);
93	    }
94	
95	    /// Remove all entries contributed by `file_path`. Called before re-merging an updated file.
96	    pub fn remove_file(&mut self, file_path: &Utf8Path) {
97	        let prefix = format!("{}:", file_path);
98	        self.interfaces.retain(|k, _| !k.starts_with(&prefix));
99	        self.type_aliases.retain(|k, _| !k.starts_with(&prefix));
100	        self.enums.retain(|k, _| !k.starts_with(&prefix));
101	        self.import_map.remove(file_path);
102	        self.re_export_map.remove(file_path);
103	        self.component_mappings.retain(|m| m.file_path != file_path);
104	    }
105	}
