    #[test]
    fn from_js_options_react_version() {
        let mut js = minimal_options();
        js.react_version = Some("react18".into());
        let opts = PipelineOptions::from(js);
        // We can't compare the react_version struct directly but we can verify
        // it parsed — if it panicked, the test would fail
        let _ = opts;
