1	/// Snapshot tests for extraction output.
2	///
3	/// These lock the exact JSON output for every fixture so that any refactor
4	/// step that accidentally changes observable behavior shows up immediately
5	/// as a snapshot diff rather than a silent regression.
6	///
7	/// To update snapshots after an intentional change:
8	///   INSTA_UPDATE=always cargo test -p oxc-react-docgen-core --test snapshots
9	///
10	/// To review pending snapshots interactively:
11	///   cargo insta review
12	use camino::Utf8PathBuf;
13	use oxc_react_docgen_core::pipeline::{extract, PipelineOptions};
14	
15	/// Absolute path to the workspace root, resolved from this crate's manifest dir.
16	fn workspace_root() -> Utf8PathBuf {
17	    let manifest = env!("CARGO_MANIFEST_DIR");
18	    // crates/core → workspace root is two levels up
19	    let root = std::path::Path::new(manifest).parent().unwrap().parent().unwrap();
20	    Utf8PathBuf::from_path_buf(root.to_owned()).unwrap()
21	}
22	
23	fn fixture_dir(library: &str) -> Utf8PathBuf {
24	    workspace_root().join("fixtures").join(library)
25	}
26	
27	fn run_fixture(library: &str) -> serde_json::Value {
28	    let dir = fixture_dir(library);
29	    let tsconfig = workspace_root().join("fixtures").join("tsconfig.json");
30	
31	    let options = PipelineOptions { src_dirs: vec![dir], tsconfig_path: Some(tsconfig), ..Default::default() };
32	
33	    let output = extract(&options);
34	
35	    // Serialize then deserialize to get a plain JSON value that insta can diff.
36	    let json_str = serde_json::to_string(&output).expect("extraction output must serialize");
37	    serde_json::from_str(&json_str).expect("round-trip must parse")
38	}
39	
40	/// Replace all absolute paths in the JSON value with `[PATH]`.
41	/// This makes snapshots portable across machines and directory layouts.
42	fn redact_paths(value: &mut serde_json::Value, workspace: &str) {
43	    match value {
44	        serde_json::Value::String(s) => {
45	            if s.contains(workspace) || s.starts_with('/') {
46	                // Keep the filename portion so snapshots are still readable.
47	                let trimmed = s.trim_start_matches(workspace).trim_start_matches('/').to_owned();
48	                *s = format!("[ROOT]/{trimmed}");
49	            }
50	        }
51	        serde_json::Value::Array(arr) => {
52	            for v in arr.iter_mut() {
53	                redact_paths(v, workspace);
54	            }
55	        }
56	        serde_json::Value::Object(map) => {
57	            for v in map.values_mut() {
58	                redact_paths(v, workspace);
59	            }
60	        }
61	        _ => {}
62	    }
63	}
64	
65	fn snapshot_fixture(library: &str) -> serde_json::Value {
66	    let mut value = run_fixture(library);
67	    let root = workspace_root();
68	    redact_paths(&mut value, root.as_str());
69	    // Zero out non-deterministic stats fields so snapshots don't flap.
70	    if let Some(stats) = value.get_mut("stats").and_then(|s| s.as_object_mut()) {
71	        stats.insert("durationMs".into(), serde_json::Value::Number(0.into()));
72	        stats.insert("dtsCacheHits".into(), serde_json::Value::Number(0.into()));
73	    }
74	    value
75	}
76	
77	// ── Per-library snapshot tests ────────────────────────────────────────────────
78	
79	#[test]
80	fn snapshot_shadcn() {
81	    let value = snapshot_fixture("shadcn");
82	    insta::assert_json_snapshot!(value);
83	}
84	
85	#[test]
86	fn snapshot_radix() {
87	    let value = snapshot_fixture("radix");
88	    insta::assert_json_snapshot!(value);
89	}
