3	use camino::Utf8Path;
4	use compact_str::CompactString;
5	
6	use crate::known::{resolve_known, KnownPatternResult};
7	use crate::react_types;
8	use crate::types::*;
9	
10	use super::alias::resolve_type_alias_type;
11	use super::collected::resolve_collected_type;
12	use super::import::resolve_to_canonical;
13	use super::react::react_type_to_prop_type;
14	use super::{ResolutionContext, MAX_DEPTH};
