16	#[allow(clippy::too_many_arguments)]
17	pub(super) fn resolve_named(
18	    name: &CompactString,
19	    args: &[CollectedType],
20	    consuming_file: &Utf8Path,
21	    ctx: &ResolutionContext,
22	    state: &mut ResolveState,
23	    depth: u8,
24	) -> PropType {
25	    if depth > MAX_DEPTH {
26	        state.diagnostics.push(Diagnostic {
27	            severity: DiagnosticSeverity::Warning,
28	            message: format!("Max resolution depth exceeded for named type '{}'", name),
29	            file: Some(consuming_file.to_string()),
30	            line: None,
31	            column: None,
32	            help: None,
33	            code: DiagnosticCode::MaxDepthExceeded,
34	        });
35	        return PropType::Opaque { raw: name.to_string(), reason: OpaqueReason::DepthExceeded };
36	    }
37	
38	    // ── 1. React builtin check ────────────────────────────────────────────────
39	    let lookup_name = name.strip_prefix("React.").unwrap_or(name.as_str());
40	    if react_types::is_react_builtin(lookup_name, &ctx.extra_builtins) {
41	        return react_type_to_prop_type(name.as_str(), args, consuming_file, ctx, state, depth);
42	    }
43	
44	    // Resolve type arguments eagerly — needed for both source lookups and known patterns.
45	    let resolved_args: Vec<PropType> =
46	        args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
47	
48	    // ── 2. Import resolution → canonical (file, name) ─────────────────────────
49	    // Check source-defined types BEFORE known library patterns so that user-defined
50	    // types like ThemingProps or StylesApiProps are never silently replaced by
51	    // opaque known-pattern shortcuts.
52	    let (canonical_file, canonical_name) =
53	        resolve_to_canonical(name.as_str(), consuming_file, ctx, &mut state.diagnostics)
54	            .unwrap_or_else(|| (consuming_file.to_owned(), name.to_string()));
55	
56	    let scoped_key = format!("{}:{}", canonical_file, canonical_name);
57	
58	    // ── 3. Type alias lookup ──────────────────────────────────────────────────
59	    if let Some(alias) = ctx.global.type_aliases.get(&scoped_key).cloned() {
60	        return resolve_type_alias_type(&alias, consuming_file, ctx, state, depth);

60	        return resolve_type_alias_type(&alias, consuming_file, ctx, state, depth);
61	    }
62	
63	    // ── 4. Interface lookup ───────────────────────────────────────────────────
64	    // At the prop-TYPE level (not chain level), an interface name is returned as Named.
65	    // Full prop expansion only happens at the component level via resolve_props_chain.
66	    if ctx.global.interfaces.contains_key(&scoped_key) {
67	        return PropType::Named { name: name.clone(), args: resolved_args };
68	    }
69	
70	    // ── 5. Known pattern check (fallback — only when not found in source) ─────
71	    // Library opaque patterns (ThemingProps, StylesApiProps, VariantProps, …) are
72	    // applied only when the type cannot be resolved from the project's own source.
73	    if let Some(result) = resolve_known(name.as_str(), &resolved_args, &ctx.global) {
74	        return match result {
75	            KnownPatternResult::Type(pt) => pt,
76	            KnownPatternResult::Alias { name: alias_name } => {
77	                // Follow the alias through resolve_named.
78	                let alias_ct = CollectedType::Named { name: alias_name.as_str().into(), args: vec![] };
79	                resolve_collected_type(&alias_ct, consuming_file, ctx, state, depth + 1)
80	            }
81	            KnownPatternResult::Props(_) => {
82	                // Props result at type level — surface as Named.
83	                PropType::Named { name: name.clone(), args: resolved_args }
84	            }
85	        };
86	    }
87	
88	    // ── 6. Silent no-op for well-known unresolvable types ────────────────────
89	    // TypeScript built-in utility types, DOM element types, and React HTML
90	    // attribute types all appear as prop types in real-world .d.ts files but
91	    // cannot be expanded without a type-checker. Return Named silently.
92	    let bare = name.strip_prefix("React.").unwrap_or(name.as_str());
93	    if matches!(
94	        bare,
95	        // TypeScript utility types
96	        "Partial" | "Required" | "Readonly" | "NonNullable" | "Record"
97	            | "ReadonlyArray" | "Array" | "Promise" | "Extract" | "Exclude"
98	            | "ReturnType" | "Parameters" | "Awaited" | "Omit" | "Pick"
99	            // TypeScript primitives used as type names
100	            | "object" | "Object" | "Function" | "Symbol" | "BigInt"
101	            // React HTML attribute types (not in is_react_builtin; appear as prop types)
102	            | "HTMLAttributes" | "InputHTMLAttributes" | "TextareaHTMLAttributes"
103	            | "SelectHTMLAttributes" | "ButtonHTMLAttributes" | "AnchorHTMLAttributes"
104	            | "FormHTMLAttributes" | "LabelHTMLAttributes" | "ImgHTMLAttributes"
105	            | "VideoHTMLAttributes" | "AudioHTMLAttributes" | "DOMAttributes"
106	            | "AriaAttributes" | "HTMLInputTypeAttribute" | "HTMLAttributeReferrerPolicy"
107	            | "HTMLAttributeAnchorTarget" | "HTMLInputAutoCompleteAttribute"
108	    ) || bare.ends_with("HTMLAttributes")
109	    {
110	        return PropType::Named { name: name.clone(), args: resolved_args };
111	    }
112	    // DOM element ref types (HTMLDivElement, HTMLInputElement, etc.)
113	    if bare.starts_with("HTML") && bare.ends_with("Element") {
114	        return PropType::Named { name: name.clone(), args: resolved_args };
115	    }
116	    if bare.starts_with("SVG") && bare.ends_with("Element") {
117	        return PropType::Named { name: name.clone(), args: resolved_args };
118	    }
