60	pub(super) fn resolve_typeof(
61	    name: &CompactString,
62	    consuming_file: &Utf8Path,
63	    ctx: &ResolutionContext,
64	    diagnostics: &mut Vec<Diagnostic>,
65	) -> PropType {
66	    // `typeof X` — look for X in global.enums (for cva() results).
67	    let found_enum =
68	        ctx.global.enums.iter().find(|(key, _)| key.ends_with(&format!(":{}", name)) || key.as_str() == name.as_str());
