70	    if found_enum.is_some() {
71	        // Has cva-like enum entries — the VariantProps<typeof X> pattern handles this.
72	        // At the type level, surface as Named.
73	        return PropType::Named { name: name.clone(), args: vec![] };
74	    }
75	
76	    diagnostics.push(Diagnostic {
77	        severity: DiagnosticSeverity::Info,
78	        message: format!("typeof '{}' in '{}' — could not statically evaluate", name, consuming_file),
79	        file: Some(consuming_file.to_string()),
80	        line: None,
81	        column: None,
82	        help: None,
83	        code: DiagnosticCode::OpaqueType,
84	    });
85	
86	    PropType::Named { name: name.clone(), args: vec![] }
87	}
