52	    // Not prop providers; suppress false "unresolvable" warnings.
53	    if matches!(
54	        type_name_bare,
55	        "Omit"
56	            | "Pick"
57	            | "Partial"
58	            | "Required"
59	            | "Readonly"
60	            | "NonNullable"
61	            | "ReturnType"
62	            | "Parameters"
63	            | "Awaited"
64	            | "Extract"
65	            | "Exclude"
66	            | "Record"
67	            | "ReadonlyArray"
68	            | "Array"
69	            | "Promise"
70	    ) {
71	        return ResolvedChain::default();
72	    }
73	
74	    // ── Step 2: Known pattern check (SxProps, VariantProps, ComponentProps…) ─
75	    // Run BEFORE is_react_builtin: some builtins (ComponentPropsWithoutRef,
76	    // PropsWithChildren, etc.) expand into props via known.rs and must NOT be
77	    // short-circuited as terminal types. resolve_known with the bare name handles
78	    // both "ComponentPropsWithoutRef" and "React.ComponentPropsWithoutRef".
79	    {
80	        let resolved_args: Vec<PropType> = type_args
81	            .iter()
82	            .map(|a| {
83	                let ct = CollectedType::Raw(a.clone());
84	                resolve_collected_type(&ct, consuming_file, ctx, state, depth + 1)
85	            })
86	            .collect();
87	
88	        if let Some(result) = resolve_known(type_name_bare, &resolved_args, &ctx.global) {
89	            return match result {
90	                KnownPatternResult::Props(props) => ResolvedChain { props, ..Default::default() },
91	                KnownPatternResult::Type(PropType::HtmlAttributes { element, omitted }) => {
92	                    // HtmlAttributes from ComponentPropsWithoutRef<'button'> or
93	                    // HTMLChakraProps<'button'> — record as InheritedLayer so
94	                    // notable_inherited can be synthesized from the element's attr table.
95	                    let layer = InheritedLayer {
96	                        type_name: type_name.to_owned(),
97	                        file_name: resolve_react_types_file(consuming_file, ctx),
98	                        omitted,
99	                        html_element: Some(element),
100	                        total_props: 0,
101	                    };
102	                    ResolvedChain { inheritance: vec![layer], ..Default::default() }
103	                }
104	                KnownPatternResult::Type(pt) => ResolvedChain::empty_with_compose(pt.raw_string()),
105	                KnownPatternResult::Alias { name } => {
106	                    resolve_props_chain(&name, &[], consuming_file, mapping, ctx, state, depth + 1)
107	                }
108	            };
109	        }
110	    }
111	
112	    // ── Step 2.5: React builtin check (after known patterns) ─────────────────
113	    // Terminal React types (ReactNode, Ref, FC, etc.) that survived the known-pattern
114	    // check are not prop providers — add to composes and stop.
115	    if react_types::is_react_builtin(type_name_bare, &ctx.extra_builtins) {
116	        return ResolvedChain::empty_with_compose(type_name.to_owned());
117	    }
118	
119	    // ── Step 3: Resolve import to canonical (file, name) ─────────────────────
120	    let (canonical_file, canonical_name) = resolve_to_canonical(type_name, consuming_file, ctx, &mut state.diagnostics)
121	        .unwrap_or_else(|| (consuming_file.to_owned(), type_name.to_owned()));
122	
123	    let scoped_key = format!("{}:{}", canonical_file, canonical_name);
124	
125	    // ── Step 4: Type alias (Omit, Pick, Partial, Union, etc.) ────────────────
126	    if let Some(alias) = ctx.global.type_aliases.get(&scoped_key).cloned() {
127	        return resolve_type_alias_chain(&alias, consuming_file, mapping, ctx, state, depth);
128	    }
129	
130	    // ── Step 5: Interface ─────────────────────────────────────────────────────
131	    if let Some(iface) = ctx.global.interfaces.get(&scoped_key).cloned() {
132	        return resolve_interface_chain(&iface, type_args, consuming_file, mapping, ctx, state, depth);
133	    }
134	
135	    // ── Step 6: Unresolvable ──────────────────────────────────────────────────
136	    state.diagnostics.push(Diagnostic {
137	        severity: DiagnosticSeverity::Warning,
138	        message: format!("Cannot resolve type '{}' in '{}' (scoped key: '{}')", type_name, consuming_file, scoped_key),
139	        file: Some(consuming_file.to_string()),
140	        line: None,
141	        column: None,
142	        help: Some(
143	            "Type may be in an unresolvable cross-package location. Check that the package is installed.".into(),
144	        ),
145	        code: DiagnosticCode::UnresolvableImport,
146	    });
147	    ResolvedChain::empty_with_compose(type_name.to_owned())
148	}
