150	/// Resolve an interface to a chain of props.
151	#[allow(clippy::too_many_arguments)]
152	pub(super) fn resolve_interface_chain(
153	    iface: &CollectedInterface,
154	    _type_args: &[String],
155	    _consuming_file: &Utf8Path,
156	    mapping: &ComponentMapping,
157	    ctx: &ResolutionContext,
158	    state: &mut ResolveState,
159	    depth: u8,
160	) -> ResolvedChain {
161	    let mut chain = ResolvedChain::default();
162	
163	    // ── Resolve extends first — parent props come before own props ────────────
164	    for extends_ref in &iface.extends {
165	        let (parent_chain, maybe_layer) =
166	            resolve_extends_ref(extends_ref, &iface.file_path, mapping, ctx, state, depth + 1);
167	        if let Some(layer) = maybe_layer {
168	            chain.inheritance.push(layer);
169	        }
170	        chain.merge_parent(parent_chain);
171	    }
172	
173	    // ── Resolve own props ────────────────────────────────────────────────────
174	    let parent_ref = Some(PropParent { name: iface.name.to_string(), file_name: iface.file_path.to_string() });
175	
176	    for raw_prop in &iface.props {
177	        let prop_type = resolve_collected_type(&raw_prop.collected_type, &iface.file_path, ctx, state, depth);
178	
179	        // Default value: code default takes precedence over JSDoc @default.
180	        let code_default = mapping.param_defaults.get(&raw_prop.name);
181	        let jsdoc_default =
182	            raw_prop.tags.get("default").or_else(|| raw_prop.tags.get("defaultValue")).map(|s| s.trim());
183	
184	        let default_value = match (code_default, jsdoc_default) {
185	            (Some(code), Some(jsdoc)) if code.value.trim_matches('"').trim_matches('\'') != jsdoc => {
186	                state.diagnostics.push(Diagnostic {
187	                    severity: DiagnosticSeverity::Info,
188	                    message: format!(
189	                        "JSDoc @default '{}' differs from code default '{}' for prop '{}' — using code value",
190	                        jsdoc, code.value, raw_prop.name
191	                    ),
192	                    file: Some(iface.file_path.to_string()),
193	                    line: None,
194	                    column: None,
195	                    help: Some("Update the JSDoc @default to match the code default.".into()),
196	                    code: DiagnosticCode::JsDocDefaultMismatch,
197	                });
198	                Some(DefaultValue { value: code.value.clone(), computed: code.computed })
199	            }
200	            (Some(code), _) => Some(DefaultValue { value: code.value.clone(), computed: code.computed }),
201	            (None, Some(jsdoc)) => Some(DefaultValue { value: jsdoc.to_owned(), computed: false }),
202	            (None, None) => None,
203	        };
204	
205	        chain.props.push(ParsedProp {
206	            name: raw_prop.name.clone(),
207	            prop_type,
208	            required: raw_prop.required,
209	            default_value,
210	            description: raw_prop.description.clone(),
211	            tags: raw_prop.tags.clone(),
212	            parent: parent_ref.clone(),
213	            declarations: vec![parent_ref.clone().unwrap()],
214	        });
215	    }
216	
217	    chain
218	}
