220	/// Find a discriminant prop — a prop that has a distinct string literal type across all members.
221	pub(super) fn find_discriminant_prop(members: &[(&str, Vec<ParsedProp>)]) -> Option<String> {
222	    if members.is_empty() {
223	        return None;
224	    }
225	
226	    let first_props = &members[0].1;
227	
228	    'outer: for prop in first_props {
229	        if !matches!(prop.prop_type, PropType::StringLiteral(_)) {
230	            continue;
231	        }
232	
233	        let mut literal_values: Vec<&str> = Vec::new();
234	        for (_, member_props) in members {
235	            let found = member_props.iter().find(|p| p.name == prop.name);
236	            match found {
237	                Some(p) => {
238	                    if let PropType::StringLiteral(ref s) = p.prop_type {
239	                        if literal_values.contains(&s.as_str()) {
240	                            // Not distinct — try next prop.
241	                            continue 'outer;
242	                        }
243	                        literal_values.push(s.as_str());
244	                    } else {
245	                        continue 'outer; // Not a literal in this member.
246	                    }
247	                }
248	                None => continue 'outer, // Not present in all members.
249	            }
250	        }
251	
252	        if literal_values.len() == members.len() {
253	            return Some(prop.name.clone());
254	        }
255	    }
256	
257	    None
258	}
