107	    pub(super) fn classify_extends(&self, name: &str, type_args: Vec<String>) -> ExtendsRef {
108	        // Strip "React." prefix for lookup in builtin tables
109	        let lookup_name = name.strip_prefix("React.").unwrap_or(name);
110	
111	        if let Some(element) = crate::react_types::html_element_for(lookup_name) {
112	            return ExtendsRef::Builtin { name: name.into(), element: Some(element.to_owned()), type_args };
113	        }
114	        if crate::react_types::is_react_builtin(lookup_name, &rustc_hash::FxHashSet::default()) {
115	            return ExtendsRef::Builtin { name: name.into(), element: None, type_args };
116	        }
117	        // Check if imported
118	        if self.imported_names.contains(name) {
119	            return ExtendsRef::Imported {
120	                local_name: name.into(),
121	                type_args,
122	                source_specifier: self.find_import_specifier(name),
123	            };
124	        }
125	        ExtendsRef::SameFile { name: name.into(), type_args }
126	    }
