130	    pub(super) fn ts_type_name_str<'a>(&self, name: &TSTypeName<'a>) -> String {
131	        match name {
132	            TSTypeName::IdentifierReference(id) => id.name.as_str().to_owned(),
133	            TSTypeName::QualifiedName(q) => {
134	                format!("{}.{}", self.ts_type_name_str(&q.left), q.right.name.as_str())
135	            }
136	            TSTypeName::ThisExpression(_) => "this".to_owned(),
137	        }
138	    }
