140	    // ─── TSTypeParameterInstantiation → Vec<String> ──────────────────────────
141	
142	    pub(super) fn extract_type_args<'a>(
143	        &self,
144	        type_params: &Option<OxcBox<'a, TSTypeParameterInstantiation<'a>>>,
145	    ) -> Vec<String> {
146	        match type_params {
147	            Some(tp) => tp.params.iter().map(|p| self.ts_type_to_collected(p).to_raw_string()).collect(),
148	            None => vec![],
149	        }
150	    }
151	
152	    // ─── TSType → CollectedType ───────────────────────────────────────────────
153	
154	    pub(super) fn ts_type_to_collected<'a>(&self, ty: &TSType<'a>) -> CollectedType {
155	        match ty {
156	            TSType::TSStringKeyword(_) => CollectedType::String,
157	            TSType::TSNumberKeyword(_) => CollectedType::Number,
158	            TSType::TSBooleanKeyword(_) => CollectedType::Boolean,
159	            TSType::TSNullKeyword(_) => CollectedType::Null,
160	            TSType::TSUndefinedKeyword(_) => CollectedType::Undefined,
161	            TSType::TSAnyKeyword(_) => CollectedType::Any,
162	            TSType::TSNeverKeyword(_) => CollectedType::Never,
163	            TSType::TSUnknownKeyword(_) => CollectedType::Unknown,
164	            TSType::TSVoidKeyword(_) => CollectedType::Void,
165	            TSType::TSBigIntKeyword(_) => CollectedType::BigInt,
166	            TSType::TSSymbolKeyword(_) => CollectedType::Symbol,

218	            }
219	
220	            TSType::TSFunctionType(f) => {
221	                // In OXC 0.135, FormalParameter has type_annotation as a separate field
222	                let params: Vec<CollectedType> = f
223	                    .params
224	                    .items
225	                    .iter()
226	                    .map(|p| {
227	                        p.type_annotation
228	                            .as_ref()
229	                            .map(|ta| self.ts_type_to_collected(&ta.type_annotation))
230	                            .unwrap_or(CollectedType::Any)
231	                    })
232	                    .collect();
233	                // return_type on TSFunctionType is Box<TSTypeAnnotation> (not Option)
234	                let return_type = self.ts_type_to_collected(&f.return_type.type_annotation);
235	                CollectedType::Function { params, return_type: Box::new(return_type) }
236	            }
237	
238	            TSType::TSIndexedAccessType(ia) => CollectedType::IndexedAccess {
239	                obj: Box::new(self.ts_type_to_collected(&ia.object_type)),
240	                key: Box::new(self.ts_type_to_collected(&ia.index_type)),
241	            },
242

95	        // TypeScript utility types
96	        "Partial" | "Required" | "Readonly" | "NonNullable" | "Record"
97	            | "ReadonlyArray" | "Array" | "Promise" | "Extract" | "Exclude"
98	            | "ReturnType" | "Parameters" | "Awaited" | "Omit" | "Pick"
99	            // TypeScript primitives used as type names
100	            | "object" | "Object" | "Function" | "Symbol" | "BigInt"
101	            // React HTML attribute types (not in is_react_builtin; appear as prop types)
102	            | "HTMLAttributes" | "InputHTMLAttributes" | "TextareaHTMLAttributes"
103	            | "SelectHTMLAttributes" | "ButtonHTMLAttributes" | "AnchorHTMLAttributes"
104	            | "FormHTMLAttributes" | "LabelHTMLAttributes" | "ImgHTMLAttributes"
105	            | "VideoHTMLAttributes" | "AudioHTMLAttributes" | "DOMAttributes"
106	            | "AriaAttributes" | "HTMLInputTypeAttribute" | "HTMLAttributeReferrerPolicy"
107	            | "HTMLAttributeAnchorTarget" | "HTMLInputAutoCompleteAttribute"
108	    ) || bare.ends_with("HTMLAttributes")
109	    {
110	        return PropType::Named { name: name.clone(), args: resolved_args };
111	    }
112	    // DOM element ref types (HTMLDivElement, HTMLInputElement, etc.)
113	    if bare.starts_with("HTML") && bare.ends_with("Element") {
114	        return PropType::Named { name: name.clone(), args: resolved_args };
115	    }
116	    if bare.starts_with("SVG") && bare.ends_with("Element") {
117	        return PropType::Named { name: name.clone(), args: resolved_args };
118	    }
119	
120	    // ── 7. Unresolvable — emit diagnostic, return Named ───────────────────────
121	    state.diagnostics.push(Diagnostic {
122	        severity: DiagnosticSeverity::Warning,
123	        message: format!("Cannot resolve type '{}' in '{}' — it will appear as opaque", name, consuming_file),
124	        file: Some(consuming_file.to_string()),
125	        line: None,
126	        column: None,
127	        help: Some("Check that the package is installed and its types are resolvable.".into()),
128	        code: DiagnosticCode::UnresolvableImport,
129	    });
130	    PropType::Named { name: name.clone(), args: resolved_args }
131	}
