14	/// Resolve a `CollectedTypeAlias` as a props chain.
15	#[allow(clippy::too_many_arguments)]
16	pub(super) fn resolve_type_alias_chain(
17	    alias: &CollectedTypeAlias,
18	    _consuming_file: &Utf8Path,
19	    mapping: &ComponentMapping,
20	    ctx: &ResolutionContext,
21	    state: &mut ResolveState,
22	    depth: u8,
23	) -> ResolvedChain {
24	    match alias {
25	        CollectedTypeAlias::Passthrough { target, file_path } => match target {
26	            CollectedType::Named { name, args } => {
27	                let raw_args: Vec<String> = args.iter().map(|a| a.to_raw_string()).collect();
28	                resolve_props_chain(name.as_str(), &raw_args, file_path, mapping, ctx, state, depth + 1)
29	            }
30	            _ => ResolvedChain::default(),
31	        },
32	
33	        CollectedTypeAlias::Omit { base, omitted_keys, file_path } => {
34	            // Resolve the base type first, then remove omitted keys.
35	            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
36	            let omitted_set: FxHashSet<&str> = omitted_keys.iter().map(|k| k.as_str()).collect();
37	            chain.props.retain(|p| !omitted_set.contains(p.name.as_str()));
38	            // Record omitted keys in the relevant inheritance layer.
39	            for layer in &mut chain.inheritance {
40	                for key in omitted_keys {
41	                    if !layer.omitted.contains(key) {
42	                        layer.omitted.push(key.clone());
43	                    }
44	                }
45	            }
46	            chain
47	        }
48	
49	        CollectedTypeAlias::Pick { base, picked_keys, file_path } => {
50	            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
51	            let picked_set: FxHashSet<&str> = picked_keys.iter().map(|k| k.as_str()).collect();
52	            chain.props.retain(|p| picked_set.contains(p.name.as_str()));
53	            chain
54	        }
55	
56	        CollectedTypeAlias::Partial { base, file_path } => {
57	            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
58	            // Make all props optional.
59	            for prop in &mut chain.props {
60	                prop.required = false;
61	            }
62	            chain
63	        }
64	
65	        CollectedTypeAlias::Required { base, file_path } => {
66	            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
67	            // Make all props required.
68	            for prop in &mut chain.props {
69	                prop.required = true;
70	            }
71	            chain
72	        }
73	
74	        CollectedTypeAlias::Union { members, file_path } => {
75	            // Discriminated union — try to find the discriminant and merge all members.
76	            resolve_union_alias(members, file_path, mapping, ctx, state, depth)
77	        }
78	
79	        CollectedTypeAlias::Intersection { members, file_path } => {
80	            // Merge all members' props.
81	            let mut chain = ResolvedChain::default();
82	            for member in members {
83	                let member_chain = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
84	                chain.merge_parent(member_chain);
85	            }
86	            chain
87	        }
88	
89	        CollectedTypeAlias::LiteralUnion { .. } => {
90	            // Pure string union used as a type alias — not a props provider.
91	            ResolvedChain::default()
92	        }
93	    }
94	}
