141	/// Resolve a `CollectedTypeAlias::Union` — detect discriminated union if possible.
142	#[allow(clippy::too_many_arguments)]
143	pub(super) fn resolve_union_alias(
144	    members: &[CollectedType],
145	    file_path: &Utf8Path,
146	    mapping: &ComponentMapping,
147	    ctx: &ResolutionContext,
148	    state: &mut ResolveState,
149	    depth: u8,
150	) -> ResolvedChain {
151	    use super::chain::find_discriminant_prop;
152	
153	    // Collect all member chains for named types (only Named can be discriminated).
154	    let named_members: Vec<(&str, Vec<ParsedProp>)> = members
155	        .iter()
156	        .filter_map(|m| {
157	            if let CollectedType::Named { name, .. } = m {
158	                let mut branch_state = ResolveState { visited: state.visited.clone(), diagnostics: vec![] };
159	                let chain =
160	                    resolve_props_chain(name.as_str(), &[], file_path, mapping, ctx, &mut branch_state, depth + 1);
161	                state.diagnostics.extend(branch_state.diagnostics);
162	                Some((name.as_str(), chain.props))
163	            } else {
164	                None
165	            }
166	        })
167	        .collect();
168	
169	    if named_members.len() < 2 {
170	        // Not a discriminated union — just merge all.
171	        let mut chain = ResolvedChain::default();
172	        for member in members {
173	            let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
174	            chain.merge_parent(sub);
175	        }
176	        return chain;
177	    }
178	
179	    // Try to find a discriminant prop (a prop whose type is a distinct string literal across all members).
180	    let discriminant = find_discriminant_prop(&named_members);
181	
182	    // Merge all props from all members.
183	    let mut merged_props: BTreeMap<String, ParsedProp> = BTreeMap::new();
184	    for (_, member_props) in &named_members {
185	        for prop in member_props {
186	            merged_props.entry(prop.name.clone()).or_insert_with(|| prop.clone());
187	        }
188	    }
189	
190	    // If we found a discriminant, merge its type as a union of all its literal values.
191	    if let Some(ref disc_name) = discriminant {
192	        let disc_literals: Vec<PropType> = named_members
193	            .iter()
194	            .filter_map(|(_, props)| props.iter().find(|p| &p.name == disc_name).map(|p| p.prop_type.clone()))
195	            .collect();
196	
197	        if let Some(disc_prop) = merged_props.get_mut(disc_name) {
198	            disc_prop.prop_type = PropType::Union(disc_literals);
199	        }
200	    }
201	
202	    // Emit discriminated union diagnostic if applicable.
203	    if discriminant.is_some() {
204	        state.diagnostics.push(Diagnostic {
205	            severity: DiagnosticSeverity::Info,
206	            message: format!(
207	                "Discriminated union detected with discriminant prop '{}'",
208	                discriminant.as_deref().unwrap_or("")
209	            ),
210	            file: Some(file_path.to_string()),
211	            line: None,
212	            column: None,
213	            help: None,
214	            code: DiagnosticCode::DiscriminatedUnion,
215	        });
216	    }
217	
218	    ResolvedChain { props: merged_props.into_values().collect(), discriminant_prop: discriminant, ..Default::default() }
219	}
