96	/// Resolve a `CollectedType` as a props chain (for base types in aliases).
97	pub(super) fn resolve_base_as_chain(
98	    base: &CollectedType,
99	    file_path: &Utf8Path,
100	    mapping: &ComponentMapping,
101	    ctx: &ResolutionContext,
102	    state: &mut ResolveState,
103	    depth: u8,
104	) -> ResolvedChain {
105	    match base {
106	        CollectedType::Named { name, args } => {
107	            let raw_args: Vec<String> = args.iter().map(|a| a.to_raw_string()).collect();
108	            resolve_props_chain(name.as_str(), &raw_args, file_path, mapping, ctx, state, depth + 1)
109	        }
110	        CollectedType::Intersection(members) => {
111	            let mut chain = ResolvedChain::default();
112	            for member in members {
113	                let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
114	                chain.merge_parent(sub);
115	            }
116	            chain
117	        }
118	        CollectedType::Object(fields) => {
119	            // Inline object type in an intersection: `ComponentPropsWithoutRef<'button'> & { asChild?: boolean }`
120	            // Expand the object fields directly as own props.
121	            let mut chain = ResolvedChain::default();
122	            for field in fields {
123	                let prop_type = resolve_collected_type(&field.collected_type, file_path, ctx, state, depth);
124	                chain.props.push(ParsedProp {
125	                    name: field.name.clone(),
126	                    prop_type,
127	                    required: field.required,
128	                    default_value: None,
129	                    description: field.description.clone(),
130	                    tags: Default::default(),
131	                    parent: None,
132	                    declarations: vec![],
133	                });
134	            }
135	            chain
136	        }
137	        _ => ResolvedChain::default(),
138	    }
139	}

