7	impl<'src> SourceDataCollector<'src> {
8	    // ─── JSDoc extraction ─────────────────────────────────────────────────────
9	
10	    /// Find JSDoc comment immediately preceding the given byte offset.
11	    /// Returns empty string if none found.
12	    pub(super) fn find_jsdoc(&self, span_start: u32) -> String {
13	        const PROXIMITY_THRESHOLD: u32 = 120; // bytes — enough for blank lines + decorator
14	
15	        let comment = self
16	            .comments
17	            .iter()
18	            .rev()
19	            .find(|c| c.is_block && c.span_end <= span_start && span_start - c.span_end <= PROXIMITY_THRESHOLD);
20	
21	        match comment {
22	            Some(c) => {
23	                let raw = &self.source[c.span_start as usize..c.span_end as usize];
24	                parse_jsdoc_text(raw)
25	            }
26	            None => String::new(),
27	        }
28	    }
29	
30	    /// Extract JSDoc @tags from the comment preceding the given byte offset.
31	    pub(super) fn extract_jsdoc_tags(&self, span_start: u32) -> BTreeMap<String, String> {
32	        const PROXIMITY_THRESHOLD: u32 = 120;
33	
34	        let comment = self
35	            .comments
36	            .iter()
37	            .rev()
38	            .find(|c| c.is_block && c.span_end <= span_start && span_start - c.span_end <= PROXIMITY_THRESHOLD);
39	
40	        match comment {
41	            Some(c) => {
42	                let raw = &self.source[c.span_start as usize..c.span_end as usize];
43	                extract_jsdoc_tags(raw)
44	            }
45	            None => BTreeMap::new(),
46	        }
47	    }
48	}
49	
50	// ─── JSDoc parsing ────────────────────────────────────────────────────────────
51	
52	pub(super) fn parse_jsdoc_text(raw: &str) -> String {
53	    // Strip `/**` prefix and `*/` suffix
54	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
55	
56	    let desc_lines: Vec<&str> = inner
57	        .lines()
58	        .map(|l| {
59	            let l = l.trim();
60	            // Strip leading `* ` or `*`
61	            let l = l.strip_prefix("* ").or_else(|| l.strip_prefix('*')).unwrap_or(l);
62	            l
63	        })
64	        .take_while(|l| !l.starts_with('@'))
65	        .collect();
66	
67	    desc_lines.join("\n").trim().to_owned()
68	}
69	
70	pub(super) fn extract_jsdoc_tags(raw: &str) -> BTreeMap<String, String> {
71	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
72	    let mut tags: BTreeMap<String, String> = BTreeMap::new();
73	    let mut in_tags = false;
74	
75	    for line in inner.lines() {
76	        let line = line.trim();
77	        let line = line.strip_prefix("* ").or_else(|| line.strip_prefix('*')).unwrap_or(line);
78	        let line = line.trim();
79	
80	        if let Some(rest) = line.strip_prefix('@') {
81	            in_tags = true;
82	            // Parse tag: `@tagname rest`
83	            let (tag, value) = if let Some(sp) = rest.find(char::is_whitespace) {
84	                let tag = &rest[..sp];
85	                let value = rest[sp..].trim();
86	                (tag, value)
87	            } else {
88	                (rest, "")
89	            };
90	
91	            // Special handling for @param — store as `param:propName`
92	            if tag == "param" {
93	                // `@param propName description` or `@param {type} propName description`
94	                let value = value.trim_start_matches('{');
95	                // Skip {type} if present
96	                let value =
97	                    if value.contains('}') { value.split_once('}').map(|x| x.1).unwrap_or("").trim() } else { value };
98	                // First word is the prop name
99	                if let Some(space) = value.find(char::is_whitespace) {
100	                    let prop_name = &value[..space];
101	                    let desc = value[space..].trim();
102	                    tags.insert(format!("param:{}", prop_name), desc.to_owned());
103	                } else if !value.is_empty() {
104	                    tags.insert(format!("param:{}", value), String::new());
105	                }
106	            } else {
107	                tags.insert(tag.to_owned(), value.to_owned());
108	            }
109	        } else if in_tags && !line.is_empty() {
110	            // Continuation of a tag — ignore for now
111	        }
112	    }
113	
114	    tags
115	}
