12 │ /// Resolve a single `ExtendsRef` and return `(chain, Option<InheritedLayer>)`.
13 │ #[allow(clippy::too_many_arguments)]
14 │ pub(super) fn resolve_extends_ref(
15 │     extends_ref: &ExtendsRef,
16 │     iface_file: &Utf8Path,
17 │     mapping: &ComponentMapping,
18 │     ctx: &ResolutionContext,
19 │     state: &mut ResolveState,
20 │     depth: u8,
21 │ ) -> (ResolvedChain, Option<InheritedLayer>) {
22 │     match extends_ref {
23 │         ExtendsRef::Builtin { name, element, type_args } => {
24 │             // HTML element attrs — the actual props are not resolved here
25 │             // (they live in @types/react); we record an InheritedLayer instead.
26 │             if let Some(element_name) = element {
27 │                 let layer = InheritedLayer {
28 │                     type_name: name.to_string(),
29 │                     file_name: resolve_react_types_file(iface_file, ctx),
30 │                     omitted: vec![],
31 │                     html_element: Some(element_name.clone()),
32 │                     total_props: 0, // unknown without type-checker
33 │                 };
34 │                 (ResolvedChain::default(), Some(layer))
35 │             } else {
36 │                 // Non-HTML-element builtins. ComponentPropsWithoutRef/ComponentProps:
37 │                 // expand directly to HtmlAttributes based on the first type arg.
38 │                 let bare = name.as_str().strip_prefix("React.").unwrap_or(name.as_str());
39 │                 if matches!(bare, "ComponentPropsWithoutRef" | "ComponentPropsWithRef" | "ComponentProps") {
40 │                     if let Some(raw_arg) = type_args.first() {
41 │                         let inner = raw_arg.trim().trim_matches('"').trim_matches('\'');
42 │                         if !inner.is_empty() {
43 │                             let layer = InheritedLayer {
44 │                                 type_name: name.to_string(),
45 │                                 file_name: resolve_react_types_file(iface_file, ctx),
46 │                                 omitted: vec![],
47 │                                 html_element: Some(inner.to_lowercase()),
48 │                                 total_props: 0,
49 │                             };
50 │                             return (
51 │                                 ResolvedChain { inheritance: vec![layer.clone()], ..Default::default() },
52 │                                 Some(layer),
53 │                             );
54 │                         }
55 │                     }
56 │                 }
57 │                 // Other non-HTML builtins (PropsWithChildren, ElementRef, etc.)
58 │                 // — resolve through the chain so resolve_known can handle them.
59 │                 let chain = resolve_props_chain(name.as_str(), type_args, iface_file, mapping, ctx, state, depth);
60 │                 (chain, None)
61 │             }
62 │         }
63 │ 
64 │         ExtendsRef::SameFile { name, type_args } => {
65 │             let chain = resolve_props_chain(name.as_str(), type_args, iface_file, mapping, ctx, state, depth);
66 │             (chain, None)
67 │         }
68 │ 
69 │         ExtendsRef::Imported { local_name, type_args, source_specifier } => {
70 │             let resolved_file = source_specifier
71 │                 .as_deref()
72 │                 .and_then(|spec| resolve_import_specifier(spec, iface_file, ctx, &mut state.diagnostics))
73 │                 .unwrap_or_else(|| iface_file.to_owned());
74 │ 
75 │             let chain = resolve_props_chain(local_name.as_str(), type_args, &resolved_file, mapping, ctx, state, depth);
76 │             (chain, None)
77 │         }
78 │     }
79 │ }

