  2 │ 
  3 │ use std::collections::BTreeMap;
  4 │ 
  5 │ use camino::Utf8Path;
  6 │ use rustc_hash::FxHashSet;
  7 │ 
  8 │ use crate::types::*;
  9 │ 
 10 │ use super::chain::resolve_props_chain;
 11 │ use super::collected::resolve_collected_type;
 12 │ use super::{ResolutionContext, ResolvedChain};
 13 │ 
 14 │ /// Resolve a `CollectedTypeAlias` as a props chain.
 15 │ #[allow(clippy::too_many_arguments)]
 16 │ pub(super) fn resolve_type_alias_chain(
 17 │     alias: &CollectedTypeAlias,
 18 │     _consuming_file: &Utf8Path,
 19 │     mapping: &ComponentMapping,
 20 │     ctx: &ResolutionContext,
 21 │     state: &mut ResolveState,
 22 │     depth: u8,
 23 │ ) -> ResolvedChain {
 24 │     match alias {
 25 │         CollectedTypeAlias::Passthrough { target, file_path } => match target {
 26 │             CollectedType::Named { name, args } => {
 27 │                 let raw_args: Vec<String> = args.iter().map(|a| a.to_raw_string()).collect();
 28 │                 resolve_props_chain(name.as_str(), &raw_args, file_path, mapping, ctx, state, depth + 1)
 29 │             }
 30 │             _ => ResolvedChain::default(),
 31 │         },
 32 │ 
 33 │         CollectedTypeAlias::Omit { base, omitted_keys, file_path } => {
 34 │             // Resolve the base type first, then remove omitted keys.
 35 │             let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
 36 │             let omitted_set: FxHashSet<&str> = omitted_keys.iter().map(|k| k.as_str()).collect();
 37 │             chain.props.retain(|p| !omitted_set.contains(p.name.as_str()));
 38 │             // Record omitted keys in the relevant inheritance layer.
 39 │             for layer in &mut chain.inheritance {
 40 │                 for key in omitted_keys {
 41 │                     if !layer.omitted.contains(key) {
 42 │                         layer.omitted.push(key.clone());
 43 │                     }
 44 │                 }
 45 │             }
 46 │             chain
 47 │         }
 48 │ 
 49 │         CollectedTypeAlias::Pick { base, picked_keys, file_path } => {
 50 │             let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
 51 │             let picked_set: FxHashSet<&str> = picked_keys.iter().map(|k| k.as_str()).collect();
 52 │             chain.props.retain(|p| picked_set.contains(p.name.as_str()));
 53 │             chain
 54 │         }
 55 │ 
 56 │         CollectedTypeAlias::Partial { base, file_path } => {
 57 │             let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
 58 │             // Make all props optional.
 59 │             for prop in &mut chain.props {
 60 │                 prop.required = false;
 61 │             }
 62 │             chain
 63 │         }
 64 │ 
 65 │         CollectedTypeAlias::Required { base, file_path } => {
 66 │             let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
 67 │             // Make all props required.
 68 │             for prop in &mut chain.props {
 69 │                 prop.required = true;
 70 │             }
 71 │             chain
 72 │         }
 73 │ 
 74 │         CollectedTypeAlias::Union { members, file_path } => {
 75 │             // Discriminated union — try to find the discriminant and merge all members.
 76 │             resolve_union_alias(members, file_path, mapping, ctx, state, depth)
 77 │         }
 78 │ 
 79 │         CollectedTypeAlias::Intersection { members, file_path } => {
 80 │             // Merge all members' props.
 81 │             let mut chain = ResolvedChain::default();
 82 │             for member in members {
 83 │                 let member_chain = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
 84 │                 chain.merge_parent(member_chain);
 85 │             }
 86 │             chain
 87 │         }
 88 │ 
 89 │         CollectedTypeAlias::LiteralUnion { .. } => {
 90 │             // Pure string union used as a type alias — not a props provider.
 91 │             ResolvedChain::default()
 92 │         }
 93 │     }
 94 │ }
 95 │ 
 96 │ /// Resolve a `CollectedType` as a props chain (for base types in aliases).
 97 │ pub(super) fn resolve_base_as_chain(
 98 │     base: &CollectedType,
 99 │     file_path: &Utf8Path,
100 │     mapping: &ComponentMapping,
101 │     ctx: &ResolutionContext,
102 │     state: &mut ResolveState,
103 │     depth: u8,
104 │ ) -> ResolvedChain {
105 │     match base {
106 │         CollectedType::Named { name, args } => {
107 │             let raw_args: Vec<String> = args.iter().map(|a| a.to_raw_string()).collect();
108 │             resolve_props_chain(name.as_str(), &raw_args, file_path, mapping, ctx, state, depth + 1)
109 │         }
110 │         CollectedType::Intersection(members) => {
111 │             let mut chain = ResolvedChain::default();
112 │             for member in members {
113 │                 let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
114 │                 chain.merge_parent(sub);
115 │             }
116 │             chain
117 │         }
118 │         CollectedType::Object(fields) => {
119 │             // Inline object type in an intersection: `ComponentPropsWithoutRef<'button'> & { asChild?: boolean }`
120 │             // Expand the object fields directly as own props.
121 │             let mut chain = ResolvedChain::default();
122 │             for field in fields {
123 │                 let prop_type = resolve_collected_type(&field.collected_type, file_path, ctx, state, depth);
124 │                 chain.props.push(ParsedProp {
125 │                     name: field.name.clone(),
126 │                     prop_type,
127 │                     required: field.required,
128 │                     default_value: None,
129 │                     description: field.description.clone(),
130 │                     tags: Default::default(),
131 │                     parent: None,
132 │                     declarations: vec![],
133 │                 });
134 │             }
135 │             chain
136 │         }
137 │         _ => ResolvedChain::default(),
138 │     }
139 │ }
140 │ 
141 │ /// Resolve a `CollectedTypeAlias::Union` — detect discriminated union if possible.
142 │ #[allow(clippy::too_many_arguments)]
143 │ pub(super) fn resolve_union_alias(
144 │     members: &[CollectedType],
145 │     file_path: &Utf8Path,
146 │     mapping: &ComponentMapping,
147 │     ctx: &ResolutionContext,
148 │     state: &mut ResolveState,
149 │     depth: u8,
150 │ ) -> ResolvedChain {
151 │     use super::chain::find_discriminant_prop;
152 │ 
153 │     // Collect all member chains for named types (only Named can be discriminated).
154 │     let named_members: Vec<(&str, Vec<ParsedProp>)> = members
155 │         .iter()
156 │         .filter_map(|m| {
157 │             if let CollectedType::Named { name, .. } = m {
158 │                 let mut branch_state = ResolveState { visited: state.visited.clone(), diagnostics: vec![] };
159 │                 let chain =
160 │                     resolve_props_chain(name.as_str(), &[], file_path, mapping, ctx, &mut branch_state, depth + 1);
161 │                 state.diagnostics.extend(branch_state.diagnostics);
162 │                 Some((name.as_str(), chain.props))
163 │             } else {
164 │                 None
165 │             }
166 │         })
167 │         .collect();
168 │ 
169 │     if named_members.len() < 2 {
170 │         // Not a discriminated union — just merge all.
171 │         let mut chain = ResolvedChain::default();
172 │         for member in members {
173 │             let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
174 │             chain.merge_parent(sub);
175 │         }
176 │         return chain;
177 │     }
178 │ 
179 │     // Try to find a discriminant prop (a prop whose type is a distinct string literal across all members).
180 │     let discriminant = find_discriminant_prop(&named_members);
181 │ 
182 │     // Merge all props from all members.
183 │     let mut merged_props: BTreeMap<String, ParsedProp> = BTreeMap::new();
184 │     for (_, member_props) in &named_members {
185 │         for prop in member_props {
186 │             merged_props.entry(prop.name.clone()).or_insert_with(|| prop.clone());
187 │         }
188 │     }
189 │ 
190 │     // If we found a discriminant, merge its type as a union of all its literal values.
191 │     if let Some(ref disc_name) = discriminant {
192 │         let disc_literals: Vec<PropType> = named_members
193 │             .iter()
194 │             .filter_map(|(_, props)| props.iter().find(|p| &p.name == disc_name).map(|p| p.prop_type.clone()))
195 │             .collect();
196 │ 
197 │         if let Some(disc_prop) = merged_props.get_mut(disc_name) {
198 │             disc_prop.prop_type = PropType::Union(disc_literals);
199 │         }
200 │     }
201 │ 
202 │     // Emit discriminated union diagnostic if applicable.
203 │     if discriminant.is_some() {
204 │         state.diagnostics.push(Diagnostic {
205 │             severity: DiagnosticSeverity::Info,
206 │             message: format!(
207 │                 "Discriminated union detected with discriminant prop '{}'",
208 │                 discriminant.as_deref().unwrap_or("")
209 │             ),
210 │             file: Some(file_path.to_string()),
211 │             line: None,
212 │             column: None,
213 │             help: None,
214 │             code: DiagnosticCode::DiscriminatedUnion,
215 │         });
216 │     }
217 │ 
218 │     ResolvedChain { props: merged_props.into_values().collect(), discriminant_prop: discriminant, ..Default::default() }
219 │ }
220 │ 
221 │ /// Resolve a `CollectedTypeAlias` to a `PropType` (at the type level, not chain level).
222 │ pub(super) fn resolve_type_alias_type(
223 │     alias: &CollectedTypeAlias,
224 │     consuming_file: &Utf8Path,
225 │     ctx: &ResolutionContext,
226 │     state: &mut ResolveState,
227 │     depth: u8,
228 │ ) -> PropType {
229 │     match alias {
230 │         CollectedTypeAlias::LiteralUnion { members, .. } => {
231 │             PropType::LiteralUnion { members: members.clone(), has_default: false }
232 │         }
233 │         CollectedTypeAlias::Passthrough { target, .. } => {
234 │             resolve_collected_type(target, consuming_file, ctx, state, depth + 1)
235 │         }
236 │         CollectedTypeAlias::Union { members, .. } => {
237 │             let resolved: Vec<PropType> =
238 │                 members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect();
239 │             PropType::Union(resolved)
240 │         }
241 │         CollectedTypeAlias::Intersection { members, .. } => {
242 │             let resolved: Vec<PropType> =
243 │                 members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect();
244 │             PropType::Intersection(resolved)
245 │         }
246 │         CollectedTypeAlias::Partial { base, .. } | CollectedTypeAlias::Required { base, .. } => {
247 │             resolve_collected_type(base, consuming_file, ctx, state, depth + 1)
248 │         }
249 │         CollectedTypeAlias::Omit { base, .. } | CollectedTypeAlias::Pick { base, .. } => {
250 │             // At the type level, just forward to the base type.
251 │             resolve_collected_type(base, consuming_file, ctx, state, depth + 1)
252 │         }
253 │     }
254 │ }

  1 │ //! Prop-type resolver — Phase 3a.
  2 │ //!
  3 │ //! Converts `ComponentMapping` (raw collected data) into a fully resolved
  4 │ //! `ComponentEntry` with `PropType` props.
  5 │ //!
  6 │ //! Central design:
  7 │ //! - `resolve_component` is the entry point (called in parallel per component).
  8 │ //! - `resolve_collected_type` is the recursive dispatch for `CollectedType → PropType`.
  9 │ //! - No string parsing happens here — everything is already structured `CollectedType`.
 10 │ //! - Graceful degradation: every unresolvable type becomes `PropType::Opaque` + a `Diagnostic`.
 11 │ 
 12 │ use std::collections::BTreeMap;
 13 │ use std::sync::Arc;
 14 │ 
 15 │ #[allow(unused_imports)]
 16 │ use camino::{Utf8Path, Utf8PathBuf};
 17 │ use compact_str::CompactString;
 18 │ use oxc_resolver::{AliasValue, ResolveOptions, Resolver};
 19 │ use rustc_hash::{FxHashMap, FxHashSet};
 20 │ 
 21 │ use crate::import_map::ImportResolutionMap;
 22 │ use crate::pipeline::PipelineOptions;
 23 │ use crate::react_types;
 24 │ use crate::types::*;
 25 │ 
 26 │ mod alias;
 27 │ mod chain;
 28 │ mod collected;
 29 │ mod extends;
 30 │ mod func;
 31 │ mod html;
 32 │ mod import;
 33 │ mod named;
 34 │ mod primitives;
 35 │ mod react;
 36 │ mod template;
