 38 │ // ─── Constants ────────────────────────────────────────────────────────────────
 39 │ 
 40 │ /// Maximum recursion depth for type resolution.
 41 │ /// Prevents infinite loops on circular type references.
 42 │ const MAX_DEPTH: u8 = 20;
 43 │ 
 44 │ // ─── ResolutionContext ────────────────────────────────────────────────────────
 45 │ 
 46 │ /// Shared, read-only context passed to all resolution functions.
 47 │ /// Arc'd so it can be cheaply shared across rayon threads.
 48 │ pub struct ResolutionContext {
 49 │     pub global: Arc<GlobalSourceData>,
 50 │     pub import_map: Arc<ImportResolutionMap>,
 51 │     pub oxc_resolver: Arc<Resolver>,
 52 │     pub extra_builtins: FxHashSet<CompactString>,
 53 │ }
 54 │ 
 55 │ impl ResolutionContext {
 56 │     pub fn new(global: Arc<GlobalSourceData>, options: &PipelineOptions) -> Self {
 57 │         let alias: Vec<(String, Vec<AliasValue>)> = react::read_tsconfig_paths(options.tsconfig_path.as_deref());
 58 │ 
 59 │         let resolve_options = ResolveOptions {
 60 │             condition_names: vec!["types".into(), "import".into(), "require".into(), "default".into()],
 61 │             main_fields: vec!["types".into(), "typings".into(), "module".into(), "main".into()],
 62 │             extensions: vec![".ts".into(), ".tsx".into(), ".d.ts".into(), ".js".into()],
 63 │             alias,
 64 │             ..ResolveOptions::default()
 65 │         };
 66 │ 
 67 │         Self {
 68 │             import_map: Arc::new(ImportResolutionMap::build(&global)),
 69 │             global,
 70 │             oxc_resolver: Arc::new(Resolver::new(resolve_options)),
 71 │             extra_builtins: options.extra_builtins.clone(),
 72 │         }
 73 │     }
 74 │ }
 75 │ 
 76 │ // ─── Entry Point ─────────────────────────────────────────────────────────────
 77 │ 
 78 │ /// Resolve a `ComponentMapping` to a complete `ComponentEntry`.
 79 │ ///
 80 │ /// Called in parallel via rayon — must be `Send + Sync` (all data is owned/Arc'd).
 81 │ pub fn resolve_component(mapping: &ComponentMapping, ctx: &ResolutionContext) -> (ComponentEntry, Vec<Diagnostic>) {
 82 │     let mut state = ResolveState::default();
 83 │ 
 84 │     let chain = chain::resolve_props_chain(
 85 │         mapping.props_type_name.as_str(),
 86 │         &mapping.props_type_args,
 87 │         &mapping.file_path,
 88 │         mapping,
 89 │         ctx,
 90 │         &mut state,
 91 │         0,
 92 │     );
 93 │ 
 94 │     // Build props BTreeMap — own props win over inherited props with same name.
 95 │     let mut props: BTreeMap<String, ParsedProp> = BTreeMap::new();
 96 │     for prop in chain.props {
 97 │         props.entry(prop.name.clone()).or_insert(prop);
 98 │     }
 99 │ 
100 │     // Populate notable_inherited from HTML element layers and non-HTML inherited layers.
101 │     let mut notable_inherited: BTreeMap<String, ParsedProp> = BTreeMap::new();
102 │     for layer in &chain.inheritance {
103 │         if let Some(ref element) = layer.html_element {
104 │             let notable_attrs = react_types::notable_html_attrs(element);
105 │             for attr_name in notable_attrs {
106 │                 if props.contains_key(*attr_name) {
107 │                     continue;
108 │                 } // own prop wins
109 │                 if notable_inherited.contains_key(*attr_name) {
110 │                     continue;
111 │                 } // already added
112 │ 
113 │                 // Synthesize a minimal prop for display purposes
114 │                 let prop_type = html::infer_html_attr_prop_type(attr_name);
115 │                 notable_inherited.insert(
116 │                     attr_name.to_string(),
117 │                     ParsedProp {
118 │                         name: attr_name.to_string(),
119 │                         prop_type,
120 │                         required: false,
121 │                         default_value: None,
122 │                         description: String::new(),
123 │                         tags: Default::default(),
124 │                         parent: Some(PropParent {
125 │                             name: format!("{}HTMLAttributes", html::capitalize_element(element)),
126 │                             file_name: "node_modules/@types/react/index.d.ts".to_string(),
127 │                         }),
128 │                         declarations: vec![],
129 │                     },
130 │                 );
131 │             }
132 │         } else {
133 │             // For non-HTML layers: add inherited props from chain.inherited_by_name
134 │             for (name, prop) in &chain.inherited_by_name {
135 │                 if !props.contains_key(name) && !notable_inherited.contains_key(name) {
136 │                     notable_inherited.insert(name.clone(), prop.clone());
137 │                 }
138 │             }
139 │         }
140 │     }
141 │ 
142 │     // Detect discriminated union if applicable.
143 │     let discriminant_prop = chain.discriminant_prop;
144 │ 
145 │     (
146 │         ComponentEntry {
147 │             display_name: mapping.component_name.clone(),
148 │             file_path: mapping.file_path.clone(),
149 │             description: mapping.description.clone(),
150 │             props,
151 │             inheritance: chain.inheritance,
152 │             notable_inherited,
153 │             discriminant_prop,
154 │             composes: chain.composes,
155 │             tags: mapping.tags.clone(),
156 │             methods: vec![],
157 │         },
158 │         state.diagnostics,
159 │     )
160 │ }
161 │ 
162 │ // ─── Intermediate Resolution Result ──────────────────────────────────────────
163 │ 
164 │ /// Result of resolving a props chain (including extends).
165 │ #[derive(Default)]
166 │ struct ResolvedChain {
167 │     /// Resolved props (may include inherited props).
168 │     props: Vec<ParsedProp>,
169 │     /// Inheritance layers, outermost first.
170 │     inheritance: Vec<InheritedLayer>,
171 │     /// Inherited props keyed by name — for notable_inherited population.
172 │     inherited_by_name: FxHashMap<String, ParsedProp>,
173 │     /// Type names that could not be resolved.
174 │     composes: Vec<String>,
175 │     /// Discriminant prop name if this is a discriminated union.
176 │     discriminant_prop: Option<String>,
177 │ }
178 │ 
179 │ impl ResolvedChain {
180 │     fn empty_with_compose(type_name: String) -> Self {
181 │         Self { composes: vec![type_name], ..Default::default() }
182 │     }
183 │ 
184 │     /// Merge a parent chain into self — own props already in `self.props` take priority.
185 │     fn merge_parent(&mut self, parent: ResolvedChain) {
186 │         // Collect existing prop names so we can skip duplicates.
187 │         let existing: FxHashSet<String> = self.props.iter().map(|p| p.name.clone()).collect();
188 │ 
189 │         for prop in parent.props {
190 │             if !existing.contains(&prop.name) {
191 │                 self.props.push(prop.clone());
192 │             }
193 │             // Always populate inherited_by_name so notable lookup works.
194 │             self.inherited_by_name.entry(prop.name.clone()).or_insert(prop);
195 │         }
196 │ 
197 │         // Prepend parent inheritance layers (parent is further up the chain).
198 │         let mut new_inheritance = parent.inheritance;
199 │         new_inheritance.append(&mut self.inheritance);
200 │         self.inheritance = new_inheritance;
201 │ 
202 │         self.composes.extend(parent.composes);
203 │         self.inherited_by_name.extend(parent.inherited_by_name);
204 │     }
205 │ }
