101 │                     let desc = value[space..].trim();
102 │                     tags.insert(format!("param:{}", prop_name), desc.to_owned());
103 │                 } else if !value.is_empty() {
104 │                     tags.insert(format!("param:{}", value), String::new());
105 │                 }
106 │             } else {
107 │                 tags.insert(tag.to_owned(), value.to_owned());
108 │             }
109 │         } else if in_tags && !line.is_empty() {
110 │             // Continuation of a tag — ignore for now
