55	    /// Merge a single file's SourceData into the global data.
56	    pub fn merge(&mut self, file_path: &Utf8Path, data: SourceData) {
57	        for (key, iface) in data.interfaces {
58	            match self.interfaces.entry(key) {
59	                std::collections::hash_map::Entry::Occupied(mut e) => {
60	                    // Declaration merging: combine props and extends
61	                    let existing = e.get_mut();
62	                    existing.props.extend(iface.props);
63	                    existing.extends.extend(iface.extends);
64	                }
65	                std::collections::hash_map::Entry::Vacant(e) => {
66	                    e.insert(iface);
67	                }
68	            }
69	        }
70	        self.type_aliases.extend(data.type_aliases);
71	        self.enums.extend(data.enums);
72	        self.import_map.insert(file_path.to_owned(), data.imports);
73	        self.re_export_map.insert(file_path.to_owned(), data.exports);
74	        self.component_mappings.extend(data.component_mappings);
75	    }
