77	    /// Remove all entries contributed by `file_path`. Called before re-merging an updated file.
78	    pub fn remove_file(&mut self, file_path: &Utf8Path) {
79	        let prefix = format!("{}:", file_path);
80	        self.interfaces.retain(|k, _| !k.starts_with(&prefix));
81	        self.type_aliases.retain(|k, _| !k.starts_with(&prefix));
82	        self.enums.retain(|k, _| !k.starts_with(&prefix));
83	        self.import_map.remove(file_path);
84	        self.re_export_map.remove(file_path);
85	        self.component_mappings.retain(|m| m.file_path != file_path);
86	    }
87	}
