1	//! Type alias classification: Omit, Pick, Partial, Required, Union, Intersection, Passthrough.
2	
3	use oxc_ast::ast::*;
4	
5	use crate::types::{CollectedType, CollectedTypeAlias};
6	
7	use super::SourceDataCollector;
8	
9	impl<'src> SourceDataCollector<'src> {
10	    // ─── TypeAlias classification ─────────────────────────────────────────────
11	
12	    pub(super) fn classify_type_alias<'a>(&mut self, _name: &str, ty: &TSType<'a>) -> Option<CollectedTypeAlias> {
13	        let fp = self.file_path.clone();
14	        match ty {
15	            TSType::TSTypeReference(tr) => {
16	                let ref_name = self.extract_type_ref_name(tr);
17	                match ref_name.as_str() {
18	                    "Omit" => {
19	                        let tp = tr.type_arguments.as_ref()?;
20	                        if tp.params.len() < 2 {
21	                            return None;
22	                        }
23	                        let (base_name, base_args) = self.extract_type_name_from_type(&tp.params[0])?;
24	                        let base = CollectedType::Named {
25	                            name: base_name,
26	                            args: base_args.into_iter().map(CollectedType::Raw).collect(),
27	                        };
28	                        let omitted_keys = self.collect_string_union_keys(&tp.params[1]);
29	                        Some(CollectedTypeAlias::Omit { base, omitted_keys, file_path: fp })
30	                    }
31	                    "Pick" => {
32	                        let tp = tr.type_arguments.as_ref()?;
33	                        if tp.params.len() < 2 {
34	                            return None;
35	                        }
36	                        let (base_name, base_args) = self.extract_type_name_from_type(&tp.params[0])?;
37	                        let base = CollectedType::Named {
38	                            name: base_name,
39	                            args: base_args.into_iter().map(CollectedType::Raw).collect(),
40	                        };
41	                        let picked_keys = self.collect_string_union_keys(&tp.params[1]);
42	                        Some(CollectedTypeAlias::Pick { base, picked_keys, file_path: fp })
43	                    }
44	                    "Partial" => {
45	                        let tp = tr.type_arguments.as_ref()?;
46	                        let (base_name, base_args) = self.extract_type_name_from_type(tp.params.first()?)?;
47	                        let base = CollectedType::Named {
48	                            name: base_name,
49	                            args: base_args.into_iter().map(CollectedType::Raw).collect(),
50	                        };
51	                        Some(CollectedTypeAlias::Partial { base, file_path: fp })
52	                    }
53	                    "Required" => {
54	                        let tp = tr.type_arguments.as_ref()?;
55	                        let (base_name, base_args) = self.extract_type_name_from_type(tp.params.first()?)?;
56	                        let base = CollectedType::Named {
57	                            name: base_name,
58	                            args: base_args.into_iter().map(CollectedType::Raw).collect(),
59	                        };
60	                        Some(CollectedTypeAlias::Required { base, file_path: fp })
61	                    }
62	                    "Readonly" => {
63	                        let tp = tr.type_arguments.as_ref()?;
64	                        let (base_name, base_args) = self.extract_type_name_from_type(tp.params.first()?)?;
65	                        let target = CollectedType::Named {
66	                            name: base_name,
67	                            args: base_args.into_iter().map(CollectedType::Raw).collect(),
68	                        };
69	                        Some(CollectedTypeAlias::Passthrough { target, file_path: fp })
70	                    }
71	                    _ => {
72	                        // Simple passthrough: `type Size = SomeOtherType`
73	                        let args = self.extract_type_args(&tr.type_arguments);
74	                        let target = CollectedType::Named {
75	                            name: ref_name.into(),
76	                            args: args.into_iter().map(CollectedType::Raw).collect(),
77	                        };
78	                        Some(CollectedTypeAlias::Passthrough { target, file_path: fp })
79	                    }
80	                }
81	            }
82	            TSType::TSUnionType(u) => {
83	                // Check if all members are string/number literals → LiteralUnion
84	                let all_string_literals = u.types.iter().all(|t| match t {
85	                    TSType::TSLiteralType(lit) => {
86	                        matches!(lit.literal, TSLiteral::StringLiteral(_))
87	                    }
88	                    TSType::TSUndefinedKeyword(_) | TSType::TSNullKeyword(_) => true,
89	                    _ => false,
90	                });
91	
92	                let members: Vec<CollectedType> = u.types.iter().map(|t| self.ts_type_to_collected(t)).collect();
93	
94	                if all_string_literals {
95	                    let member_strs: Vec<String> = members.iter().map(|m| m.to_raw_string()).collect();
96	                    return Some(CollectedTypeAlias::LiteralUnion { members: member_strs, file_path: fp });
97	                }
98	                Some(CollectedTypeAlias::Union { members, file_path: fp })
99	            }
100	            TSType::TSIntersectionType(i) => {
101	                let members = i.types.iter().map(|t| self.ts_type_to_collected(t)).collect();
102	                Some(CollectedTypeAlias::Intersection { members, file_path: fp })
103	            }
104	            TSType::TSParenthesizedType(p) => self.classify_type_alias(_name, &p.type_annotation),
105	            _ => None,
106	        }
107	    }
108	
109	    /// Collect the string literal keys from a type like `'key1' | 'key2'`.
110	    pub(super) fn collect_string_union_keys<'a>(&self, ty: &TSType<'a>) -> Vec<String> {
111	        match ty {
112	            TSType::TSLiteralType(lit) => match &lit.literal {
113	                TSLiteral::StringLiteral(s) => vec![s.value.as_str().to_owned()],
114	                _ => vec![],
115	            },
116	            TSType::TSUnionType(u) => u.types.iter().flat_map(|t| self.collect_string_union_keys(t)).collect(),
117	            _ => vec![],
118	        }
119	    }
120	}
