1	//! `impl Visit for SourceDataCollector` — the AST walker entry points.
2	
3	use oxc_ast::ast::*;
4	use oxc_ast_visit::{walk, Visit};
5	use oxc_syntax::scope::ScopeFlags;
6	
7	use crate::types::{
8	    CollectedInterface, ComponentMapping, EnumEntry, EnumValue, ExtendsRef, ImportBinding, LexedExport, RawProp,
9	};
10	
11	use super::{declaration_name, is_pascal_case, SourceDataCollector};
12	
13	impl<'a, 'src> Visit<'a> for SourceDataCollector<'src> {
14	    fn visit_import_declaration(&mut self, node: &ImportDeclaration<'a>) {
15	        let specifier = node.source.value.as_str().to_owned();
16	        let is_type_only = node.import_kind.is_type();
17	
18	        if let Some(specifiers) = &node.specifiers {
19	            for spec in specifiers {
20	                match spec {
21	                    ImportDeclarationSpecifier::ImportSpecifier(s) => {
22	                        let local = s.local.name.as_str();
23	                        let imported = s.imported.name();
24	                        let imported_str = imported.as_str();
25	                        self.imported_names.insert(local.into());
26	                        self.data.imports.push(ImportBinding {
27	                            local_name: local.into(),
28	                            exported_name: imported_str.into(),
29	                            specifier: specifier.clone(),
30	                            is_type_only: is_type_only || s.import_kind.is_type(),
31	                        });
32	                    }
33	                    ImportDeclarationSpecifier::ImportDefaultSpecifier(s) => {
34	                        let local = s.local.name.as_str();
35	                        self.imported_names.insert(local.into());
36	                        self.data.imports.push(ImportBinding {
37	                            local_name: local.into(),
38	                            exported_name: "default".into(),
39	                            specifier: specifier.clone(),
40	                            is_type_only,
41	                        });
42	                    }
43	                    ImportDeclarationSpecifier::ImportNamespaceSpecifier(s) => {
44	                        let local = s.local.name.as_str();
45	                        self.imported_names.insert(local.into());
46	                        self.data.imports.push(ImportBinding {
47	                            local_name: local.into(),
48	                            exported_name: "*".into(),
49	                            specifier: specifier.clone(),
50	                            is_type_only,
51	                        });
52	                    }
53	                }
54	            }
55	        }
56	
57	        // Don't walk children — we've handled everything
58	    }
59	
60	    fn visit_export_named_declaration(&mut self, node: &ExportNamedDeclaration<'a>) {
61	        if let Some(source) = &node.source {
62	            // Re-exports: `export { X } from "./y"`
63	            let src = source.value.as_str().to_owned();
64	            for spec in &node.specifiers {
65	                self.data.exports.push(LexedExport::ReExportNamed {
66	                    // local_name is what we call it here; source_name is the original
67	                    local_name: spec.exported.name().as_str().to_owned(),
68	                    source_name: spec.local.name().as_str().to_owned(),
69	                    source_specifier: src.clone(),
70	                    is_type_only: node.export_kind.is_type() || spec.export_kind.is_type(),
71	                });
72	            }
73	        } else {
74	            // Local exports: `export interface Foo / export type Bar / export const X`
75	            if let Some(decl) = &node.declaration {
76	                let decl_name = declaration_name(decl);
77	                if let Some(name) = decl_name {
78	                    self.data.exports.push(LexedExport::LocalDeclaration {
79	                        name: name.to_owned(),
80	                        is_type_only: node.export_kind.is_type(),
81	                    });
82	                }
83	            }
84	            // Also handle `export { Foo }` without a source (local)
85	            for spec in &node.specifiers {
86	                self.data.exports.push(LexedExport::LocalDeclaration {
87	                    name: spec.exported.name().as_str().to_owned(),
88	                    is_type_only: node.export_kind.is_type() || spec.export_kind.is_type(),
89	                });
90	            }
91	        }
92	
93	        // Walk the declaration so sub-visitors (interface, type alias, etc.) fire
94	        walk::walk_export_named_declaration(self, node);
95	    }
96	
97	    fn visit_export_all_declaration(&mut self, node: &ExportAllDeclaration<'a>) {
98	        let src = node.source.value.as_str().to_owned();
99	        if let Some(ns) = &node.exported {
100	            // `export * as Ns from "./y"`
101	            self.data.exports.push(LexedExport::ReExportNamespace {
102	                namespace: ns.name().as_str().to_owned(),
103	                source_specifier: src,
104	            });
105	        } else {
106	            // `export * from "./y"`
107	            self.data
108	                .exports
109	                .push(LexedExport::ReExportAll { source_specifier: src, is_type_only: node.export_kind.is_type() });
110	        }
111	    }
112	
113	    fn visit_ts_interface_declaration(&mut self, node: &TSInterfaceDeclaration<'a>) {
114	        let name = node.id.name.as_str();
115	        let key = self.scoped_key(name);
116	
117	        let extends: Vec<ExtendsRef> = node.extends.iter().map(|ext| self.collect_extends(ext)).collect();
118	
119	        let props: Vec<RawProp> =
120	            node.body.body.iter().filter_map(|sig| self.collect_property_signature(sig)).collect();
121	
122	        let description = self.find_jsdoc(node.span.start);
123	        let tags = self.extract_jsdoc_tags(node.span.start);
124	
125	        self.data.interfaces.insert(
126	            key.clone(),
127	            CollectedInterface {
128	                scoped_key: key,
129	                name: name.into(),
130	                file_path: self.file_path.clone(),
131	                props,
132	                extends,
133	                description,
134	                tags,
135	            },
136	        );
137	
138	        // Don't walk children — we've extracted everything we need
139	    }
140	
141	    fn visit_ts_type_alias_declaration(&mut self, node: &TSTypeAliasDeclaration<'a>) {
142	        let name = node.id.name.as_str();
143	        let key = self.scoped_key(name);
144	
145	        if let Some(alias) = self.classify_type_alias(name, &node.type_annotation) {
146	            self.data.type_aliases.insert(key, alias);
147	        }
148	    }
149	
150	    fn visit_ts_enum_declaration(&mut self, node: &TSEnumDeclaration<'a>) {
151	        let enum_name = node.id.name.as_str();
152	        let key = self.scoped_key(enum_name);
153	
154	        let entries: Vec<EnumEntry> = node
155	            .body
156	            .members
157	            .iter()
158	            .filter_map(|member| {
159	                let name = match &member.id {
160	                    TSEnumMemberName::Identifier(id) => id.name.as_str().to_owned(),
161	                    TSEnumMemberName::String(s) => s.value.as_str().to_owned(),
162	                    TSEnumMemberName::ComputedString(s) => s.value.as_str().to_owned(),
163	                    TSEnumMemberName::ComputedTemplateString(_) => return None,
164	                };
165	
166	                let value = match &member.initializer {
167	                    Some(init) => {
168	                        self.expression_to_enum_value(init).unwrap_or_else(|| EnumValue::String(name.clone()))
169	                    }
170	                    None => EnumValue::String(name.clone()),
171	                };
172	
173	                let description = self.find_jsdoc(member.span.start);
174	                Some(EnumEntry { name, value, description })
175	            })
176	            .collect();
177	
178	        if !entries.is_empty() {
179	            self.data.enums.insert(key, entries);
180	        }
181	    }
182	
183	    fn visit_variable_declaration(&mut self, node: &VariableDeclaration<'a>) {
184	        for declarator in &node.declarations {
185	            self.try_collect_const_enum(declarator);
186	            // Collect cva() / tv() variant definitions for all file types (.ts and .tsx)
187	            if let BindingPattern::BindingIdentifier(id) = &declarator.id {
188	                let name = id.name.as_str().to_owned();
189	                self.try_collect_cva_call(declarator, &name);
190	            }
191	            if self.is_tsx {
192	                if let Some(name) = self.extract_pascal_name(declarator) {
193	                    if let Some(mapping) = self
194	                        .try_fc_annotation(declarator, &name)
195	                        .or_else(|| self.try_forward_ref(declarator, &name))
196	                        .or_else(|| self.try_hoc_wrapped(declarator, &name))
197	                    {
198	                        self.data.component_mappings.push(mapping);
199	                        continue;
200	                    }
201	                }
202	            }
203	            // Pattern 5: declare const Button: React.ForwardRefExoticComponent<ButtonProps & RefAttributes<E>>
204	            // Common in .d.ts files — no initializer, just a type annotation
205	            if declarator.init.is_none() {
206	                if let Some(name) = self.extract_pascal_name(declarator) {
207	                    if let Some(mapping) = self.try_forward_ref_exotic_decl(declarator, &name) {
208	                        self.data.component_mappings.push(mapping);
209	                    }
210	                }
211	            }
212	        }
213	        // Walk children for nested declarations
214	        walk::walk_variable_declaration(self, node);
215	    }
216	
217	    fn visit_function(&mut self, func: &Function<'a>, flags: ScopeFlags) {
218	        // Pattern 4: `function Button(props: ButtonProps) { ... }`
219	        if self.is_tsx {
220	            if let Some(id) = &func.id {
221	                let name = id.name.as_str();
222	                if is_pascal_case(name) && func.r#type == FunctionType::FunctionDeclaration {
223	                    if let Some(first_param) = func.params.items.first() {
224	                        if let Some(type_ann) = &first_param.type_annotation {
225	                            if let Some((props_name, type_args)) =
226	                                self.extract_type_name_from_type(&type_ann.type_annotation)
227	                            {
228	                                let description = self.find_jsdoc(func.span.start);
229	                                let tags = self.extract_jsdoc_tags(func.span.start);
230	                                let param_defaults = self.extract_param_defaults(&func.params);
231	                                self.data.component_mappings.push(ComponentMapping {
232	                                    component_name: name.to_owned(),
233	                                    props_type_name: props_name,
234	                                    props_type_args: type_args,
235	                                    file_path: self.file_path.clone(),
236	                                    description,
237	                                    tags,
238	                                    span_start: func.span.start,
239	                                    span_end: func.span.end,
240	                                    param_defaults,
241	                                });
242	                            }
243	                        }
244	                    }
245	                }
246	            }
247	        }
248	        walk::walk_function(self, func, flags);
249	    }
250	
251	    fn visit_expression_statement(&mut self, node: &ExpressionStatement<'a>) {
252	        // Scan for `Button.displayName = "Button"` assignments
253	        self.try_scan_display_name(node);
254	        walk::walk_expression_statement(self, node);
255	    }
256	}
