17	/// Stateful session for incremental watch-mode extraction.
18	///
19	/// `global` and `component_cache` are updated atomically / concurrently on each
20	/// file change.  `reverse_deps` is rebuilt on structural changes (new file,
21	/// deleted file) via a new `WatchSession`.
22	pub struct WatchSession {
23	    pub options: PipelineOptions,
24	    /// Current merged source data — swapped atomically via `ArcSwap`.
25	    pub global: ArcSwap<GlobalSourceData>,
26	    /// Reverse-dependency graph built at initialisation time.
27	    pub reverse_deps: Arc<ReverseDeps>,
28	    /// Per-file SourceData cache (avoids re-reading files that haven't changed).
29	    pub source_cache: DashMap<Utf8PathBuf, SourceData>,
30	    /// Latest resolved component entries, keyed by display name.
31	    pub component_cache: DashMap<String, ComponentEntry>,
32	    /// Guards initialize() so concurrent callers don't race to build caches.
33	    initialized: Mutex<bool>,
34	}
35	
36	impl WatchSession {
37	    /// Create an empty WatchSession (call `initialize()` before first use).
38	    pub fn new(options: PipelineOptions) -> Self {
39	        Self {
40	            options,
41	            global: ArcSwap::new(Arc::new(GlobalSourceData::default())),
42	            reverse_deps: Arc::new(ReverseDeps { inner: Default::default() }),
43	            source_cache: DashMap::new(),
44	            component_cache: DashMap::new(),
45	            initialized: Mutex::new(false),
46	        }
47	    }
48	
49	    /// Run a full cold extraction to populate this session's caches.
50	    ///
51	    /// Idempotent — concurrent or repeated calls return the existing snapshot
52	    /// without re-running extraction.
53	    pub fn initialize(&self) -> ExtractionOutput {
54	        let mut guard = self.initialized.lock().expect("init lock poisoned");
55	        if *guard {
56	            return self.snapshot();
57	        }
58	
59	        // Cold extraction for the public-facing output.
60	        let mut output = extract(&self.options);
61	
62	        // Rebuild GlobalSourceData locally so we can populate our own caches.
63	        let src_files = discover_files(&self.options.src_dirs, &self.options.exclude_patterns);
64	        let mut global = GlobalSourceData::default();
65	
66	        for path in &src_files {
67	            let source = match std::fs::read_to_string(path) {
68	                Ok(s) => s,
69	                Err(e) => {
70	                    output.diagnostics.push(Diagnostic {
71	                        severity: DiagnosticSeverity::Error,
72	                        message: format!("Failed to read '{}': {}", path, e),
73	                        file: Some(path.to_string()),
74	                        line: None,
75	                        column: None,
76	                        help: Some("Check file permissions and that the file exists.".into()),
77	                        code: DiagnosticCode::IoError,
78	                    });
79	                    String::new()
80	                }
81	            };
82	            let data = crate::extractor::parse_file(path, &source);
83	            self.source_cache.insert(path.clone(), data.clone());
84	            global.merge(path, data);
85	        }
86	
87	        // Build reverse deps from the fully-merged global.
88	        // Note: we can't mutate self.reverse_deps (it's Arc, not ArcSwap).
89	        // On structural changes the caller should create a new WatchSession.
90	        let new_global = Arc::new(global);
91	        self.global.store(new_global);
92	
93	        // Seed component cache from the cold output.
94	        for (name, entry) in &output.components {
