53	    /// Build from a fully-merged `GlobalSourceData`.
54	    /// Called once per extraction run, before parallel resolution starts.
55	    ///
56	    /// No I/O — pure data transformation.
57	    pub fn build(global: &GlobalSourceData) -> Self {
58	        let mut bindings: FxHashMap<(Utf8PathBuf, CompactString), ImportRef> = FxHashMap::default();
59	        let mut wildcard_sources: FxHashMap<Utf8PathBuf, Vec<String>> = FxHashMap::default();
60	
61	        // ── Populate bindings from import_map ──────────────────────────────
62	        for (file_path, import_bindings) in &global.import_map {
