11	pub(super) fn resolve_function_type(
12	    params: &[CollectedType],
13	    return_type: &CollectedType,
14	    consuming_file: &Utf8Path,
15	    ctx: &ResolutionContext,
16	    state: &mut ResolveState,
17	    depth: u8,
18	) -> PropType {
19	    // Check if the return type is a React node → render prop pattern.
20	    let returns_react_node = matches!(
21	        return_type,
22	        CollectedType::Named { name, .. }
23	            if matches!(
24	                name.as_str(),
25	                "ReactNode"
26	                    | "ReactElement"
27	                    | "JSX.Element"
28	                    | "Element"
29	                    | "ReactPortal"
30	                    | "ReactFragment"
31	            )
32	    );
33	
34	    if returns_react_node && params.len() == 1 {
35	        let event_type = params[0].to_raw_string();
36	        return PropType::EventHandler { event_type };
37	    }
38	
39	    // Generic event handler: (e: SomeEvent) => void
40	    if params.len() == 1 {
41	        let event_type = params[0].to_raw_string();
42	        return PropType::EventHandler { event_type };
43	    }
44	
45	    // Zero-arg callback: () => void
46	    if params.is_empty() {
47	        return PropType::EventHandler { event_type: "void".into() };
48	    }
49	
50	    // Multi-param function — describe as opaque.
51	    let param_strs: Vec<String> = params.iter().map(|p| p.to_raw_string()).collect();
52	    let raw = format!("({}) => {}", param_strs.join(", "), return_type.to_raw_string());
53	
54	    // Resolve the return type to see if it's ReactNode.
55	    let _ = resolve_collected_type(return_type, consuming_file, ctx, state, depth + 1);
56	
57	    PropType::Opaque { raw, reason: OpaqueReason::ConditionalType }
58	}
