60	pub(super) fn resolve_typeof(
61	    name: &CompactString,
62	    consuming_file: &Utf8Path,
63	    ctx: &ResolutionContext,
64	    diagnostics: &mut Vec<Diagnostic>,
65	) -> PropType {
66	    // `typeof X` — look for X in global.enums (for cva() results), via the
67	    // precomputed bare-name index (O(1) instead of a linear scan over every
68	    // enum/cva/tv/recipe entry in the project with a per-candidate allocation).
69	    let found_enum = ctx.enum_bare_index.get(name.as_str()).and_then(|key| ctx.global.enums.get(key.as_str()));
70	
71	    if found_enum.is_some() {
72	        // Has cva-like enum entries — the VariantProps<typeof X> pattern handles this.
73	        // At the type level, surface as Named.
74	        return PropType::Named { name: name.clone(), args: vec![] };
75	    }
76	
77	    diagnostics.push(Diagnostic {
78	        severity: DiagnosticSeverity::Info,
79	        message: format!("typeof '{}' in '{}' — could not statically evaluate", name, consuming_file),
80	        file: Some(consuming_file.to_string()),
81	        line: None,
82	        column: None,
83	        help: None,
84	        code: DiagnosticCode::OpaqueType,
85	    });
86	
87	    PropType::Named { name: name.clone(), args: vec![] }
88	}
