                    | "ReactPortal"
                    | "ReactFragment"
            )
    );

    let first_param_name = || param_names.first().and_then(|n| n.as_ref()).map(|s| s.to_string());

    if returns_react_node && params.len() == 1 {
        let event_type = params[0].to_raw_string();
