const { existsSync } = require('node:fs')
const { join } = require('node:path')

// Maps process.platform/arch (and, on Linux, libc) to the published per-platform
// package name — napi-rs's standard convention. Only consulted as a fallback when
// this repo's own dev-local build (target/release, target/debug) isn't present,
// i.e. when @oxc-react-docgen/napi is installed as a real dependency rather than
// developed in-place.
function platformPackageName() {
  const { platform, arch } = process
  if (platform === 'darwin') {
    if (arch === 'arm64') return '@oxc-react-docgen/napi-darwin-arm64'
    if (arch === 'x64') return '@oxc-react-docgen/napi-darwin-x64'
  }
  if (platform === 'win32' && arch === 'x64') return '@oxc-react-docgen/napi-win32-x64-msvc'
  if (platform === 'linux') {
    // glibc vs musl detection, matching napi-rs's own generated-loader convention.
    let isMusl = false
    try {
      isMusl = !!process.report?.getReport()?.header?.glibcVersionRuntime === false
    } catch {
      // process.report unavailable — assume glibc, the more common case.
    }
    if (arch === 'x64' && !isMusl) return '@oxc-react-docgen/napi-linux-x64-gnu'
    if (arch === 'arm64' && !isMusl) return '@oxc-react-docgen/napi-linux-arm64-gnu'
  }
  return null
}

if (process.env.NAPI_RS_NATIVE_LIBRARY_PATH) {
  module.exports = require(process.env.NAPI_RS_NATIVE_LIBRARY_PATH)
} else {
  // Must match package name in crates/binding/Cargo.toml (oxc-react-docgen-napi → underscores)
  const binaryName = 'oxc_react_docgen_napi'
  const candidates = [
    join(__dirname, `${binaryName}.node`),
    join(__dirname, '../../target/release', `${binaryName}.node`),
    join(__dirname, '../../target/debug', `${binaryName}.node`),
  ]
  const found = candidates.find(p => existsSync(p))

  if (found) {
    module.exports = require(found)
  } else {
    const pkg = platformPackageName()
    let resolved
    if (pkg) {
      try {
        resolved = require(pkg)
      } catch {
        resolved = undefined
      }
    }
    if (!resolved) {
      throw new Error(
        `@oxc-react-docgen/napi: native binary not found.\n` +
        (pkg
          ? `Expected it via the optional dependency '${pkg}' — make sure your package manager installs ` +
            `optionalDependencies for your platform (${process.platform}-${process.arch}), or run ` +
            `'cargo build -p oxc-react-docgen-napi' if developing this repo directly.\n`
          : `Unsupported platform: ${process.platform}-${process.arch}.\n`) +
        `Dev-local paths searched:\n${candidates.map(p => `  ${p}`).join('\n')}`
      )
    }
    module.exports = resolved
  }
}

