// Ports of crates/cli/src/commands/extract.rs's serialize_rdt/serialize_storybook and
// crates/core/src/types/output.rs's PropType::raw_string()/is_literal_union(). Kept in
// lockstep with the Rust implementations by hand — there's no shared source of truth
// across the FFI boundary, so any change to the Rust side needs a matching edit here.
import type { ComponentEntry, ExtractionOutput, PropType } from '@oxc-react-docgen/napi'

function elementToTypeName(element: string): string {
  switch (element) {
    case 'button':
      return 'Button'
    case 'input':
      return 'Input'
    case 'textarea':
      return 'Textarea'
    case 'select':
      return 'Select'
    case 'a':
      return 'Anchor'
    case 'form':
      return 'Form'
    case 'label':
      return 'Label'
    case 'img':
      return 'Img'
    default:
      return 'HTML'
  }
}

export function isLiteralUnion(t: PropType): boolean {
  if (t.kind === 'union') {
    return t.members.every(m => m.kind === 'stringLiteral' || m.kind === 'numberLiteral' || m.kind === 'boolLiteral')
  }
  return t.kind === 'literalUnion'
}

export function rawString(t: PropType): string {
  switch (t.kind) {
    case 'string':
      return 'string'
    case 'number':
      return 'number'
    case 'boolean':
      return 'boolean'
    case 'null':
      return 'null'
    case 'undefined':
      return 'undefined'
    case 'any':
      return 'any'
    case 'never':
      return 'never'
    case 'unknown':
      return 'unknown'
    case 'void':
      return 'void'
    case 'stringLiteral':
      return `"${t.value}"`
    case 'numberLiteral':
      return String(t.value)
    case 'boolLiteral':
      return String(t.value)
    case 'union':
      return t.members.map(rawString).join(' | ')
    case 'intersection':
      return t.members.map(rawString).join(' & ')
    case 'array':
      return `${rawString(t.element)}[]`
    case 'tuple':
      return 'tuple'
    case 'object':
      return 'object'
    case 'literalUnion':
      return t.members.map(m => `"${m}"`).join(' | ')
    case 'named':
      return t.args.length === 0 ? t.name : `${t.name}<${t.args.map(rawString).join(', ')}>`
    case 'reactNode':
      return 'ReactNode'
    case 'cssProperties':
      return 'CSSProperties'
    case 'eventHandler':
      return `(${t.paramName ?? 'e'}: ${t.eventType}) => void`
    case 'ref':
      return t.element ? `Ref<${t.element}>` : 'Ref<unknown>'
    case 'elementType':
      return 'ElementType'
    case 'htmlAttributes':
      return `${elementToTypeName(t.element)}HTMLAttributes`
    case 'sxProps':
      return 'SxProps'
    case 'opaque':
      return t.raw
  }
}

/** RDT's type-name convention for literal unions: `{name: "enum", value: [...]}` instead
 * of inlining the literal text, so prop-table renderers that pattern-match
 * `type.name === "enum"` show a `<select>` control. */
function rdtTypeJson(t: PropType): { name: string; value?: Array<{ value: string }> } {
  if (isLiteralUnion(t)) {
    const values =
      t.kind === 'union'
        ? t.members.map(m => ({ value: rawString(m) }))
        : t.kind === 'literalUnion'
          ? t.members.map(m => ({ value: `"${m}"` }))
          : []
    return { name: 'enum', value: values }
  }
  return { name: rawString(t) }
}

export function serializeRdt(output: ExtractionOutput): string {
  const components: Record<string, unknown> = {}
  for (const [name, entry] of Object.entries(output.components)) {
    const props: Record<string, unknown> = {}
    for (const [propName, prop] of Object.entries(entry.props)) {
      props[propName] = {
        name: prop.name,
        type: rdtTypeJson(prop.type),
        required: prop.required,
        defaultValue: prop.defaultValue ? { value: prop.defaultValue.value, computed: prop.defaultValue.computed } : null,
        description: prop.description,
        parent: prop.parent ? { name: prop.parent.name, fileName: prop.parent.fileName } : null,
      }
    }
    components[name] = {
      displayName: entry.displayName,
      props,
      description: entry.description,
      methods: [],
      tags: entry.tags,
    }
  }
  return JSON.stringify(components, null, 2)
}

export function serializeStorybook(output: ExtractionOutput): string {
  const components: Record<string, unknown> = {}
  for (const [name, entry] of Object.entries(output.components)) {
    const props: Record<string, unknown> = {}
    for (const [propName, prop] of Object.entries(entry.props)) {
      props[propName] = {
        name: prop.name,
        type: { name: rawString(prop.type) },
        required: prop.required,
        defaultValue: prop.defaultValue ? { value: prop.defaultValue.value } : null,
        description: prop.description,
      }
    }
    components[name] = {
      displayName: entry.displayName,
      props,
      description: entry.description,
      methods: [],
    }
  }
  return JSON.stringify(components, null, 2)
}

export type OutputFormat = 'canonical' | 'rdt' | 'storybook'

export function serialize(output: ExtractionOutput, format: OutputFormat): string {
  switch (format) {
    case 'canonical':
      return JSON.stringify(output, null, 2)
    case 'rdt':
      return serializeRdt(output)
    case 'storybook':
      return serializeStorybook(output)
  }
}

export function htmlElement(entry: ComponentEntry): string | null {
  for (const layer of entry.inheritance) {
    if (layer.htmlElement) return layer.htmlElement
  }
  return null
}

// Ports crates/cli/src/output.rs. Always writes to stderr — stdout is reserved for the
// JSON payload (canonical/RDT/storybook), in every mode, so `oxc-react-docgen extract | jq .`
// never sees this interleaved with the data.
import chalk from 'chalk'
import type { Diagnostic, ExtractionOutput } from '@oxc-react-docgen/napi'

export function printSummary(output: ExtractionOutput, quiet: boolean): void {
  if (quiet) return

  const errors = output.diagnostics.filter(d => d.severity === 'error').length
  const warnings = output.diagnostics.filter(d => d.severity === 'warning').length

  const warningsStr = warnings > 0 ? chalk.yellow(`${warnings} warnings`) : `${warnings} warnings`
  const errorsStr = errors > 0 ? chalk.red(`${errors} errors`) : `${errors} errors`

  process.stderr.write('\n')
  process.stderr.write(
    `  ${chalk.yellow('⚡')}  ${chalk.bold(output.stats.componentsExtracted)} components  ·  ` +
      `${chalk.bold(Object.keys(output.enums).length)} enums  ·  ${warningsStr}  ·  ${errorsStr}  ·  ` +
      `${chalk.bold(output.stats.durationMs)}ms\n`,
  )
  process.stderr.write('\n')
}

export function printDiagnostics(diagnostics: Diagnostic[]): void {
  for (const d of diagnostics) {
    const prefix =
      d.severity === 'error' ? chalk.red('error') : d.severity === 'warning' ? chalk.yellow('warn') : chalk.dim('info')
    if (d.file) {
      process.stderr.write(`  [${prefix}] ${d.file}:${d.message}\n`)
    } else {
      process.stderr.write(`  [${prefix}] ${d.message}\n`)
    }
    if (d.help) {
      process.stderr.write(`    ${chalk.dim('help:')} ${d.help}\n`)
    }
  }
}

// Loads docgen.config.ts and merges it with CLI flags into a JsExtractOptions the NAPI
// binding accepts. Unlike crates/cli/src/config.rs (which hard-errors on any found config
// file — mapping its JSON schema onto Rust's PipelineOptions isn't implemented there), this
// CLI runs in the same JS runtime as the config file, so it can actually merge it: no FFI
// boundary to cross, no schema-mapping gap to work around.
import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { pathToFileURL } from 'node:url'

import type { JsExtractOptions } from '@oxc-react-docgen/napi'

const WORKSPACE_ROOT_SIGNALS = ['pnpm-workspace.yaml', 'turbo.json', '.moon/workspace.yml']

/** Walk up from `startDir` looking for docgen.config.ts, stopping at a workspace root. */
function findConfigFile(startDir: string): string | null {
  let dir = startDir
  for (;;) {
    const candidate = join(dir, 'docgen.config.ts')
    if (existsSync(candidate)) return candidate
    if (WORKSPACE_ROOT_SIGNALS.some(signal => existsSync(join(dir, signal)))) return null
    const parent = dirname(dir)
    if (parent === dir) return null
    dir = parent
  }
}

/** The shape a docgen.config.ts default-exports — a subset of JsExtractOptions using the
 * same field names, so no separate schema is needed. */
type DocgenConfig = Partial<JsExtractOptions>

async function loadConfigFile(path: string): Promise<DocgenConfig> {
  const mod = await import(pathToFileURL(path).href)
  const config = mod.default ?? mod
  if (typeof config !== 'object' || config === null) {
    throw new Error(`${path} must default-export an object, got ${typeof config}`)
  }
  return config as DocgenConfig
}

export interface BuildOptionsArgs {
  src: string[]
  noCrossPackage?: boolean
  reactVersion?: string
  cacheDir?: string
  configPath?: string
}

/** Merge (docgen.config.ts, CLI flags, defaults) into JsExtractOptions — CLI flags win. */
export async function buildOptions(args: BuildOptionsArgs): Promise<JsExtractOptions> {
  const configPath = args.configPath ?? findConfigFile(process.cwd())
  const config: DocgenConfig = configPath ? await loadConfigFile(configPath) : {}

  const options: JsExtractOptions = {
    srcDirs: config.srcDirs ?? ['./src'],
    exclude: config.exclude,
    reactVersion: config.reactVersion,
    crossPackage: config.crossPackage,
    pandacssOutdir: config.pandacssOutdir,
    variantFunctions: config.variantFunctions,
    skipHtmlProps: config.skipHtmlProps,
    tsconfigPath: config.tsconfigPath,
    extraBuiltins: config.extraBuiltins,
    vanillaExtract: config.vanillaExtract,
    cacheDir: config.cacheDir,
    resolveComplexTypes: config.resolveComplexTypes,
    extraPathsJson: config.extraPathsJson,
    knownTypeOverridesJson: config.knownTypeOverridesJson,
  }

  if (args.src.length > 0) options.srcDirs = args.src
  if (args.noCrossPackage) options.crossPackage = false
  if (args.reactVersion) options.reactVersion = args.reactVersion === 'react18' ? 'react18' : 'react19'
  if (args.cacheDir) options.cacheDir = args.cacheDir

  return options
}

