93	        let containing_file = containing_file.as_ref();
94	        let span =
95	            tracing::debug_span!("resolve_dts", file = ?containing_file, specifier = specifier);
96	        let _enter = span.enter();
97	        let result = self.resolve_dts_impl(containing_file, specifier);
98	        match &result {
99	            Ok(r) => tracing::debug!(ret = ?r.path),
100	            Err(err) => tracing::debug!(?err),
101	        }
102	        result
103	    }
104	
105	    fn resolve_dts_impl(
106	        &self,
107	        containing_file: &Path,
108	        specifier: &str,
109	    ) -> Result<Resolution, ResolveError> {
110	        let mut ctx = Ctx::default();
111	
112	        let containing_dir = containing_file.parent().unwrap_or(containing_file);
113	        let cached_dir = self.cache.value(containing_dir);
114	
115	        let extensions =
116	            Extensions::TYPESCRIPT.union(Extensions::JAVASCRIPT).union(Extensions::DECLARATION);
117	
118	        // Parse query/fragment
119	        let parsed = Specifier::parse(specifier).map_err(ResolveError::Specifier)?;
120	        ctx.with_query_fragment(parsed.query, parsed.fragment);
121	        let specifier = parsed.path();
122	
123	        // 1. tsconfig paths (non-relative only)
124	        if !specifier.starts_with('.')
125	            && !specifier.starts_with('/')
126	            && let Some(path) = self.dts_resolve_tsconfig_paths(&cached_dir, specifier, &mut ctx)?
127	        {
128	            return self.dts_finalize(&path, &mut ctx);
129	        }
130	
131	        // 2. Route by specifier type
132	        let result = if specifier.starts_with('.') || specifier.starts_with('/') {
133	            // Relative or absolute
134	            let candidate = cached_dir.normalize_with(specifier, &self.cache);
135	            self.dts_resolve_relative(extensions, &candidate, &mut ctx)?
136	        } else if specifier.starts_with('#') {
137	            // Package imports
138	            self.dts_resolve_package_imports(&cached_dir, specifier, &mut ctx)?
139	        } else if specifier.contains(':') {
140	            // URI scheme (node:fs, etc.)
141	            None
142	        } else {
143	            // Bare specifier -> node_modules
144	            let (package_name, rest) = Self::parse_package_specifier(specifier);
145	
146	            // Try self-referencing first
147	            if let Some(path) = self.dts_resolve_package_self(&cached_dir, specifier, &mut ctx)? {
148	                Some(path)
149	            } else {
150	                self.dts_resolve_node_modules(
151	                    extensions,
152	                    specifier,
153	                    package_name,
154	                    rest,
155	                    &cached_dir,
156	                    &mut ctx,
157	                )?
158	            }
159	        };
160	
161	        result.map_or_else(
162	            || Err(ResolveError::NotFound(specifier.to_string())),
163	            |path| self.dts_finalize(&path, &mut ctx),
164	        )
165	    }
166	
167	    fn dts_finalize(
168	        &self,
169	        cached_path: &CachedPath,
170	        ctx: &mut Ctx,
171	    ) -> Result<Resolution, ResolveError> {
172	        let path = self.load_realpath(cached_path)?;
173	        let package_json = self.find_package_json_for_a_package(cached_path, ctx)?;
174	        let module_type = Self::dts_module_type(cached_path);
175	        Ok(Resolution {
176	            path,
177	            query: ctx.query.take(),
178	            fragment: ctx.fragment.take(),
179	            package_json,
180	            module_type,
181	        })
182	    }
183	
184	    fn dts_module_type(cached_path: &CachedPath) -> Option<ModuleType> {
185	        let path_str = cached_path.path().to_string_lossy();
186	        if path_str.ends_with(".d.mts") || path_str.ends_with(".mts") {
187	            Some(ModuleType::Module)
188	        } else if path_str.ends_with(".d.cts") || path_str.ends_with(".cts") {
189	            Some(ModuleType::CommonJs)
190	        } else if path_str.ends_with(".json") {
191	            Some(ModuleType::Json)
192	        } else {
193	            None
194	        }
195	    }
