197	    // -------- Core resolution methods --------
198	
199	    fn dts_resolve_relative(
200	        &self,
201	        extensions: Extensions,
202	        candidate: &CachedPath,
203	        ctx: &mut Ctx,
204	    ) -> ResolveResult {
205	        if let Some(path) = self.dts_resolve_as_file(extensions, candidate, ctx) {
206	            return Ok(Some(path));
207	        }
208	        self.dts_resolve_as_directory(extensions, candidate, ctx)
209	    }
210	
211	    /// TS: `loadModuleFromFile`
212	    fn dts_resolve_as_file(
213	        &self,
214	        extensions: Extensions,
215	        candidate: &CachedPath,
216	        ctx: &mut Ctx,
217	    ) -> Option<CachedPath> {
218	        let path_str = candidate.path().to_string_lossy();
219	
220	        // Phase 1: Extension replacement (./foo.js -> ./foo.ts)
221	        if let Some(original_ext) = Self::dts_get_known_extension(&path_str) {
222	            // Strip the extension to get the extensionless base
223	            let base_len = path_str.len() - original_ext.len();
224	            let base_str = &path_str[..base_len];
225	            let base = self.cache.value(Path::new(base_str));
226	            if let Some(path) = self.dts_try_extensions(&base, extensions, original_ext, ctx) {
227	                return Some(path);
228	            }
229	        }
230	
231	        // Phase 2: Extension addition (./foo -> ./foo.ts)
232	        self.dts_try_extensions(candidate, extensions, "", ctx)
233	    }
234	
235	    /// Get the known extension from a path, including compound extensions like `.d.ts`.
236	    fn dts_get_known_extension(path: &str) -> Option<&str> {
237	        // Check compound extensions first
238	        for ext in &[".d.ts", ".d.mts", ".d.cts"] {
239	            if path.ends_with(ext) {
240	                return Some(ext);
241	            }
242	        }
243	        // Check single extensions
244	        let dot_pos = path.rfind('.')?;
245	        let ext = &path[dot_pos..];
246	        match ext {
247	            ".ts" | ".tsx" | ".mts" | ".cts" | ".js" | ".jsx" | ".mjs" | ".cjs" | ".json" => {
248	                Some(ext)
249	            }
250	            _ => {
251	                // Unknown extensions like .vue, .svelte - return them for d.{ext}.ts handling
252	                if !ext.is_empty() && ext.len() < 10 { Some(ext) } else { None }
253	            }
254	        }
255	    }
256	
257	    /// TS: `tryAddingExtensions`
258	    #[allow(clippy::too_many_lines)]
259	    fn dts_try_extensions(
260	        &self,
261	        base: &CachedPath,
262	        extensions: Extensions,
263	        original_ext: &str,
264	        ctx: &mut Ctx,
265	    ) -> Option<CachedPath> {
266	        match original_ext {
267	            ".mjs" | ".mts" | ".d.mts" => {
268	                if extensions.contains(Extensions::TYPESCRIPT)
269	                    && let Some(p) = self.dts_try_file(base, ".mts", ctx)
270	                {
271	                    return Some(p);
272	                }
273	                if extensions.contains(Extensions::DECLARATION)
274	                    && let Some(p) = self.dts_try_file(base, ".d.mts", ctx)
275	                {
276	                    return Some(p);
277	                }
278	                if extensions.contains(Extensions::JAVASCRIPT)
279	                    && let Some(p) = self.dts_try_file(base, ".mjs", ctx)
280	                {
281	                    return Some(p);
282	                }
283	            }
284	            ".cjs" | ".cts" | ".d.cts" => {
285	                if extensions.contains(Extensions::TYPESCRIPT)
286	                    && let Some(p) = self.dts_try_file(base, ".cts", ctx)
287	                {
288	                    return Some(p);
289	                }
290	                if extensions.contains(Extensions::DECLARATION)
291	                    && let Some(p) = self.dts_try_file(base, ".d.cts", ctx)
292	                {
293	                    return Some(p);
294	                }
295	                if extensions.contains(Extensions::JAVASCRIPT)
296	                    && let Some(p) = self.dts_try_file(base, ".cjs", ctx)
297	                {
298	                    return Some(p);
299	                }
300	            }
301	            ".json" => {
302	                if extensions.contains(Extensions::DECLARATION)
303	                    && let Some(p) = self.dts_try_file(base, ".d.json.ts", ctx)
304	                {
305	                    return Some(p);
306	                }
307	            }
308	            ".tsx" | ".jsx" => {
309	                if extensions.contains(Extensions::TYPESCRIPT) {
310	                    if let Some(p) = self.dts_try_file(base, ".tsx", ctx) {
311	                        return Some(p);
312	                    }
313	                    if let Some(p) = self.dts_try_file(base, ".ts", ctx) {
314	                        return Some(p);
315	                    }
316	                }
317	                if extensions.contains(Extensions::DECLARATION)
318	                    && let Some(p) = self.dts_try_file(base, ".d.ts", ctx)
319	                {
320	                    return Some(p);
321	                }
322	                if extensions.contains(Extensions::JAVASCRIPT) {
323	                    if let Some(p) = self.dts_try_file(base, ".jsx", ctx) {
324	                        return Some(p);
325	                    }
326	                    if let Some(p) = self.dts_try_file(base, ".js", ctx) {
327	                        return Some(p);
328	                    }
329	                }
330	            }
331	            ".ts" | ".d.ts" | ".js" | "" => {
332	                if extensions.contains(Extensions::TYPESCRIPT) {
333	                    if let Some(p) = self.dts_try_file(base, ".ts", ctx) {
334	                        return Some(p);
335	                    }
336	                    if let Some(p) = self.dts_try_file(base, ".tsx", ctx) {
337	                        return Some(p);
338	                    }
339	                }
340	                if extensions.contains(Extensions::DECLARATION)
341	                    && let Some(p) = self.dts_try_file(base, ".d.ts", ctx)
342	                {
343	                    return Some(p);
344	                }
345	                if extensions.contains(Extensions::JAVASCRIPT) {
346	                    if let Some(p) = self.dts_try_file(base, ".js", ctx) {
347	                        return Some(p);
348	                    }
349	                    if let Some(p) = self.dts_try_file(base, ".jsx", ctx) {
350	                        return Some(p);
351	                    }
352	                }
353	            }
354	            // Unknown extensions like ".vue", ".svelte" -> try .d{ext}.ts
355	            other => {
356	                if extensions.contains(Extensions::DECLARATION) {
357	                    let d_ext = format!(".d{other}.ts");
358	                    if let Some(p) = self.dts_try_file(base, &d_ext, ctx) {
359	                        return Some(p);
360	                    }
361	                }
362	            }
363	        }
364	        None
365	    }
366	
367	    fn dts_try_file(&self, base: &CachedPath, ext: &str, ctx: &mut Ctx) -> Option<CachedPath> {
368	        let candidate = base.add_extension(ext, &self.cache);
369	        if self.is_file(&candidate, ctx) { Some(candidate) } else { None }
370	    }
371	
372	    /// TS: `loadNodeModuleFromDirectoryWorker`
373	    fn dts_resolve_as_directory(
374	        &self,
375	        extensions: Extensions,
376	        candidate: &CachedPath,
377	        ctx: &mut Ctx,
378	    ) -> ResolveResult {
379	        if !self.is_dir(candidate, ctx) {
380	            return Ok(None);
381	        }
382	
383	        let pkg = self.cache.get_package_json(candidate, &self.options, ctx)?;
384	        let main_fields = ["main".to_string()];
385	
386	        // Try typesVersions paths
387	        if let Some(ref pkg) = pkg
388	            && let Some(version_paths) = Self::dts_get_matching_version_paths(pkg)
389	        {
390	            let mut entry = if extensions.contains(Extensions::DECLARATION) {
391	                pkg.typings().or_else(|| pkg.types())
392	            } else {
393	                None
394	            };
395	            if entry.is_none()
396	                && extensions.intersects(
397	                    Extensions::TYPESCRIPT
398	                        .union(Extensions::JAVASCRIPT)
399	                        .union(Extensions::DECLARATION),
400	                )
401	            {
402	                entry = pkg.main_fields(&main_fields).next();
403	            }
404	
405	            // TS uses getRelativePathFromDirectory to compute the specifier,
406	            // which strips the "./" prefix from package.json entry values.
407	            let vp_specifier = entry.map_or("index", |e| e.strip_prefix("./").unwrap_or(e));
408	            if let Some(path) = self.dts_resolve_via_version_paths(
409	                extensions,
410	                vp_specifier,
411	                candidate,
412	                &version_paths,
413	                ctx,
414	            )? {
415	                return Ok(Some(path));
416	            }
417	        }
418	
419	        // Determine entry file (types/typings/main)
420	        if let Some(ref pkg) = pkg {
421	            let mut entry = if extensions.contains(Extensions::DECLARATION) {
422	                pkg.typings().or_else(|| pkg.types())
423	            } else {
424	                None
425	            };
426	            if entry.is_none()
427	                && extensions.intersects(
428	                    Extensions::TYPESCRIPT
429	                        .union(Extensions::JAVASCRIPT)
430	                        .union(Extensions::DECLARATION),
431	                )
432	            {
433	                entry = pkg.main_fields(&main_fields).next();
434	            }
435	            if let Some(entry_str) = entry {
436	                // TS: "Even if extensions is DtsOnly, we can still look up a .ts file
437	                // as a result of package.json 'types'"
438	                let expanded = if extensions == Extensions::DECLARATION {
439	                    Extensions::TYPESCRIPT.union(Extensions::DECLARATION)
440	                } else {
441	                    extensions
442	                };
443	                let entry_path = candidate.normalize_with(entry_str, &self.cache);
444	                if let Some(path) = self.dts_resolve_as_file(expanded, &entry_path, ctx) {
445	                    return Ok(Some(path));
446	                }
447	                if self.is_dir(&entry_path, ctx) {
448	                    let index = entry_path.push("index", &self.cache);
449	                    if let Some(path) = self.dts_resolve_as_file(expanded, &index, ctx) {
450	                        return Ok(Some(path));
451	                    }
452	                }
453	            }
454	        }
455	
456	        // Fallback: index
457	        let index = candidate.push("index", &self.cache);
458	        Ok(self.dts_resolve_as_file(extensions, &index, ctx))
459	    }
460	
461	    // -------- node_modules resolution (TWO-PASS) --------
462	
463	    fn dts_resolve_node_modules(
464	        &self,
465	        extensions: Extensions,
466	        specifier: &str,
467	        package_name: &str,
468	        rest: &str,
469	        directory: &CachedPath,
470	        ctx: &mut Ctx,
471	    ) -> ResolveResult {
472	        let priority_exts = extensions & Extensions::TYPESCRIPT.union(Extensions::DECLARATION);
473	        let secondary_exts =
474	            extensions.difference(Extensions::TYPESCRIPT.union(Extensions::DECLARATION));
475	
476	        // PASS 1: Walk ALL ancestors for TS/DTS + @types
477	        if !priority_exts.is_empty() {
478	            for ancestor in
479	                std::iter::successors(Some(directory.clone()), |cp| cp.parent(&self.cache))
480	            {
481	                let nm = ancestor.push("node_modules", &self.cache);
482	                if !self.is_dir(&nm, ctx) {
483	                    continue;
484	                }
485	
486	                // Try implementation package
487	                if let Some(path) =
488	                    self.dts_resolve_in_node_modules_dir(priority_exts, specifier, &nm, ctx)?
489	                {
490	                    return Ok(Some(path));
491	                }
492	
493	                // Try @types
494	                if priority_exts.contains(Extensions::DECLARATION) {
495	                    let mangled = Self::dts_mangle_scoped_name(package_name);
496	                    let at_types_dir = nm.push("@types", &self.cache);
497	                    if self.is_dir(&at_types_dir, ctx) {
498	                        let at_types_specifier = if rest.is_empty() {
499	                            mangled.clone()
500	                        } else {
501	                            format!("{mangled}{rest}")
502	                        };
503	                        if let Some(path) = self.dts_resolve_in_node_modules_dir(
504	                            Extensions::DECLARATION,
505	                            &at_types_specifier,
506	                            &at_types_dir,
507	                            ctx,
508	                        )? {
509	                            return Ok(Some(path));
510	                        }
511	                    }
512	                }
513	            }
514	        }
515	
516	        // PASS 2: Walk ALL ancestors for JS only (no @types)
517	        if !secondary_exts.is_empty() {
518	            for ancestor in
519	                std::iter::successors(Some(directory.clone()), |cp| cp.parent(&self.cache))
520	            {
521	                let nm = ancestor.push("node_modules", &self.cache);
522	                if !self.is_dir(&nm, ctx) {
523	                    continue;
524	                }
525	                if let Some(path) =
526	                    self.dts_resolve_in_node_modules_dir(secondary_exts, specifier, &nm, ctx)?
527	                {
528	                    return Ok(Some(path));
529	                }
530	            }
531	        }
532	
533	        Ok(None)
534	    }
535	
536	    fn dts_resolve_in_node_modules_dir(
537	        &self,
538	        extensions: Extensions,
539	        specifier: &str,
540	        nm_dir: &CachedPath,
541	        ctx: &mut Ctx,
542	    ) -> ResolveResult {
543	        let (package_name, rest) = Self::parse_package_specifier(specifier);
544	        let pkg_dir = nm_dir.normalize_with(package_name, &self.cache);
545	
546	        if !self.is_dir(&pkg_dir, ctx) {
547	            return Ok(None);
548	        }
549	
550	        let pkg = self.cache.get_package_json(&pkg_dir, &self.options, ctx)?;
551	
552	        // PRIORITY 1: exports (blocks everything else when present)
553	        if let Some(ref pkg) = pkg
554	            && pkg.exports().is_some()
555	        {
556	            let subpath = if rest.is_empty() { ".".to_string() } else { format!(".{rest}") };
557	
558	            for exports in pkg.exports_fields(&self.options.exports_fields) {
559	                if let Ok(Some(path)) =
560	                    self.package_exports_resolve(&pkg_dir, &subpath, &exports, None, ctx)
561	                {
562	                    // Try to resolve the ESM match (file may need extension)
563	                    if let Some(resolved) = self.dts_resolve_esm_match(&path, ctx) {
564	                        return Ok(Some(resolved));
565	                    }
566	                    return Ok(Some(path));
567	                }
568	            }
569	            // exports blocks types/typings/main
570	            return Ok(None);
571	        }
572	
573	        // PRIORITY 2: typesVersions (for subpath imports: rest != "")
574	        if !rest.is_empty()
575	            && let Some(ref pkg) = pkg
576	            && let Some(version_paths) = Self::dts_get_matching_version_paths(pkg)
577	        {
578	            let rest_without_slash = rest.strip_prefix('/').unwrap_or(rest);
579	            if let Some(path) = self.dts_resolve_via_version_paths(
580	                extensions,
581	                rest_without_slash,
582	                &pkg_dir,
583	                &version_paths,
584	                ctx,
585	            )? {
586	                return Ok(Some(path));
587	            }
588	        }
589	
590	        // PRIORITY 3: standard file + directory
591	        if !rest.is_empty() {
592	            let candidate = nm_dir.normalize_with(specifier, &self.cache);
593	            if let Some(path) = self.dts_resolve_as_file(extensions, &candidate, ctx) {
594	                return Ok(Some(path));
595	            }
596	            if self.is_dir(&candidate, ctx) {
597	                return self.dts_resolve_as_directory(extensions, &candidate, ctx);
598	            }
599	        }
600	
601	        self.dts_resolve_as_directory(extensions, &pkg_dir, ctx)
602	    }
603	
604	    fn dts_resolve_esm_match(&self, cached_path: &CachedPath, ctx: &mut Ctx) -> Option<CachedPath> {
605	        // Try declaration/TS extension substitution first (e.g. .mjs -> .d.mts)
606	        let extensions = Extensions::TYPESCRIPT.union(Extensions::DECLARATION);
607	        if let Some(path) = self.dts_resolve_as_file(extensions, cached_path, ctx) {
608	            return Some(path);
609	        }
610	        // Fall back to original file if it exists
611	        if self.is_file(cached_path, ctx) {
612	            return Some(cached_path.clone());
613	        }
614	        None
615	    }
616	
617	    // -------- @types name mangling --------
618	
619	    pub(crate) fn dts_mangle_scoped_name(name: &str) -> String {
620	        name.strip_prefix('@').map_or_else(|| name.to_string(), |rest| rest.replacen('/', "__", 1))
621	    }
622	
623	    // -------- typesVersions --------
624	
625	    /// Get the first matching version path from typesVersions.
626	    ///
627	    /// TypeScript matches `*` (wildcard) as "any version", which is the common case.
628	    /// For simplicity, we match all version ranges.
629	    fn dts_get_matching_version_paths(pkg: &PackageJson) -> Option<Vec<(String, Vec<String>)>> {
630	        let types_versions = pkg.types_versions()?;
631	
632	        // TypeScript iterates versions and picks the first matching one.
633	        // The `*` key matches all versions, which is the overwhelmingly common case.
634	        for (_version_range, paths_value) in types_versions.iter() {
635	            if let Some(map) = paths_value.as_map() {
636	                let mut result = Vec::new();
637	                for (pattern, targets_entry) in map.iter() {
638	                    let targets: Vec<String> = if let Some(arr) = targets_entry.as_array() {
639	                        arr.iter().filter_map(|v| v.as_string().map(String::from)).collect()
640	                    } else if let Some(s) = targets_entry.as_string() {
641	                        vec![s.to_string()]
642	                    } else {
643	                        continue;
644	                    };
645	                    result.push((pattern.to_string(), targets));
646	                }
647	                if !result.is_empty() {
648	                    return Some(result);
649	                }
650	            }
651	        }
652	        None
653	    }
654	
655	    /// Resolve a specifier against typesVersions path mappings.
656	    fn dts_resolve_via_version_paths(
657	        &self,
658	        extensions: Extensions,
659	        specifier: &str,
660	        base_dir: &CachedPath,
661	        version_paths: &[(String, Vec<String>)],
662	        ctx: &mut Ctx,
663	    ) -> ResolveResult {
664	        for (pattern, targets) in version_paths {
665	            if let Some(matched) = Self::dts_match_pattern(pattern, specifier) {
666	                for target in targets {
667	                    let resolved_target = target.replace('*', &matched);
668	                    let candidate = base_dir.normalize_with(&resolved_target, &self.cache);
669	                    if let Some(path) = self.dts_resolve_as_file(extensions, &candidate, ctx) {
670	                        return Ok(Some(path));
671	                    }
672	                    if self.is_dir(&candidate, ctx)
673	                        && let Some(path) =
674	                            self.dts_resolve_as_directory(extensions, &candidate, ctx)?
675	                    {
676	                        return Ok(Some(path));
677	                    }
678	                }
679	            }
680	        }
681	        Ok(None)
682	    }
683	
684	    /// Match a specifier against a pattern with optional `*` wildcard.
685	    fn dts_match_pattern<'a>(pattern: &str, specifier: &'a str) -> Option<Cow<'a, str>> {
686	        if let Some((prefix, suffix)) = pattern.split_once('*') {
687	            if specifier.starts_with(prefix)
688	                && (suffix.is_empty() || specifier.ends_with(suffix))
689	                && specifier.len() >= prefix.len() + suffix.len()
690	            {
691	                let matched = &specifier[prefix.len()..specifier.len() - suffix.len()];
692	                Some(Cow::Borrowed(matched))
693	            } else {
