use oxc_resolver::{ResolveOptions, Resolver};

#[test]
fn scratch_resolve_dts_finds_at_types_react() {
    let resolver = Resolver::new(ResolveOptions {
        condition_names: vec!["types".into(), "import".into(), "require".into(), "default".into()],
        main_fields: vec!["types".into(), "typings".into(), "module".into(), "main".into()],
        extensions: vec![".ts".into(), ".tsx".into(), ".d.ts".into(), ".js".into()],
        ..ResolveOptions::default()
    });

    let from_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");

    // Plain bundler-style resolve of bare "react" — should NOT find a .d.ts
    // (react's package.json has no "types" field, this is the whole premise).
    let plain = resolver.resolve(&from_dir, "react");
    println!("plain resolve(\"react\") = {plain:?}");

    // resolve_dts should follow TS's @types fallback automatically.
    let dts = resolver.resolve_dts(&from_dir, "react");
    println!("resolve_dts(\"react\") = {dts:?}");
    match &dts {
        Ok(res) => {
            let path = res.path().to_string_lossy();
            assert!(path.contains("@types") && path.contains("react"), "expected @types/react path, got: {path}");
            assert!(path.ends_with(".d.ts"), "expected a .d.ts file, got: {path}");
        }
        Err(e) => panic!("resolve_dts(\"react\") failed: {e:?}"),
    }

    // Also check a scoped package to confirm name-mangling (@babel/core -> @types/babel__core)
    // is real if such a package exists in this workspace's node_modules; skip if not present.
    let babel = resolver.resolve_dts(&from_dir, "@babel/core");
    println!("resolve_dts(\"@babel/core\") = {babel:?}");
}

