113	/// Best-effort path to the @types/react .d.ts file for RDT propFilter compat.
114	/// Falls back to a synthetic path if @types/react is not installed.
115	pub(super) fn resolve_react_types_file(from_file: &Utf8Path, ctx: &ResolutionContext) -> String {
116	    // Try to resolve from the consuming file's directory.
117	    if let Some(from_dir) = from_file.parent() {
118	        if let Ok(resolved) = ctx.oxc_resolver.resolve(from_dir.as_std_path(), "@types/react") {
119	            return resolved.path().to_string_lossy().into_owned();
120	        }
121	    }
122	    // Fallback — synthetic path that still satisfies `node_modules` filtering.
123	    "node_modules/@types/react/index.d.ts".to_owned()
124	}
