126	/// Read `compilerOptions.paths` from a tsconfig.json and convert to `oxc_resolver`
127	/// alias format: `Vec<(pattern, Vec<AliasValue>)>`.
128	pub(super) fn read_tsconfig_paths(tsconfig: Option<&camino::Utf8Path>) -> Vec<(String, Vec<AliasValue>)> {
129	    let Some(path) = tsconfig else { return vec![] };
130	    let Ok(content) = std::fs::read_to_string(path.as_std_path()) else { return vec![] };
131	    let stripped = strip_json_comments(&content);
132	    let Ok(value) = serde_json::from_str::<serde_json::Value>(&stripped) else {
133	        return vec![];
134	    };
135	
136	    let base_url = value["compilerOptions"]["baseUrl"].as_str().map(|b| path.parent().unwrap_or(path).join(b));
137	
138	    let paths = match value["compilerOptions"]["paths"].as_object() {
139	        Some(p) => p,
140	        None => return vec![],
141	    };
142	
143	    paths
144	        .iter()
145	        .filter_map(|(pattern, targets)| {
146	            let resolved: Vec<AliasValue> = targets
147	                .as_array()?
148	                .iter()
149	                .filter_map(|t| t.as_str())
150	                .map(|t| {
151	                    // Remove trailing wildcards: "@lib/*" → "@lib/"
152	                    let t = t.trim_end_matches("/*").trim_end_matches('*');
153	                    let resolved_path =
154	                        if let Some(base) = &base_url { base.join(t) } else { path.parent().unwrap_or(path).join(t) };
155	                    AliasValue::Path(resolved_path.as_std_path().to_string_lossy().into_owned())
156	                })
157	                .collect();
158	
159	            let pattern_clean = pattern.trim_end_matches("/*").to_owned();
160	            Some((pattern_clean, resolved))
161	        })
162	        .collect()
163	}
164	
165	/// Minimal JSON comment stripper for tsconfig files.
166	/// Handles single-line `//` comments; does NOT handle block `/* */` comments.
167	pub(super) fn strip_json_comments(s: &str) -> String {
168	    s.lines()
169	        .map(|line| {
170	            if let Some(idx) = line.find("//") {
171	                // Only strip if the `//` is not inside a string.
172	                // Heuristic: count unescaped `"` before idx — if even, we're outside a string.
173	                let before = &line[..idx];
174	                let quote_count = before.chars().filter(|&c| c == '"').count();
175	                if quote_count % 2 == 0 {
176	                    return &line[..idx];
177	                }
178	            }
179	            line
180	        })
181	        .collect::<Vec<_>>()
182	        .join("\n")
183	}
