fn visit_ts_type_alias_declaration(&mut self, node: &TSTypeAliasDeclaration<'a>) {
    let name = node.id.name.as_str();
    let key = self.scoped_key(name);

    if let Some(alias) = self.classify_type_alias(name, &node.type_annotation) {
