77	pub(super) fn parse_jsdoc_text(raw: &str) -> String {
78	    // Strip `/**` prefix and `*/` suffix
79	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
80	
81	    let desc_lines: Vec<&str> = inner
82	        .lines()
83	        .map(|l| {
84	            let l = l.trim();
85	            // Strip leading `* ` or `*`
86	            let l = l.strip_prefix("* ").or_else(|| l.strip_prefix('*')).unwrap_or(l);
87	            l
88	        })
89	        .take_while(|l| !l.starts_with('@'))
90	        .collect();
91	
92	    desc_lines.join("\n").trim().to_owned()
93	}
