95	pub(super) fn extract_jsdoc_tags(raw: &str) -> BTreeMap<String, String> {
96	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
97	    let mut tags: BTreeMap<String, String> = BTreeMap::new();
98	    let mut in_tags = false;
99	
100	    for line in inner.lines() {
101	        let line = line.trim();
102	        let line = line.strip_prefix("* ").or_else(|| line.strip_prefix('*')).unwrap_or(line);
103	        let line = line.trim();
104	
105	        if let Some(rest) = line.strip_prefix('@') {
106	            in_tags = true;
107	            // Parse tag: `@tagname rest`
108	            let (tag, value) = if let Some(sp) = rest.find(char::is_whitespace) {
109	                let tag = &rest[..sp];
110	                let value = rest[sp..].trim();
111	                (tag, value)
112	            } else {
113	                (rest, "")
114	            };
115	
116	            // Special handling for @param — store as `param:propName`
117	            if tag == "param" {
118	                // `@param propName description` or `@param {type} propName description`
119	                let value = value.trim_start_matches('{');
120	                // Skip {type} if present
121	                let value =
122	                    if value.contains('}') { value.split_once('}').map(|x| x.1).unwrap_or("").trim() } else { value };
123	                // First word is the prop name
124	                if let Some(space) = value.find(char::is_whitespace) {
125	                    let prop_name = &value[..space];
126	                    let desc = value[space..].trim();
127	                    tags.insert(format!("param:{}", prop_name), desc.to_owned());
128	                } else if !value.is_empty() {
129	                    tags.insert(format!("param:{}", value), String::new());
130	                }
131	            } else {
132	                tags.insert(tag.to_owned(), value.to_owned());
133	            }
134	        } else if in_tags && !line.is_empty() {
135	            // Continuation of a tag — ignore for now
136	        }
137	    }
138	
139	    tags
140	}
