117	/// Resolve a `CollectedType` as a props chain (for base types in aliases).
118	pub(super) fn resolve_base_as_chain(
119	    base: &CollectedType,
120	    file_path: &Utf8Path,
121	    mapping: &ComponentMapping,
122	    ctx: &ResolutionContext,
123	    state: &mut ResolveState,
124	    depth: u8,
125	) -> ResolvedChain {
126	    match base {
127	        CollectedType::Named { name, args } => {
128	            // Omit/Pick/Partial/Readonly applied to a *structured* reference — e.g. a
129	            // member of `Omit<T, keyof U> & U` after `T`/`U` were substituted with real
130	            // types (see resolver/substitute.rs). Handled directly here, rather than via
131	            // the string-based `resolve_props_chain` path below, so nested generics and
132	            // `keyof` operands survive structurally instead of being flattened to a
133	            // single opaque display string first.
134	            if let Some(alias) = super::substitute::synthesize_utility_alias(name.as_str(), args, file_path) {
135	                return resolve_type_alias_chain(&alias, file_path, mapping, ctx, state, depth);
136	            }
137	
138	            // A user-defined generic alias referenced with structured (possibly
139	            // cross-file, possibly nested-generic) arguments — e.g.
140	            // `SelectRootBaseProps<T>` used as `Assign<T, U>`'s own `U` argument.
141	            // Substituted and resolved directly here so the nested generic survives,
142	            // rather than falling through to the string-based path below (which would
143	            // flatten it to a single opaque display string before substitution ever ran).
144	            if let Some(alias) = super::substitute::generic_alias_with_structured_args(
145	                name.as_str(),
146	                args,
147	                file_path,
148	                ctx,
149	                &mut state.diagnostics,
150	            ) {
151	                return resolve_type_alias_chain(&alias, file_path, mapping, ctx, state, depth + 1);
152	            }
153	
154	            let raw_args: Vec<String> = args.iter().map(|a| a.to_raw_string()).collect();
155	            resolve_props_chain(name.as_str(), &raw_args, file_path, mapping, ctx, state, depth + 1)
156	        }
157	        // Generic-alias substitution marker (see resolver/substitute.rs and the
158	        // `CollectedType::AtFile` doc comment): `inner` was written in `file`, not
159	        // whatever file this call chain has been resolving relative to — e.g. a
160	        // type argument substituted from the caller's scope into a callee alias
161	        // declared in a different file. Switch file context and continue.
162	        CollectedType::AtFile { file, inner } => resolve_base_as_chain(inner, file, mapping, ctx, state, depth),
163	        CollectedType::Intersection(members) => {
164	            let mut chain = ResolvedChain::default();
165	            for member in members {
166	                let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
167	                chain.merge_parent(sub);
168	            }
169	            chain
170	        }
171	        CollectedType::Object(fields) => {
172	            // Inline object type in an intersection: `ComponentPropsWithoutRef<'button'> & { asChild?: boolean }`
173	            // Expand the object fields directly as own props.
174	            let mut chain = ResolvedChain::default();
175	            for field in fields {
176	                let prop_type = resolve_collected_type(&field.collected_type, file_path, ctx, state, depth);
177	                chain.props.push(ParsedProp {
178	                    name: field.name.clone(),
179	                    prop_type,
180	                    required: field.required,
181	                    default_value: None,
182	                    description: field.description.clone(),
183	                    tags: Default::default(),
184	                    parent: None,
185	                    declarations: vec![],
186	                });
187	            }
188	            chain
189	        }
190	        CollectedType::Union(members) => {
191	            // Union base: merge all members together.
192	            // This handles `Omit<A | B, K>` and similar patterns.
193	            let mut chain = ResolvedChain::default();
194	            for member in members {
195	                let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
196	                chain.merge_parent(sub);
197	            }
198	            chain
199	        }
200	        _ => ResolvedChain::default(),
201	    }
202	}
