204	/// Resolve a `CollectedTypeAlias::Union` — detect discriminated union if possible.
205	#[allow(clippy::too_many_arguments)]
206	pub(super) fn resolve_union_alias(
207	    members: &[CollectedType],
208	    file_path: &Utf8Path,
209	    mapping: &ComponentMapping,
210	    ctx: &ResolutionContext,
211	    state: &mut ResolveState,
212	    depth: u8,
213	) -> ResolvedChain {
214	    use super::chain::find_discriminant_prop;
215	
216	    // Collect all member chains for named types (only Named can be discriminated).
217	    let named_members: Vec<(&str, Vec<ParsedProp>)> = members
218	        .iter()
219	        .filter_map(|m| {
220	            if let CollectedType::Named { name, .. } = m {
221	                let mut branch_state = ResolveState { visited: state.visited.clone(), diagnostics: vec![] };
222	                let chain =
223	                    resolve_props_chain(name.as_str(), &[], file_path, mapping, ctx, &mut branch_state, depth + 1);
224	                state.diagnostics.extend(branch_state.diagnostics);
225	                Some((name.as_str(), chain.props))
226	            } else {
227	                None
228	            }
229	        })
230	        .collect();
231	
232	    if named_members.len() < 2 {
233	        // Not a discriminated union — just merge all.
234	        let mut chain = ResolvedChain::default();
235	        for member in members {
236	            let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
237	            chain.merge_parent(sub);
238	        }
239	        return chain;
240	    }
241	
242	    // Try to find a discriminant prop (a prop whose type is a distinct string literal across all members).
243	    let discriminant = find_discriminant_prop(&named_members);
244	
245	    // Merge all props from all members. A prop's merged type is the union of every
246	    // distinct type it has across the members that declare it (deduped — two members
247	    // contributing the identical type must not produce a redundant single-member
248	    // union); a prop missing from at least one member becomes optional overall, even
249	    // if it was required in every member where it does appear, since the union type
250	    // doesn't guarantee its presence.
251	    let mut merged_props: BTreeMap<String, ParsedProp> = BTreeMap::new();
252	    let mut prop_types: BTreeMap<String, Vec<PropType>> = BTreeMap::new();
253	    let mut seen_count: BTreeMap<String, usize> = BTreeMap::new();
254	    let mut required_in_all: BTreeMap<String, bool> = BTreeMap::new();
255	    let mut total_variants: usize = 0;
256	
257	    for (_, member_props) in &named_members {
258	        total_variants += 1;
259	        record_variant_props(member_props, &mut merged_props, &mut prop_types, &mut seen_count, &mut required_in_all);
260	    }
261	
262	    // Also merge non-Named members (inline objects, intersections, nested unions, etc.)
263	    // that were excluded from the discriminant analysis above.
264	    for member in members {
265	        if !matches!(member, CollectedType::Named { .. }) {
266	            let sub_chain = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
267	            total_variants += 1;
268	            record_variant_props(
269	                &sub_chain.props,
270	                &mut merged_props,
271	                &mut prop_types,
272	                &mut seen_count,
273	                &mut required_in_all,
274	            );
275	        }
276	    }
277	
278	    for (name, mut types) in prop_types {
279	        let prop_type = match types.len() {
280	            0 | 1 => match types.pop() {
281	                Some(t) => t,
282	                None => continue,
283	            },
284	            _ => PropType::Union(types),
285	        };
286	
287	        if let Some(entry) = merged_props.get_mut(&name) {
288	            entry.prop_type = prop_type;
289	            let present_everywhere = seen_count.get(&name).copied().unwrap_or(0) == total_variants;
290	            let required_everywhere = required_in_all.get(&name).copied().unwrap_or(false);
291	            entry.required = present_everywhere && required_everywhere;
292	        }
293	    }
294	
295	    // If we found a discriminant, merge its type as a union of all its literal values.
296	    if let Some(ref disc_name) = discriminant {
297	        let disc_literals: Vec<PropType> = named_members
298	            .iter()
299	            .filter_map(|(_, props)| props.iter().find(|p| &p.name == disc_name).map(|p| p.prop_type.clone()))
300	            .collect();
301	
302	        if let Some(disc_prop) = merged_props.get_mut(disc_name) {
303	            disc_prop.prop_type = PropType::Union(disc_literals);
304	        }
305	    }
306	
307	    // Emit discriminated union diagnostic if applicable.
308	    if discriminant.is_some() {
309	        state.diagnostics.push(Diagnostic {
310	            severity: DiagnosticSeverity::Info,
311	            message: format!(
312	                "Discriminated union detected with discriminant prop '{}'",
313	                discriminant.as_deref().unwrap_or("")
314	            ),
315	            file: Some(file_path.to_string()),
316	            line: None,
317	            column: None,
318	            help: None,
319	            code: DiagnosticCode::DiscriminatedUnion,
320	        });
321	    }
322	
323	    ResolvedChain { props: merged_props.into_values().collect(), discriminant_prop: discriminant, ..Default::default() }
324	}
