326	/// Record one union member's props into the shared merge accumulators: the
327	/// first-seen `ParsedProp` (for name/description/parent/etc.), the set of
328	/// distinct types contributed for each prop name, how many members declared
329	/// it, and whether every member that declared it marked it required.
330	fn record_variant_props(
331	    props: &[ParsedProp],
332	    merged_props: &mut BTreeMap<String, ParsedProp>,
333	    prop_types: &mut BTreeMap<String, Vec<PropType>>,
334	    seen_count: &mut BTreeMap<String, usize>,
335	    required_in_all: &mut BTreeMap<String, bool>,
336	) {
337	    for prop in props {
338	        merged_props.entry(prop.name.clone()).or_insert_with(|| prop.clone());
339	
340	        let types = prop_types.entry(prop.name.clone()).or_default();
341	        if !types.contains(&prop.prop_type) {
342	            types.push(prop.prop_type.clone());
343	        }
344	
345	        *seen_count.entry(prop.name.clone()).or_insert(0) += 1;
346	
347	        required_in_all
348	            .entry(prop.name.clone())
349	            .and_modify(|required| *required = *required && prop.required)
350	            .or_insert(prop.required);
351	    }
352	}
