354	/// Resolve a `CollectedTypeAlias` to a `PropType` (at the type level, not chain level).
355	pub(super) fn resolve_type_alias_type(
356	    alias: &CollectedTypeAlias,
357	    consuming_file: &Utf8Path,
358	    ctx: &ResolutionContext,
359	    state: &mut ResolveState,
360	    depth: u8,
361	) -> PropType {
362	    match alias {
363	        CollectedTypeAlias::LiteralUnion { members, .. } => {
364	            PropType::LiteralUnion { members: members.clone(), has_default: false }
365	        }
366	        CollectedTypeAlias::Passthrough { target, .. } => {
367	            resolve_collected_type(target, consuming_file, ctx, state, depth + 1)
368	        }
369	        CollectedTypeAlias::Union { members, .. } => {
370	            let resolved: Vec<PropType> =
371	                members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect();
372	            PropType::Union(resolved)
373	        }
374	        CollectedTypeAlias::Intersection { members, .. } => {
375	            let resolved: Vec<PropType> =
376	                members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect();
377	            PropType::Intersection(resolved)
378	        }
379	        CollectedTypeAlias::Partial { base, .. } | CollectedTypeAlias::Required { base, .. } => {
380	            resolve_collected_type(base, consuming_file, ctx, state, depth + 1)
381	        }
382	        CollectedTypeAlias::Omit { base, .. } | CollectedTypeAlias::Pick { base, .. } => {
383	            // At the type level, just forward to the base type.
384	            resolve_collected_type(base, consuming_file, ctx, state, depth + 1)
385	        }
386	    }
387	}
