357	    alias: &CollectedTypeAlias,
358	    consuming_file: &Utf8Path,
359	    ctx: &ResolutionContext,
360	    state: &mut ResolveState,
361	    depth: u8,
362	) -> PropType {
363	    match alias {
364	        CollectedTypeAlias::LiteralUnion { members, .. } => {
365	            PropType::LiteralUnion { members: members.clone(), has_default: false }
366	        }
367	        CollectedTypeAlias::Passthrough { target, .. } => {
368	            resolve_collected_type(target, consuming_file, ctx, state, depth + 1)
369	        }
370	        CollectedTypeAlias::Union { members, .. } => {
371	            let resolved: Vec<PropType> =
372	                members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect();
