374	        }
375	        CollectedTypeAlias::Intersection { members, .. } => {
376	            let resolved: Vec<PropType> =
377	                members.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect();
378	            PropType::Intersection(resolved)
379	        }
