29	/// Built once, then read by all parallel resolution workers.
30	/// Uses Arc in pipeline — clone is cheap.
31	#[derive(Debug, Default, Clone)]
32	pub struct GlobalSourceData {
33	    /// All interfaces across all files.
34	    /// Key: "${absolute_file_path}:${name}" — always scoped, never bare
