46	    /// Key: "${absolute_file_path}:${name}"
47	    pub enums: FxHashMap<String, Vec<EnumEntry>>,
48	
49	    /// Import resolution map: file → [ImportBinding]
50	    pub import_map: FxHashMap<Utf8PathBuf, Vec<ImportBinding>>,
51	
52	    /// Re-export map: file → [LexedExport]
53	    pub re_export_map: FxHashMap<Utf8PathBuf, Vec<LexedExport>>,
