59	impl GlobalSourceData {
60	    /// Merge a single file's SourceData into the global data.
61	    pub fn merge(&mut self, file_path: &Utf8Path, data: SourceData) {
62	        for (key, iface) in data.interfaces {
63	            match self.interfaces.entry(key) {
64	                std::collections::hash_map::Entry::Occupied(mut e) => {
65	                    // Declaration merging: combine props and extends
66	                    let existing = e.get_mut();
67	                    existing.props.extend(iface.props);
68	                    existing.extends.extend(iface.extends);
69	                }
70	                std::collections::hash_map::Entry::Vacant(e) => {
71	                    e.insert(iface);
72	                }
73	            }
74	        }
75	        self.type_aliases.extend(data.type_aliases);
76	        self.type_alias_params.extend(data.type_alias_params);
77	        self.enums.extend(data.enums);
78	        self.import_map.insert(file_path.to_owned(), data.imports);
79	        self.re_export_map.insert(file_path.to_owned(), data.exports);
80	        self.component_mappings.extend(data.component_mappings);
81	    }
82	
83	    /// Remove all entries contributed by `file_path`. Called before re-merging an updated file.
84	    pub fn remove_file(&mut self, file_path: &Utf8Path) {
85	        let prefix = format!("{}:", file_path);
86	        self.interfaces.retain(|k, _| !k.starts_with(&prefix));
87	        self.type_aliases.retain(|k, _| !k.starts_with(&prefix));
88	        self.type_alias_params.retain(|k, _| !k.starts_with(&prefix));
89	        self.enums.retain(|k, _| !k.starts_with(&prefix));
90	        self.import_map.remove(file_path);
91	        self.re_export_map.remove(file_path);
92	        self.component_mappings.retain(|m| m.file_path != file_path);
93	    }
94	}
