14	    ctx: &ResolutionContext,
15	    diagnostics: &mut Vec<Diagnostic>,
16	) -> Option<(Utf8PathBuf, String)> {
17	    let import_ref = ctx.import_map.find_import(consuming_file, name)?;
18	
