26	/// Use `oxc_resolver` to turn an import specifier into an absolute file path.
27	pub(super) fn resolve_import_specifier(
28	    specifier: &str,
29	    from_file: &Utf8Path,
30	    ctx: &ResolutionContext,
31	    diagnostics: &mut Vec<Diagnostic>,
32	) -> Option<Utf8PathBuf> {
33	    let from_dir = from_file.parent()?;
34	
35	    // Bare package specifiers (not relative/absolute) need real TypeScript
36	    // declaration resolution: prefer a real .d.ts over whatever JS entry point
37	    // the package's own "main"/"exports" happens to point to, and fall back to
38	    // the separate `@types/<package>` package when the package ships no types
39	    // of its own at all — e.g. "react": its package.json has no "types" field
40	    // and no "types" export condition, so a plain `resolve()` below lands on
