100	/// Execute `docgen.config.ts` at `path` and map its default export onto
101	/// [`PipelineOptions`].
102	///
103	/// A config file that fails to evaluate, or evaluates to something that doesn't
104	/// match [`DocgenConfigSchema`] (a typo'd key, wrong value type, or a field this
105	/// module doesn't support yet), is a hard error rather than silently falling back
106	/// to defaults — crates/core/CLAUDE.md non-negotiable #6: never fail silently. A
107	/// config a user explicitly wrote getting quietly ignored is a plausible-looking
108	/// but wrong result forever.
109	pub fn try_load_config(path: &std::path::Path) -> Result<Option<PipelineOptions>> {
110	    use std::io::Write;
111	
112	    // Pass the config path via environment variable to avoid any path content
113	    // being interpreted as JavaScript (command injection via crafted filenames).
114	    let script = "import { pathToFileURL } from 'node:url';\
115	        const p = process.env.__DOCGEN_CONFIG_PATH;\
116	        const m = await import(pathToFileURL(p).href);\
117	        process.stdout.write(JSON.stringify(m.default ?? m));";
118	
119	    let mut command = std::process::Command::new("node");
120	    command
121	        .args(["--input-type=module"])
122	        .env("NODE_OPTIONS", "--import=tsx/esm")
123	        .env("__DOCGEN_CONFIG_PATH", path)
124	        .stdin(std::process::Stdio::piped())
125	        .stdout(std::process::Stdio::piped())
126	        .stderr(std::process::Stdio::null());
127	    // Resolve `tsx` (and anything the config file itself imports) relative to the
128	    // config file's own directory, not wherever the CLI happened to be invoked
129	    // from — matters for `--config ../other-project/docgen.config.ts` pointing
130	    // outside the current project, and for a project whose `tsx` devDependency
131	    // isn't hoisted to whatever the caller's own cwd happens to be.
132	    if let Some(dir) = path.parent() {
133	        command.current_dir(dir);
134	    }
135	    let mut child = command.spawn().into_diagnostic()?;
136	
137	    // Write the script to stdin, then close stdin to signal EOF.
138	    let mut stdin =
139	        child.stdin.take().ok_or_else(|| miette::miette!("failed to open stdin for the node subprocess"))?;
140	    stdin.write_all(script.as_bytes()).into_diagnostic()?;
141	    drop(stdin);
142	
143	    let output = child.wait_with_output().into_diagnostic()?;
144	
145	    if !output.status.success() {
146	        return Err(miette::miette!(
147	            help = "Check docgen.config.ts for syntax errors, or remove it to use defaults.",
148	            "docgen.config.ts at {} failed to evaluate ({})",
149	            path.display(),
150	            output.status,
151	        ));
152	    }
153	
154	    let schema: DocgenConfigSchema = serde_json::from_slice(&output.stdout).map_err(|e| {
155	        miette::miette!(
156	            help = "Check docgen.config.ts's exported fields against the supported schema \
157	                    (srcDirs, excludePatterns, excludePrefixes, reactVersion, crossPackage, \
158	                    pandacssOutdir, variantFunctions, htmlAttributes, tsconfigPath, \
159	                    vanillaExtract, cacheDir).",
160	            "docgen.config.ts at {} doesn't match the expected shape: {}",
161	            path.display(),
162	            e,
163	        )
164	    })?;
165	
166	    Ok(Some(schema.into_pipeline_options()))
167	}
