/// Look up an interface by canonical `(file, name)`, falling back first to a
/// `React.`-namespace-qualified key (`@types/react` declares everything
/// inside `declare namespace React { ... }`, so real declarations are keyed
/// "React.HTMLAttributes" even though nothing imports them that way — a plain
/// `import type { HTMLAttributes } from "react"` binds the bare name), then
/// to TypeScript's own lib.es5.d.ts/lib.dom.d.ts (native/DOM globals like
/// `Date` are never imported at all, so `canonical_file` is just wherever the
/// same-file fallback landed — check the real declaration files last).
pub(super) fn lookup_interface<'g>(
    ctx: &'g ResolutionContext,
    canonical_file: &str,
    canonical_name: &str,
) -> Option<&'g CollectedInterface> {
    if let Some(iface) = ctx.global.interfaces.get(&format!("{canonical_file}:{canonical_name}")) {
        return Some(iface);
    }
    if let Some(iface) = ctx.global.interfaces.get(&format!("{canonical_file}:React.{canonical_name}")) {
        return Some(iface);
    }
    ctx.ambient_global_files.iter().find_map(|lib_file| ctx.global.interfaces.get(&format!("{lib_file}:{canonical_name}")))
}

/// Same as `lookup_interface`, for type aliases. Returns the key that actually
/// matched (bare, `React.`-qualified, or an ambient lib file) alongside the
/// value, since callers also need it to look up `type_alias_params` under the
/// same key.
pub(super) fn lookup_type_alias<'g>(
    ctx: &'g ResolutionContext,
    canonical_file: &str,
    canonical_name: &str,
) -> Option<(String, &'g CollectedTypeAlias)> {
    let bare_key = format!("{canonical_file}:{canonical_name}");
    if let Some(alias) = ctx.global.type_aliases.get(&bare_key) {
        return Some((bare_key, alias));
    }
    let qualified_key = format!("{canonical_file}:React.{canonical_name}");
    if let Some(alias) = ctx.global.type_aliases.get(&qualified_key) {
        return Some((qualified_key, alias));
    }
    ctx.ambient_global_files.iter().find_map(|lib_file| {
        let key = format!("{lib_file}:{canonical_name}");
        ctx.global.type_aliases.get(&key).map(|alias| (key, alias))
    })
}

