13	// ─── ResolveState ─────────────────────────────────────────────────────────────
14	
15	/// Mutable resolution state threaded through all resolver functions.
16	/// Bundles the two fields that every recursive resolver function needs,
17	/// eliminating long argument signatures.
18	#[derive(Default)]
19	pub(crate) struct ResolveState {
20	    /// Cycle-detection set: "${file}:${type_name}" keys.
21	    pub(crate) visited: FxHashSet<CompactString>,
22	    /// Accumulated non-fatal issues.
23	    pub(crate) diagnostics: Vec<Diagnostic>,
24	    /// Declared generic type parameter names (`TData`, `T`, `U`, ...) seen so far
25	    /// while resolving this component — accumulated as interfaces/aliases with
26	    /// their own type parameters are entered, never removed. A bare reference to
27	    /// one of these names is an expected, unexpandable generic placeholder, not
28	    /// a broken/missing type — see `resolver::named::resolve_named`.
29	    pub(crate) in_scope_type_params: FxHashSet<CompactString>,
30	}
31	
32	// ─── GlobalSourceData ─────────────────────────────────────────────────────────
33	
34	/// Merged source data from all files — the shared resolution context.
35	/// Built once, then read by all parallel resolution workers.
36	/// Uses Arc in pipeline — clone is cheap.
37	#[derive(Debug, Default, Clone)]
38	pub struct GlobalSourceData {
39	    /// All interfaces across all files.
40	    /// Key: "${absolute_file_path}:${name}" — always scoped, never bare
41	    pub interfaces: FxHashMap<String, CollectedInterface>,
42	
43	    /// All type aliases across all files.
44	    /// Key: "${absolute_file_path}:${name}"
45	    pub type_aliases: FxHashMap<String, CollectedTypeAlias>,
46	
47	    /// Declared type parameter names for generic type alias declarations — see
48	    /// `SourceData::type_alias_params`. Key: "${absolute_file_path}:${name}"
49	    pub type_alias_params: FxHashMap<String, Vec<TypeName>>,
50	
51	    /// Declared type parameter names for generic interface declarations — see
52	    /// `SourceData::interface_type_params`. Key: "${absolute_file_path}:${name}"
53	    pub interface_type_params: FxHashMap<String, Vec<TypeName>>,
54	
55	    /// All enum-like definitions across all files.
56	    /// Key: "${absolute_file_path}:${name}"
57	    pub enums: FxHashMap<String, Vec<EnumEntry>>,
58	
59	    /// Import resolution map: file → [ImportBinding]
60	    pub import_map: FxHashMap<Utf8PathBuf, Vec<ImportBinding>>,
61	
62	    /// Re-export map: file → [LexedExport]
63	    pub re_export_map: FxHashMap<Utf8PathBuf, Vec<LexedExport>>,
64	
65	    /// All component mappings discovered
66	    pub component_mappings: Vec<ComponentMapping>,
67	}
68	
69	impl GlobalSourceData {
70	    /// Merge a single file's SourceData into the global data.
71	    pub fn merge(&mut self, file_path: &Utf8Path, data: SourceData) {
72	        for (key, iface) in data.interfaces {
73	            match self.interfaces.entry(key) {
74	                std::collections::hash_map::Entry::Occupied(mut e) => {
75	                    // Declaration merging: combine props and extends
76	                    let existing = e.get_mut();
77	                    existing.props.extend(iface.props);
78	                    existing.extends.extend(iface.extends);
79	                }
80	                std::collections::hash_map::Entry::Vacant(e) => {
81	                    e.insert(iface);
82	                }
83	            }
84	        }
85	        self.type_aliases.extend(data.type_aliases);
86	        self.type_alias_params.extend(data.type_alias_params);
87	        self.interface_type_params.extend(data.interface_type_params);
88	        self.enums.extend(data.enums);
89	        self.import_map.insert(file_path.to_owned(), data.imports);
90	        self.re_export_map.insert(file_path.to_owned(), data.exports);
91	        self.component_mappings.extend(data.component_mappings);
92	    }
93	
94	    /// Remove all entries contributed by `file_path`. Called before re-merging an updated file.
95	    pub fn remove_file(&mut self, file_path: &Utf8Path) {
96	        let prefix = format!("{}:", file_path);
97	        self.interfaces.retain(|k, _| !k.starts_with(&prefix));
98	        self.type_aliases.retain(|k, _| !k.starts_with(&prefix));
99	        self.type_alias_params.retain(|k, _| !k.starts_with(&prefix));
100	        self.interface_type_params.retain(|k, _| !k.starts_with(&prefix));
101	        self.enums.retain(|k, _| !k.starts_with(&prefix));
102	        self.import_map.remove(file_path);
103	        self.re_export_map.remove(file_path);
104	        self.component_mappings.retain(|m| m.file_path != file_path);
105	    }
106	}
