    let source = r#"
        interface ButtonProps { label: string; }
        const InternalCompoundedButton = React.forwardRef<HTMLButtonElement, ButtonProps>((props, ref) => {
            return null;
        });
        const Button = InternalCompoundedButton;
        export default Button;
