90	pub fn serialize_rdt(output: &oxc_react_docgen_core::types::ExtractionOutput) -> String {
91	    // RDT-compatible shape: flatten to Record<string, ComponentDoc>
92	    let mut map = serde_json::Map::new();
93	    for (name, entry) in &output.components {
94	        let props: serde_json::Map<String, serde_json::Value> = entry
95	            .props
96	            .iter()
97	            .map(|(k, prop)| {
98	                let obj = serde_json::json!({
99	                    "name": prop.name,
100	                    "type": rdt_type_json(&prop.prop_type),
101	                    "required": prop.required,
102	                    "defaultValue": prop.default_value.as_ref().map(|d| serde_json::json!({"value": d.value, "computed": d.computed})),
103	                    "description": prop.description,
104	                    "parent": prop.parent.as_ref().map(|p| serde_json::json!({"name": p.name, "fileName": p.file_name})),
105	                });
106	                (k.clone(), obj)
107	            })
108	            .collect();
109	        map.insert(
110	            name.clone(),
111	            serde_json::json!({
112	                "displayName": entry.display_name,
113	                "props": serde_json::Value::Object(props),
114	                "description": entry.description,
115	                "methods": [],
116	                "tags": entry.tags,
117	            }),
118	        );
119	    }
120	    serde_json::to_string_pretty(&serde_json::Value::Object(map)).unwrap_or_default()
121	}
