fn config_schema_rejects_a_typo_d_react_version_instead_of_defaulting() {
    // Adversarial review finding: a typo'd reactVersion silently defaulted
    // to react19 with no error at all.
    let json = r#"{ "reactVersion": "react20" }"#;
