3	use camino::{Utf8Path, Utf8PathBuf};
4	
5	use crate::types::*;
6	
7	use super::ResolutionContext;
8	
9	/// Resolve `name` to its canonical `(file_path, name)` pair.
10	/// Returns `None` if `name` is a local declaration (not imported).
11	pub(super) fn resolve_to_canonical(
12	    name: &str,
13	    consuming_file: &Utf8Path,
14	    ctx: &ResolutionContext,
15	    diagnostics: &mut Vec<Diagnostic>,
16	) -> Option<(Utf8PathBuf, String)> {
17	    if let Some(import_ref) = ctx.import_map.find_import(consuming_file, name) {
18	        let resolved_file = resolve_import_specifier(&import_ref.specifier, consuming_file, ctx, diagnostics)?;
19	        let canonical_name = import_ref.exported_name.to_string();
20	        return Some((resolved_file, canonical_name));
21	    }
22	
23	    // Namespace-import member access: `import * as React from "react"` then a
24	    // reference to `React.DependencyList`. `find_import` only tracks the
25	    // namespace binding itself ("React", with `exported_name == "*"`) — a
26	    // literal dotted name like "React.DependencyList" is never itself a
27	    // binding, so the lookup above always misses it. Split off the namespace
28	    // prefix and route the member name through the namespace's own import
29	    // specifier instead.
30	    let (namespace, member) = name.split_once('.')?;
31	    let namespace_ref = ctx.import_map.find_import(consuming_file, namespace)?;
32	    if namespace_ref.exported_name != "*" {
33	        return None;
34	    }
35	    let resolved_file = resolve_import_specifier(&namespace_ref.specifier, consuming_file, ctx, diagnostics)?;
36	    Some((resolved_file, member.to_string()))
37	}
38	
39	/// Look up an interface by canonical `(file, name)`, falling back to a
40	/// `React.`-namespace-qualified key. `@types/react` declares everything
41	/// inside `declare namespace React { ... }`, so real declarations are keyed
42	/// "React.HTMLAttributes" even though nothing imports them that way — a plain
43	/// `import type { HTMLAttributes } from "react"` binds the bare name.
44	pub(super) fn lookup_interface<'g>(
45	    global: &'g GlobalSourceData,
46	    canonical_file: &str,
47	    canonical_name: &str,
48	) -> Option<&'g CollectedInterface> {
49	    global
50	        .interfaces
51	        .get(&format!("{canonical_file}:{canonical_name}"))
52	        .or_else(|| global.interfaces.get(&format!("{canonical_file}:React.{canonical_name}")))
53	}
54	
55	/// Same as `lookup_interface`, for type aliases. Returns the key that actually
56	/// matched (bare or `React.`-qualified) alongside the value, since callers
57	/// also need it to look up `type_alias_params` under the same key.
58	pub(super) fn lookup_type_alias<'g>(
59	    global: &'g GlobalSourceData,
60	    canonical_file: &str,
61	    canonical_name: &str,
62	) -> Option<(String, &'g CollectedTypeAlias)> {
63	    let bare_key = format!("{canonical_file}:{canonical_name}");
64	    if let Some(alias) = global.type_aliases.get(&bare_key) {
65	        return Some((bare_key, alias));
66	    }
67	    let qualified_key = format!("{canonical_file}:React.{canonical_name}");
68	    global.type_aliases.get(&qualified_key).map(|alias| (qualified_key, alias))
69	}
70	
71	/// Same as `lookup_interface`, but also falls back to TypeScript's own ambient
72	/// lib files (`ctx.ambient_global_files`) when the name isn't found via
73	/// import/same-file resolution — e.g. `HTMLDivElement`, declared ambiently in
74	/// `lib.dom.d.ts`, is never imported, so `resolve_to_canonical` never resolves
75	/// it to that file and `canonical_file` stays the consuming file instead.
76	pub(super) fn lookup_interface_including_ambient<'g>(
77	    ctx: &'g ResolutionContext,
78	    canonical_file: &str,
79	    canonical_name: &str,
80	) -> Option<&'g CollectedInterface> {
81	    lookup_interface(&ctx.global, canonical_file, canonical_name).or_else(|| {
82	        ctx.ambient_global_files
83	            .iter()
84	            .find_map(|lib_file| ctx.global.interfaces.get(&format!("{lib_file}:{canonical_name}")))
85	    })
86	}
87	
88	/// Look up a name directly on TypeScript's own ambient lib files
89	/// (`ctx.ambient_global_files` — `lib.es5.d.ts`/`lib.dom.d.ts`), by bare name
90	/// only (these are ambient globals, never namespace-qualified). Deliberately
91	/// separate from — and only ever consulted AFTER — every other resolution
92	/// path (imports, same-file declarations, the well-known-TS-utility-type
93	/// silent list): `Record`/`Partial`/etc. are themselves declared here too
94	/// (`Record<K, T> = { [P in K]: T }`, a mapped type this tool can't expand),
95	/// so checking this first would intercept those already-handled names and
96	/// degrade them to Opaque instead of leaving them to the existing shortcuts.
97	pub(super) fn lookup_ambient_global<'g>(ctx: &'g ResolutionContext, name: &str) -> Option<AmbientGlobalLookup<'g>> {
98	    for lib_file in &ctx.ambient_global_files {
99	        let key = format!("{lib_file}:{name}");
100	        if ctx.global.interfaces.contains_key(&key) {
101	            return Some(AmbientGlobalLookup::Interface);
102	        }
103	        if let Some(alias) = ctx.global.type_aliases.get(&key) {
104	            return Some(AmbientGlobalLookup::TypeAlias(alias));
105	        }
106	    }
107	    None
108	}
109	
110	pub(super) enum AmbientGlobalLookup<'g> {
111	    Interface,
112	    TypeAlias(&'g CollectedTypeAlias),
113	}
114	
115	/// Use `oxc_resolver` to turn an import specifier into an absolute file path.
116	pub(super) fn resolve_import_specifier(
117	    specifier: &str,
118	    from_file: &Utf8Path,
119	    ctx: &ResolutionContext,
120	    diagnostics: &mut Vec<Diagnostic>,
121	) -> Option<Utf8PathBuf> {
122	    let from_dir = from_file.parent()?;
123	
124	    // Bare package specifiers (not relative/absolute) need real TypeScript
125	    // declaration resolution: prefer a real .d.ts over whatever JS entry point
126	    // the package's own "main"/"exports" happens to point to, and fall back to
127	    // the separate `@types/<package>` package when the package ships no types
128	    // of its own at all — e.g. "react": its package.json has no "types" field
129	    // and no "types" export condition, so a plain `resolve()` below lands on
130	    // `index.js`, and a named type-only import like `HTMLAttributes` can never
131	    // be found there.
132	    if !specifier.starts_with('.') && !specifier.starts_with('/') {
133	        if let Some(path) = super::react::resolve_package_types_file(&ctx.oxc_resolver, from_dir, specifier) {
134	            return Utf8PathBuf::from_path_buf(std::path::PathBuf::from(path)).ok();
135	        }
136	    }
137	
138	    match ctx.oxc_resolver.resolve(from_dir.as_std_path(), specifier) {
139	        Ok(resolved) => Utf8PathBuf::from_path_buf(resolved.path().to_owned()).ok(),
140	        Err(e) => {
141	            diagnostics.push(Diagnostic {
142	                severity: DiagnosticSeverity::Warning,
143	                message: format!("Cannot resolve '{}' from '{}'", specifier, from_file),
144	                file: Some(from_file.to_string()),
145	                line: None,
146	                column: None,
147	                help: Some(format!("Resolution error: {}", e)),
148	                code: DiagnosticCode::UnresolvableImport,
149	            });
150	            None
151	        }
152	    }
153	}
