2	//!
3	//! Answers the question: "in file F, the name N was imported — what specifier and
4	//! canonical name does it refer to?"  Actual path resolution (specifier → absolute
5	//! path) is left to the caller via `oxc_resolver`.
6	
7	use camino::{Utf8Path, Utf8PathBuf};
