13	// ─── Public Types ─────────────────────────────────────────────────────────────
14	
15	/// Where an imported name comes from, as written in the source.
16	#[derive(Debug, Clone)]
17	pub struct ImportRef {
18	    /// The import specifier as written: `"@radix-ui/react-button"`, `"./types"`, etc.
19	    pub specifier: String,
20	    /// The exported name in the source module (original name before `as` rename).
21	    pub exported_name: CompactString,
22	    /// `true` for `import type { ... }` bindings.
23	    #[allow(dead_code)]
24	    pub is_type_only: bool,
25	}
26	
27	/// Result of walking one step of a re-export chain.
28	#[allow(dead_code)]
29	#[derive(Debug, Clone)]
30	pub enum ReExportStep {
31	    /// Found a named re-export — caller resolves `source_specifier` to a file and recurses.
32	    Named { source_specifier: String, source_name: String },
33	    /// Found one or more `export * from "..."` entries — caller checks each.
34	    Wildcards(Vec<String>),
35	}
