37	// ─── ImportResolutionMap ──────────────────────────────────────────────────────
38	
39	/// Maps `(consuming_file, local_name)` → import reference.
40	/// Built once from `GlobalSourceData`, then used read-only during parallel resolution.
41	pub struct ImportResolutionMap {
42	    /// `file_path` → (`local_name` → specifier + original exported name).
43	    /// Nested (rather than a flat `(Utf8PathBuf, CompactString)` key) so lookups can
44	    /// borrow `&Utf8Path` directly instead of cloning the whole path per call.
45	    /// Note: we store the specifier string, not the resolved file path.
46	    /// The resolver calls `oxc_resolver` to turn specifiers into absolute paths.
47	    bindings: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, ImportRef>>,
48	
49	    /// `barrel_file` → specifiers it wildcard-re-exports from (`export * from "..."`).
50	    #[allow(dead_code)]
51	    wildcard_sources: FxHashMap<Utf8PathBuf, Vec<String>>,
52	}
53	
54	impl ImportResolutionMap {
55	    /// Build from a fully-merged `GlobalSourceData`.
56	    /// Called once per extraction run, before parallel resolution starts.
57	    ///
58	    /// No I/O — pure data transformation.
59	    pub fn build(global: &GlobalSourceData) -> Self {
60	        let mut bindings: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, ImportRef>> = FxHashMap::default();
61	        let mut wildcard_sources: FxHashMap<Utf8PathBuf, Vec<String>> = FxHashMap::default();
62	
63	        // ── Populate bindings from import_map ──────────────────────────────
64	        for (file_path, import_bindings) in &global.import_map {
65	            let per_file = bindings.entry(file_path.clone()).or_default();
66	            for binding in import_bindings {
67	                per_file.insert(
68	                    binding.local_name.clone(),
69	                    ImportRef {
70	                        specifier: binding.specifier.clone(),
71	                        exported_name: binding.exported_name.clone(),
72	                        is_type_only: binding.is_type_only,
73	                    },
74	                );
75	            }
76	        }
77	
78	        // ── Populate wildcard_sources from re_export_map ──────────────────
79	        for (file_path, exports) in &global.re_export_map {
80	            for export in exports {
81	                if let LexedExport::ReExportAll { source_specifier, .. } = export {
82	                    wildcard_sources.entry(file_path.clone()).or_default().push(source_specifier.clone());
83	                }
84	            }
85	        }
86	
87	        Self { bindings, wildcard_sources }
88	    }
89	
90	    /// Given a file and a local name used in that file, return where it was imported from.
91	    ///
92	    /// Returns `None` if the name is locally defined (not imported).
93	    pub fn find_import(&self, file: &Utf8Path, local_name: &str) -> Option<&ImportRef> {
94	        self.bindings.get(file)?.get(local_name)
95	    }
