102	    #[allow(dead_code)]
103	    pub fn resolve_reexport_chain(
104	        &self,
105	        barrel_file: &Utf8Path,
106	        exported_name: &str,
107	        global: &GlobalSourceData,
108	    ) -> Option<ReExportStep> {
109	        let exports = global.re_export_map.get(barrel_file)?;
110	
111	        let mut wildcard_specifiers: Vec<String> = Vec::new();
112	
113	        for export in exports {
114	            match export {
115	                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } => {
116	                    if local_name == exported_name {
117	                        return Some(ReExportStep::Named {
118	                            source_specifier: source_specifier.clone(),
119	                            source_name: source_name.clone(),
