mod tests {
    use super::*;

    // The DTS parse cache (crates/core/src/cache.rs) serializes with plain
    // rmp_serde::to_vec/from_slice, which MessagePack-encodes structs
    // POSITIONALLY (as an array of values), not as a map of field names —
