    #[test]
    fn collected_object_field_round_trips_through_rmp_serde_positional_encoding() {
        let field = CollectedObjectField {
            name: "label".to_owned(),
            collected_type: CollectedType::String,
            required: true,
            description: "the label".to_owned(),
        };
        let ct = CollectedType::Object(vec![field]);

        let bytes = rmp_serde::to_vec(&ct).expect("serialization should succeed");
        let round_tripped: CollectedType =
            rmp_serde::from_slice(&bytes).expect("deserialization should succeed for rmp_serde's positional encoding");

        let CollectedType::Object(fields) = round_tripped else {
            panic!("expected CollectedType::Object, got {:?}", round_tripped);
        };
        assert_eq!(fields.len(), 1);
        assert_eq!(fields[0].name, "label");
        assert_eq!(fields[0].required, true);
        assert_eq!(fields[0].description, "the label");
    }
}

