export const meta = {
  name: 'post-session-adversarial-review',
  description: 'Multi-model adversarial review of everything since cc2ff97 — bugs, perf, competitive-fit vs react-docgen-typescript',
  phases: [
    { title: 'Find', detail: 'Sonnet 5 scans 7 areas for bugs/perf/DX/infra issues' },
    { title: 'Verify', detail: 'Opus 5 + Fable 5 independently judge each finding' },
    { title: 'Synthesize', detail: 'Opus 5 (high effort) produces the prioritized report' },
  ],
}

const PROJECT_CONTEXT = `
oxc-react-docgen: a 10-100x faster drop-in replacement for react-docgen-typescript (RDT).
OXC parses TypeScript/TSX in Rust with no type-checking pass; props are resolved structurally.
The ENTIRE value proposition is speed (cold extraction ~32ms vs RDT's multi-second Program spin-up)
AND accuracy (must match RDT's real output on real component libraries — tracked in docs/rdt-coverage.md).

Two categories of bug are competitively fatal, more than any generic code-quality issue:
1. PERFORMANCE REGRESSIONS in hot paths (resolver/*, extractor/*, cache.rs) — speed is why anyone
   would choose this over RDT. An accidental clone, allocation, or repeated computation on a path
   that runs per-type or per-file is a real competitive threat, not just a style nit.
2. ACCURACY REGRESSIONS — anything that silently produces a wrong prop type, drops a prop, or
   misclassifies a component. crates/core/CLAUDE.md non-negotiable #6: always emit a Diagnostic
   when degrading, never fail silently.

Non-negotiables: no unwrap() outside #[cfg(test)]; FxHashMap internal maps, BTreeMap JSON-output
maps; CompactString for hot-path names; no AST refs escape parse_file(); no terminal code in
crates/core; no wildcard matches on project-local enums (exhaustive match is deliberate — it's
already caught several real bugs this session by forcing every call site to handle new variants).

This review covers everything from commit cc2ff97 to HEAD on main: resolver diagnostic-quality
fixes, a newly-wired barrel/re-export resolution feature (recursive, runs on every type lookup),
consumer-surface (NAPI binding + vite-plugin) fixes, and new infrastructure (moon task graph, CI
affected-detection gating, oxfmt formatting, oxlint linting, AGPL license adoption). The infra
changes are ONLY locally verified — nobody has actually run the GitHub Actions workflow yet.
`.trim()

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      maxItems: 5,
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          line: { type: 'number' },
          dimension: { type: 'string', enum: ['correctness', 'performance', 'competitive-accuracy', 'dx-adoption', 'infra-correctness'] },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          summary: { type: 'string' },
          detail: { type: 'string' },
          suggested_fix: { type: 'string' },
        },
        required: ['file', 'dimension', 'severity', 'summary', 'detail'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean' },
    reasoning: { type: 'string' },
  },
  required: ['refuted', 'reasoning'],
}

const AREAS = [
  {
    key: 'resolver-diagnostics',
    prompt: `${PROJECT_CONTEXT}\n\nReview the diagnostic-quality fixes in this range: run \`git log --oneline cc2ff97..HEAD -- crates/core/src/resolver crates/core/src/types/output.rs crates/core/src/types/diagnostic.rs crates/core/src/known.rs\` then \`git diff cc2ff97..HEAD -- crates/core/src/resolver crates/core/src/types/output.rs crates/core/src/types/diagnostic.rs crates/core/src/known.rs\`. Focus: corrected OpaqueReason tags, the new max_depth_diagnostic/io_read_error shared constructors, the UnresolvableImport message rewrite in chain.rs, group_diagnostics' comparison change. Look for: a wrong OpaqueReason mapping that slipped through, a message that leaks internal state again, a missed call site still using the old inline diagnostic construction, any correctness OR performance issue. Return up to 5 real findings, most severe first.`,
  },
  {
    key: 'barrel-resolution',
    prompt: `${PROJECT_CONTEXT}\n\nReview the new barrel/re-export resolution feature: \`git show c11130a\` and \`git diff cc2ff97..HEAD -- crates/core/src/resolver/import.rs crates/core/src/import_map.rs\`. This is NEW recursive logic (follow_reexports, MAX_REEXPORT_DEPTH=8) that runs on every named-type resolution — a hot path. Look hard for: infinite-loop risk in cyclic re-export graphs, unnecessary allocation per call (String/Vec churn), whether the depth guard is actually reachable/tested, whether wildcard-source iteration could be quadratic for large barrels, and any correctness gap (does it handle a barrel re-exporting from another barrel re-exporting from a third file — 3+ hops). Return up to 5 real findings, most severe first.`,
  },
  {
    key: 'cleanup-and-dedup',
    prompt: `${PROJECT_CONTEXT}\n\nReview \`git show b50fa0b\` (TS-utility-type dedup, dead branch removal, CollectedObjectField derive change, canonicalize_first_src_dir extraction). Look for: did the is_ts_utility_type consolidation actually preserve identical behavior at both call sites (chain.rs vs named.rs had a slightly different name list historically — verify nothing was dropped), does the CollectedObjectField derive change actually stay wire-compatible with anything that might depend on the old manual JSON shape, is the cva-call-detection allocation fix actually correct (still matches the same set of callee names). Return up to 5 real findings, most severe first.`,
  },
  {
    key: 'consumer-surface',
    prompt: `${PROJECT_CONTEXT}\n\nReview \`git show bd6a8f9\` (crates/binding/src/lib.rs's TryFrom rewrite, packages/napi/index.d.ts fixes, packages/vite-plugin/src/index.ts's buildStart + skipHtmlProps). This is the actual code real npm consumers run — a bug here is a first-impression bug. Look for: does the TryFrom<JsExtractOptions> rewrite handle every field correctly (compare against the old hand-built version for a dropped field), does buildStart's cold-extraction path have a race with configureServer in any dev-server-then-rebuild scenario, is skipHtmlProps's mapping to htmlAttributes:'none' actually correct for every options combination, does the Diagnostic field type fix (file/line/column/help as T|null) match what's actually serialized today. Return up to 5 real findings, most severe first.`,
  },
  {
    key: 'infra-moon-ci',
    prompt: `${PROJECT_CONTEXT}\n\nReview \`git show 611d215\` and \`git show b06e303\` (moon.yml task definitions across all 6 projects, and .github/workflows/ci.yml's new detect-changes affected-gating job). NOBODY has run this CI workflow yet — only local \`moon query\`/\`moon run\` testing happened. Look hard for: a project dependency edge that's still missing from the moon graph (would cause a real regression to be silently skipped by CI), a bash edge case in the detect-changes step (empty AFFECTED, a base ref that resolves but to a weird state, the python3 one-liner failing silently), whether the fail-open default actually triggers correctly in every case it's supposed to, whether gating cargo-deny would have been more correct than not gating it. Return up to 5 real findings, most severe first.`,
  },
  {
    key: 'infra-format-lint',
    prompt: `${PROJECT_CONTEXT}\n\nReview \`git show 4c79e73\` and \`git show 31fd9f5\` (.oxfmtrc.json, .oxlintrc.json, the justfile/CI wiring). Look for: source files that exist today but aren't covered by any of the explicit globs (check apps/validate, packages/napi, packages/vite-plugin, packages/cli for anything missed), whether any of the ~19 disabled oxlint rules are actually hiding a real bug class rather than pure noise, whether the two-invocation "strict src / relaxed tests" split could silently pass a file that matches neither glob, whether the config will visibly rot (e.g. a new file added later that nobody remembers to add to the globs). Return up to 5 real findings, most severe first.`,
  },
  {
    key: 'license-and-docs',
    prompt: `${PROJECT_CONTEXT}\n\nReview \`git show 6c411b9\` (AGPL license adoption across 13 package.json + Cargo.toml) and the docs/adr/*.md files added this range. Look for: any package.json or Cargo.toml that still claims MIT or has no license field that should have one, whether cargo-deny's allow-list change is scoped correctly (does it accidentally allow AGPL for a THIRD-PARTY dependency where that would be wrong, vs. just this workspace's own crates), whether any ADR's factual claim (the recursion_limit finding, the 32ms benchmark citation) is unverifiable or overstated as written. Return up to 5 real findings, most severe first.`,
  },
]

phase('Find')
const found = await Promise.all(AREAS.map((a) => agent(a.prompt, { label: `find:${a.key}`, phase: 'Find', schema: FINDINGS_SCHEMA })))

const allFindings = []
found.forEach((result, i) => {
  const list = (result && result.findings) || []
  list.forEach((f) => allFindings.push({ ...f, area: AREAS[i].key }))
})
log(`Found ${allFindings.length} candidate findings across ${AREAS.length} areas.`)

phase('Verify')
const verified = await pipeline(
  allFindings,
  (f) =>
    Promise.all([
      agent(
        `${PROJECT_CONTEXT}\n\nAdversarially verify this finding — try to REFUTE it. Read the actual current code at the cited file/line yourself before judging; don't take the summary on faith. Default to refuted=true if you can't confirm the issue is real and matters.\n\nFinding (area: ${f.area}, dimension: ${f.dimension}, severity: ${f.severity}):\n${f.summary}\n\n${f.detail}`,
        { label: `verify-opus:${f.area}`, phase: 'Verify', schema: VERDICT_SCHEMA, model: 'opus' },
      ),
      agent(
        `${PROJECT_CONTEXT}\n\nAdversarially verify this finding — try to REFUTE it. Read the actual current code at the cited file/line yourself before judging; don't take the summary on faith. Default to refuted=true if you can't confirm the issue is real and matters.\n\nFinding (area: ${f.area}, dimension: ${f.dimension}, severity: ${f.severity}):\n${f.summary}\n\n${f.detail}`,
        { label: `verify-fable:${f.area}`, phase: 'Verify', schema: VERDICT_SCHEMA, model: 'fable' },
      ),
    ]).then((votes) => ({ ...f, votes: votes.filter(Boolean) })),
)

const confirmed = verified.filter(Boolean).filter((f) => {
  const refutes = f.votes.filter((v) => v.refuted).length
  return refutes < f.votes.length // survives unless ALL available votes refute it
})
log(`${confirmed.length} of ${allFindings.length} findings survived adversarial verification.`)

phase('Synthesize')
const report = await agent(
  `${PROJECT_CONTEXT}\n\nYou are producing the final report for this adversarial review. Below are confirmed findings (JSON), each with the verifying models' reasoning attached. Write a prioritized report: group by severity, lead with anything that's a real performance regression on a hot path or a real accuracy regression — those are the competitively fatal categories per the project context above. For each finding give: what it is, why it matters given this project's actual goal (beating RDT on speed+accuracy), and a concrete suggested fix. End with a short "what's NOT a real problem" section for anything notable that got refuted, so the reasoning isn't lost. Keep it tight and actionable, not padded.\n\nConfirmed findings:\n${JSON.stringify(confirmed, null, 2)}`,
  { label: 'synthesis', phase: 'Synthesize', model: 'opus', effort: 'high' },
)

return { totalFindings: allFindings.length, confirmedCount: confirmed.length, confirmed, report }

