  1 │ //! Import and canonical resolution.
  2 │ 
  3 │ use camino::{Utf8Path, Utf8PathBuf};
  4 │ 
  5 │ use crate::import_map::ReExportStep;
  6 │ use crate::types::*;
  7 │ 
  8 │ use super::ResolutionContext;
  9 │ 
 10 │ /// Re-export chains in real code are shallow (one or two barrel hops); this
 11 │ /// only guards against a pathological or cyclic `export * from` graph.
 12 │ const MAX_REEXPORT_DEPTH: u8 = 8;
 13 │ 
 14 │ /// Resolve `name` to its canonical `(file_path, name)` pair.
 15 │ /// Returns `None` if `name` is a local declaration (not imported).
 16 │ pub(super) fn resolve_to_canonical(
 17 │     name: &str,
 18 │     consuming_file: &Utf8Path,
 19 │     ctx: &ResolutionContext,
 20 │     diagnostics: &mut Vec<Diagnostic>,
 21 │ ) -> Option<(Utf8PathBuf, String)> {
 22 │     if let Some(import_ref) = ctx.import_map.find_import(consuming_file, name) {
 23 │         let resolved_file = resolve_import_specifier(&import_ref.specifier, consuming_file, ctx, diagnostics)?;
 24 │         let canonical_name = import_ref.exported_name.to_string();
 25 │         return Some(follow_reexports(resolved_file, canonical_name, ctx, diagnostics, 0));
 26 │     }
 27 │ 
 28 │     // Namespace-import member access: `import * as React from "react"` then a
 29 │     // reference to `React.DependencyList`. `find_import` only tracks the
 30 │     // namespace binding itself ("React", with `exported_name == "*"`) — a
 31 │     // literal dotted name like "React.DependencyList" is never itself a
 32 │     // binding, so the lookup above always misses it. Split off the namespace
 33 │     // prefix and route the member name through the namespace's own import
 34 │     // specifier instead.
 35 │     let (namespace, member) = name.split_once('.')?;
 36 │     let namespace_ref = ctx.import_map.find_import(consuming_file, namespace)?;
 37 │     if namespace_ref.exported_name != "*" {
 38 │         return None;
 39 │     }
 40 │     let resolved_file = resolve_import_specifier(&namespace_ref.specifier, consuming_file, ctx, diagnostics)?;
 41 │     Some(follow_reexports(resolved_file, member.to_string(), ctx, diagnostics, 0))
 42 │ }
 43 │ 
 44 │ /// A directly-imported name may land on a barrel file (`export { X } from
 45 │ /// './x'` or `export * from './x'`) that doesn't declare `name` itself —
 46 │ /// ubiquitous in real component libraries' `index.ts` files. Follow the
 47 │ /// re-export chain until we reach a file that actually declares `name`, or
 48 │ /// run out of chain to follow — in which case the original (barrel_file,
 49 │ /// name) is returned unchanged, so the caller's existing "cannot resolve"
 50 │ /// diagnostic still fires exactly as it did before this existed.
 51 │ fn follow_reexports(
 52 │     file: Utf8PathBuf,
 53 │     name: String,
 54 │     ctx: &ResolutionContext,
 55 │     diagnostics: &mut Vec<Diagnostic>,
 56 │     depth: u8,
 57 │ ) -> (Utf8PathBuf, String) {
 58 │     if depth >= MAX_REEXPORT_DEPTH || is_declared_at(&ctx.global, &file, &name) {
 59 │         return (file, name);
 60 │     }
 61 │     match ctx.import_map.resolve_reexport_chain(&file, &name, &ctx.global) {
 62 │         Some(ReExportStep::Named { source_specifier, source_name }) => {
 63 │             let Some(next_file) = resolve_import_specifier(&source_specifier, &file, ctx, diagnostics) else {
 64 │                 return (file, name);
 65 │             };
 66 │             follow_reexports(next_file, source_name, ctx, diagnostics, depth + 1)
 67 │         }
 68 │         Some(ReExportStep::Wildcards(specifiers)) => {
 69 │             for specifier in &specifiers {
