 97 │ /// "React.HTMLAttributes" even though nothing imports them that way — a plain
 98 │ /// `import type { HTMLAttributes } from "react"` binds the bare name.
 99 │ pub(super) fn lookup_interface<'g>(
100 │     global: &'g GlobalSourceData,
101 │     canonical_file: &str,
102 │     canonical_name: &str,
103 │ ) -> Option<&'g CollectedInterface> {
104 │     global
105 │         .interfaces
106 │         .get(&format!("{canonical_file}:{canonical_name}"))
107 │         .or_else(|| global.interfaces.get(&format!("{canonical_file}:React.{canonical_name}")))
108 │ }
109 │ 
110 │ /// Same as `lookup_interface`, for type aliases. Returns the key that actually
111 │ /// matched (bare or `React.`-qualified) alongside the value, since callers
112 │ /// also need it to look up `type_alias_params` under the same key.
113 │ pub(super) fn lookup_type_alias<'g>(
114 │     global: &'g GlobalSourceData,
115 │     canonical_file: &str,
116 │     canonical_name: &str,
117 │ ) -> Option<(String, &'g CollectedTypeAlias)> {
118 │     let bare_key = format!("{canonical_file}:{canonical_name}");
119 │     if let Some(alias) = global.type_aliases.get(&bare_key) {
120 │         return Some((bare_key, alias));
121 │     }
122 │     let qualified_key = format!("{canonical_file}:React.{canonical_name}");
123 │     global.type_aliases.get(&qualified_key).map(|alias| (qualified_key, alias))
124 │ }
125 │ 
126 │ /// Same as `lookup_interface`, but also falls back to TypeScript's own ambient
127 │ /// lib files (`ctx.ambient_global_files`) when the name isn't found via
128 │ /// import/same-file resolution — e.g. `HTMLDivElement`, declared ambiently in
129 │ /// `lib.dom.d.ts`, is never imported, so `resolve_to_canonical` never resolves
130 │ /// it to that file and `canonical_file` stays the consuming file instead.
131 │ pub(super) fn lookup_interface_including_ambient<'g>(
132 │     ctx: &'g ResolutionContext,
133 │     canonical_file: &str,
134 │     canonical_name: &str,
135 │ ) -> Option<&'g CollectedInterface> {
136 │     lookup_interface(&ctx.global, canonical_file, canonical_name).or_else(|| {
137 │         ctx.ambient_global_files
138 │             .iter()
139 │             .find_map(|lib_file| ctx.global.interfaces.get(&format!("{lib_file}:{canonical_name}")))
140 │     })
141 │ }
142 │ 
143 │ /// Look up a name directly on TypeScript's own ambient lib files
144 │ /// (`ctx.ambient_global_files` — `lib.es5.d.ts`/`lib.dom.d.ts`), by bare name
145 │ /// only (these are ambient globals, never namespace-qualified). Deliberately
146 │ /// separate from — and only ever consulted AFTER — every other resolution
147 │ /// path (imports, same-file declarations, the well-known-TS-utility-type
148 │ /// silent list): `Record`/`Partial`/etc. are themselves declared here too
149 │ /// (`Record<K, T> = { [P in K]: T }`, a mapped type this tool can't expand),
150 │ /// so checking this first would intercept those already-handled names and
151 │ /// degrade them to Opaque instead of leaving them to the existing shortcuts.
152 │ pub(super) fn lookup_ambient_global<'g>(ctx: &'g ResolutionContext, name: &str) -> Option<AmbientGlobalLookup<'g>> {
153 │     for lib_file in &ctx.ambient_global_files {
154 │         let key = format!("{lib_file}:{name}");
155 │         if ctx.global.interfaces.contains_key(&key) {
156 │             return Some(AmbientGlobalLookup::Interface);
157 │         }
158 │         if let Some(alias) = ctx.global.type_aliases.get(&key) {
159 │             return Some(AmbientGlobalLookup::TypeAlias(alias));
160 │         }
161 │     }
162 │     None
163 │ }
164 │ 
165 │ pub(super) enum AmbientGlobalLookup<'g> {
166 │     Interface,
167 │     TypeAlias(&'g CollectedTypeAlias),
168 │ }
169 │ 
170 │ /// Use `oxc_resolver` to turn an import specifier into an absolute file path.
171 │ pub(super) fn resolve_import_specifier(
172 │     specifier: &str,
173 │     from_file: &Utf8Path,
174 │     ctx: &ResolutionContext,
175 │     diagnostics: &mut Vec<Diagnostic>,
176 │ ) -> Option<Utf8PathBuf> {
177 │     let from_dir = from_file.parent()?;
178 │ 
179 │     // Bare package specifiers (not relative/absolute) need real TypeScript
180 │     // declaration resolution: prefer a real .d.ts over whatever JS entry point
181 │     // the package's own "main"/"exports" happens to point to, and fall back to
182 │     // the separate `@types/<package>` package when the package ships no types
183 │     // of its own at all — e.g. "react": its package.json has no "types" field
184 │     // and no "types" export condition, so a plain `resolve()` below lands on
185 │     // `index.js`, and a named type-only import like `HTMLAttributes` can never
186 │     // be found there.
187 │     if !specifier.starts_with('.') && !specifier.starts_with('/') {
188 │         if let Some(path) = super::react::resolve_package_types_file(&ctx.oxc_resolver, from_dir, specifier) {
189 │             return Utf8PathBuf::from_path_buf(std::path::PathBuf::from(path)).ok();
190 │         }
191 │     }
192 │ 
193 │     match ctx.oxc_resolver.resolve(from_dir.as_std_path(), specifier) {
194 │         Ok(resolved) => Utf8PathBuf::from_path_buf(resolved.path().to_owned()).ok(),
195 │         Err(e) => {
196 │             diagnostics.push(Diagnostic {
197 │                 severity: DiagnosticSeverity::Warning,
198 │                 message: format!("Cannot resolve '{}' from '{}'", specifier, from_file),
199 │                 file: Some(from_file.to_string()),
200 │                 line: None,
201 │                 column: None,
202 │                 help: Some(format!("Resolution error: {}", e)),
203 │                 code: DiagnosticCode::UnresolvableImport,
204 │             });
205 │             None
206 │         }
207 │     }
208 │ }

