    // component libraries: several sub-barrels all wildcarding a common
    // `types.ts`) re-explores that shared subtree once per path into it,
    // multiplying out to branching_factor^depth calls instead of one call per
    // graph node. Reproduced empirically in the review: 7 barrels took 9.7s
    // wall time vs 156ms at 2. This builds a minimal diamond — each barrel
    // wildcard-re-exports its next sibling TWICE — deep enough to hit
    // MAX_REEXPORT_DEPTH (8), with a name that's never declared anywhere (the
    // unhappy path, which forces full traversal instead of an early-exit on
    // first match). Without the visited-set fix this explores 2^8 = 256 calls;
    // with it, exactly 8 (one per graph node).
    #[test]
    fn test_barrel_resolution_does_not_exponentially_blow_up_on_shared_descendants() {
        let manifest_dir = camino::Utf8Path::new(env!("CARGO_MANIFEST_DIR"));
        let tmp = TempDir::new_in(manifest_dir).unwrap();

        // MAX_REEXPORT_DEPTH is 8; each "level" here spends 2 (barrel -> one of
        // BRANCHING distinct sibling files -> the next shared barrel), so 4
        // levels reaches the cap exactly. Every sibling is a genuinely distinct
        // file (not the same path referenced twice) so oxc_resolver's own path
        // cache can't absorb the redundancy the way a duplicate specifier would.
        const BRANCHING: usize = 10;
        const LEVELS: usize = 4;
        for level in 0..LEVELS {
            let entries = (0..BRANCHING)
                .map(|i| format!("export * from './sibling_{level}_{i}';\n"))
                .collect::<String>();
            write_file(&tmp, &format!("barrel_{level}.ts"), &entries);
            for i in 0..BRANCHING {
                write_file(&tmp, &format!("sibling_{level}_{i}.ts"), &format!("export * from './barrel_{}';\n", level + 1));
            }
