48	            .unwrap_or_else(|| (consuming_file.to_owned(), name.to_string()));
49	
50	    // ── 3. Type alias lookup ──────────────────────────────────────────────────
51	    if let Some((matched_key, alias)) = lookup_type_alias(&ctx.global, canonical_file.as_str(), &canonical_name) {
52	        let alias = alias.clone();
53	        // A generic alias's own declared type parameters (`type Foo<TData> = ...`)
54	        // are expected, unexpandable placeholders wherever referenced in its body —
55	        // not unresolvable types. Register them so step 7 below doesn't warn.
56	        if let Some(params) = ctx.global.type_alias_params.get(&matched_key) {
