import { spawnSync } from 'node:child_process'
import { resolve } from 'node:path'

// Cross-tool cold-extraction wall-clock comparison: each run below is a fresh
// child process, so the timing includes process startup + module load + (for
// rdt/rdg) TS-compiler/Babel init — the real cost a CI job or a fresh `npm
// run build` pays, not an in-process warm-loop number that hides that cost.
// This runs the WHOLE fixture corpus per invocation, same granularity as the
// existing run:* scripts (rdt/rdg: one Node process for every fixture; ours:
// one CLI process per library directory, summed) — a fair "cost of running
// this tool once over the repo" comparison, not a per-file microbenchmark.

const RUNS = 5

interface Timing {
  tool: string
  script: string
  msPerRun: number[]
}

function timeScript(tool: string, script: string): Timing {
  const msPerRun: number[] = []
  for (let i = 0; i < RUNS; i++) {
    const start = performance.now()
    const result = spawnSync('tsx', [resolve(import.meta.dirname, script)], {
      encoding: 'utf8',
      stdio: ['ignore', 'ignore', 'inherit'],
      maxBuffer: 100 * 1024 * 1024,
    })
    const elapsed = performance.now() - start
    if (result.error) throw new Error(`${script} failed to spawn: ${result.error.message}`)
    if (result.status !== 0) throw new Error(`${script} exited with status ${result.status}`)
    msPerRun.push(elapsed)
  }
  return { tool, script, msPerRun }
}

function median(xs: number[]): number {
  const sorted = [...xs].toSorted((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid]
}

function stddev(xs: number[]): number {
  const mean = xs.reduce((a, b) => a + b, 0) / xs.length
  const variance = xs.reduce((a, b) => a + (b - mean) ** 2, 0) / xs.length
  return Math.sqrt(variance)
}

const timings = [
  timeScript('react-docgen', 'run-react-docgen.ts'),
  timeScript('react-docgen-typescript', 'run-react-docgen-typescript.ts'),
  timeScript('oxc-react-docgen', 'run-ours.ts'),
]

console.log(`\nCold whole-corpus extraction, ${RUNS} runs each (fresh process per run):\n`)
const report = timings.map((t) => ({
  tool: t.tool,
  runsMs: t.msPerRun.map((n) => Math.round(n * 10) / 10),
  medianMs: Math.round(median(t.msPerRun) * 10) / 10,
  stddevMs: Math.round(stddev(t.msPerRun) * 10) / 10,
}))

for (const r of report) {
  console.log(`${r.tool.padEnd(28)} median=${r.medianMs}ms  stddev=${r.stddevMs}ms  runs=[${r.runsMs.join(', ')}]`)
}

const oursMedian = report.find((r) => r.tool === 'oxc-react-docgen')?.medianMs ?? 0
for (const r of report) {
  if (r.tool === 'oxc-react-docgen' || oursMedian === 0) continue
  console.log(`\noxc-react-docgen is ${(r.medianMs / oursMedian).toFixed(1)}x faster than ${r.tool} (cold, whole corpus)`)
}

import { writeFileSync } from 'node:fs'
writeFileSync('./bench-cold.json', JSON.stringify({ runs: RUNS, generatedAt: new Date().toISOString(), report }, null, 2))
console.log(`\nFull structured output written to apps/validate/bench-cold.json`)

