195	    // not unresolvable types. Register them so `resolve_named` doesn't warn.
196	    if let Some(params) = ctx.global.interface_type_params.get(&iface.scoped_key) {
197	        state.in_scope_type_params.extend(params.iter().cloned());
198	    }
199	
200	    // ── Resolve extends first — parent props come before own props ────────────
201	    for extends_ref in &iface.extends {
