259	/// Find a discriminant prop — a prop that has a distinct string literal type across all members.
260	pub(super) fn find_discriminant_prop(members: &[(&str, Vec<ParsedProp>)]) -> Option<String> {
261	    if members.is_empty() {
262	        return None;
263	    }
264	
265	    // Collect candidate prop names: appear in all members AND have PropType::StringLiteral in at least one.
266	    // Use the intersection of all member prop names as candidates.
267	    let mut candidate_names: Option<std::collections::BTreeSet<&str>> = None;
268	    for (_, member_props) in members {
269	        let names: std::collections::BTreeSet<&str> = member_props.iter().map(|p| p.name.as_str()).collect();
270	        candidate_names = Some(match candidate_names {
271	            None => names,
272	            Some(existing) => existing.intersection(&names).copied().collect(),
273	        });
274	    }
275	    let candidate_names = candidate_names.unwrap_or_default();
276	
277	    'outer: for candidate in &candidate_names {
278	        // Check that this prop has a string literal type in at least one member.
279	        let has_literal = members.iter().any(|(_, props)| {
280	            props.iter().any(|p| p.name.as_str() == *candidate && matches!(p.prop_type, PropType::StringLiteral(_)))
281	        });
282	        if !has_literal {
283	            continue;
284	        }
285	
286	        let mut literal_values: Vec<&str> = Vec::new();
287	        for (_, member_props) in members {
288	            let found = member_props.iter().find(|p| p.name.as_str() == *candidate);
289	            match found {
290	                Some(p) => {
291	                    if let PropType::StringLiteral(ref s) = p.prop_type {
292	                        if literal_values.contains(&s.as_str()) {
293	                            // Not distinct — try next prop.
294	                            continue 'outer;
295	                        }
296	                        literal_values.push(s.as_str());
297	                    } else {
298	                        continue 'outer; // Not a literal in this member.
299	                    }
300	                }
301	                None => continue 'outer, // Not present in all members.
302	            }
303	        }
304	
305	        if literal_values.len() == members.len() {
306	            return Some((*candidate).to_owned());
307	        }
308	    }
309	
310	    None
311	}
