63	            // Record omitted keys in the relevant inheritance layer.
64	            for layer in &mut chain.inheritance {
65	                for key in &all_omitted {
66	                    if !layer.omitted.contains(key) {
67	                        layer.omitted.push(key.clone());
68	                    }
69	                }
70	            }
71	            chain
72	        }
