75	            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
76	            let picked_set: FxHashSet<&str> = picked_keys.iter().map(|k| k.as_str()).collect();
77	            chain.props.retain(|p| picked_set.contains(p.name.as_str()));
