81	        CollectedTypeAlias::Partial { base, file_path } => {
82	            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
83	            // Make all props optional.
84	            for prop in &mut chain.props {
85	                prop.required = false;
86	            }
87	            chain
88	        }
89	
90	        CollectedTypeAlias::Required { base, file_path } => {
91	            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
92	            // Make all props required.
93	            for prop in &mut chain.props {
94	                prop.required = true;
95	            }
96	            chain
97	        }
98	
99	        CollectedTypeAlias::Union { members, file_path } => {
100	            // Discriminated union — try to find the discriminant and merge all members.
101	            resolve_union_alias(members, file_path, mapping, ctx, state, depth)
102	        }
103	
104	        CollectedTypeAlias::Intersection { members, file_path } => {
105	            // Merge all members' props.
106	            let mut chain = ResolvedChain::default();
107	            for member in members {
108	                let member_chain = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
109	                chain.merge_parent(member_chain);
110	            }
111	            chain
112	        }
