121	/// Resolve a `CollectedType` as a props chain (for base types in aliases).
122	pub(super) fn resolve_base_as_chain(
123	    base: &CollectedType,
124	    file_path: &Utf8Path,
125	    mapping: &ComponentMapping,
126	    ctx: &ResolutionContext,
127	    state: &mut ResolveState,
128	    depth: u8,
129	) -> ResolvedChain {
130	    match base {
131	        CollectedType::Named { name, args } => {
132	            // Omit/Pick/Partial/Readonly applied to a *structured* reference — e.g. a
133	            // member of `Omit<T, keyof U> & U` after `T`/`U` were substituted with real
134	            // types (see resolver/substitute.rs). Handled directly here, rather than via
135	            // the string-based `resolve_props_chain` path below, so nested generics and
136	            // `keyof` operands survive structurally instead of being flattened to a
137	            // single opaque display string first.
138	            if let Some(alias) = super::substitute::synthesize_utility_alias(name.as_str(), args, file_path) {
139	                return resolve_type_alias_chain(&alias, file_path, mapping, ctx, state, depth);
140	            }
141	
142	            // A user-defined generic alias referenced with structured (possibly
143	            // cross-file, possibly nested-generic) arguments — e.g.
144	            // `SelectRootBaseProps<T>` used as `Assign<T, U>`'s own `U` argument.
145	            // Substituted and resolved directly here so the nested generic survives,
146	            // rather than falling through to the string-based path below (which would
147	            // flatten it to a single opaque display string before substitution ever ran).
148	            if let Some(alias) = super::substitute::generic_alias_with_structured_args(
149	                name.as_str(),
150	                args,
151	                file_path,
152	                ctx,
153	                &mut state.diagnostics,
154	            ) {
155	                return resolve_type_alias_chain(&alias, file_path, mapping, ctx, state, depth + 1);
156	            }
157	
158	            let raw_args: Vec<String> = args.iter().map(|a| a.to_raw_string()).collect();
159	            resolve_props_chain(name.as_str(), &raw_args, file_path, mapping, ctx, state, depth + 1)
160	        }
161	        // Generic-alias substitution marker (see resolver/substitute.rs and the
162	        // `CollectedType::AtFile` doc comment): `inner` was written in `file`, not
163	        // whatever file this call chain has been resolving relative to — e.g. a
164	        // type argument substituted from the caller's scope into a callee alias
165	        // declared in a different file. Switch file context and continue.
166	        CollectedType::AtFile { file, inner } => resolve_base_as_chain(inner, file, mapping, ctx, state, depth),
167	        CollectedType::Intersection(members) => {
168	            let mut chain = ResolvedChain::default();
169	            for member in members {
170	                let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
171	                chain.merge_parent(sub);
172	            }
173	            chain
174	        }
175	        CollectedType::Object(fields) => {
176	            // Inline object type in an intersection: `ComponentPropsWithoutRef<'button'> & { asChild?: boolean }`
177	            // Expand the object fields directly as own props.
178	            let mut chain = ResolvedChain::default();
179	            for field in fields {
180	                let prop_type = resolve_collected_type(&field.collected_type, file_path, ctx, state, depth);
181	                chain.props.push(ParsedProp {
182	                    name: field.name.clone(),
183	                    prop_type,
184	                    required: field.required,
185	                    default_value: None,
186	                    description: field.description.clone(),
187	                    tags: Default::default(),
188	                    parent: None,
189	                    declarations: vec![],
190	                });
191	            }
192	            chain
193	        }
194	        CollectedType::Union(members) => {
195	            // Delegate to the same discriminant-detection merge used for a
196	            // directly-aliased union (`type X = A | B`). A union doesn't stop being
197	            // discriminated just because it's wrapped in an intersection
198	            // (`type X = Base & (A | B)`, e.g. react-day-picker's real
199	            // `DayPickerProps`) or used as `Omit<A | B, K>`'s base — falling back to
200	            // a naive per-member merge here silently lost the discriminant and
201	            // collapsed each prop's type to whichever branch happened to be seen
202	            // last instead of a proper union across all branches.
203	            resolve_union_alias(members, file_path, mapping, ctx, state, depth)
204	        }
205	        // None of these can ever provide a props chain (a props type must be
206	        // object-like — an interface, intersection, union, or inline object).
207	        // Named explicitly, not via a wildcard, so a future CollectedType
208	        // variant forces a compile error here instead of silently falling
209	        // through to an empty, undiagnosed chain the way IndexedAccess and
210	        // Function once did.
211	        CollectedType::String
212	        | CollectedType::Number
213	        | CollectedType::Boolean
214	        | CollectedType::Null
215	        | CollectedType::Undefined
216	        | CollectedType::Any
217	        | CollectedType::Never
218	        | CollectedType::Unknown
219	        | CollectedType::Void
220	        | CollectedType::BigInt
221	        | CollectedType::Symbol
222	        | CollectedType::StringLiteral(_)
223	        | CollectedType::NumberLiteral(_)
224	        | CollectedType::BoolLiteral(_)
225	        | CollectedType::Array(_)
226	        | CollectedType::Tuple(_)
227	        | CollectedType::TypeOf(_)
228	        | CollectedType::IndexedAccess { .. }
229	        | CollectedType::TemplateLiteral(_)
230	        | CollectedType::Function { .. }
231	        | CollectedType::Conditional { .. }
232	        | CollectedType::Mapped { .. }
233	        | CollectedType::KeyOf(_)
234	        | CollectedType::Raw(_) => {
235	            state.diagnostics.push(Diagnostic {
236	                severity: DiagnosticSeverity::Warning,
237	                message: format!(
238	                    "'{}' cannot be used as a component's props base in '{}' — expected an interface, \
239	                     intersection, union, or inline object type",
240	                    base.to_raw_string(),
241	                    file_path
242	                ),
243	                file: Some(file_path.to_string()),
244	                line: None,
245	                column: None,
246	                help: Some("Check that this member of the props type resolves to an object-like shape.".into()),
247	                code: DiagnosticCode::OpaqueType,
248	            });
249	            ResolvedChain::default()
250	        }
251	    }
252	}
