254	/// Resolve a `CollectedTypeAlias::Union` — detect discriminated union if possible.
255	#[allow(clippy::too_many_arguments)]
256	pub(super) fn resolve_union_alias(
257	    members: &[CollectedType],
258	    file_path: &Utf8Path,
259	    mapping: &ComponentMapping,
260	    ctx: &ResolutionContext,
261	    state: &mut ResolveState,
262	    depth: u8,
263	) -> ResolvedChain {
264	    use super::chain::find_discriminant_prop;
265	
266	    // Collect all member chains for named types (only Named can be discriminated).
267	    let named_members: Vec<(&str, Vec<ParsedProp>)> = members
268	        .iter()
269	        .filter_map(|m| {
270	            if let CollectedType::Named { name, .. } = m {
271	                let mut branch_state = ResolveState {
272	                    visited: state.visited.clone(),
273	                    diagnostics: vec![],
274	                    in_scope_type_params: state.in_scope_type_params.clone(),
275	                };
276	                let chain =
277	                    resolve_props_chain(name.as_str(), &[], file_path, mapping, ctx, &mut branch_state, depth + 1);
278	                state.diagnostics.extend(branch_state.diagnostics);
279	                Some((name.as_str(), chain.props))
280	            } else {
281	                None
282	            }
283	        })
284	        .collect();
285	
286	    if named_members.len() < 2 {
287	        // Not a discriminated union — just merge all.
288	        let mut chain = ResolvedChain::default();
289	        for member in members {
290	            let sub = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
291	            chain.merge_parent(sub);
292	        }
293	        return chain;
294	    }
295	
296	    // Try to find a discriminant prop (a prop whose type is a distinct string literal across all members).
297	    let discriminant = find_discriminant_prop(&named_members);
298	
299	    // Merge all props from all members. A prop's merged type is the union of every
300	    // distinct type it has across the members that declare it (deduped — two members
301	    // contributing the identical type must not produce a redundant single-member
302	    // union); a prop missing from at least one member becomes optional overall, even
303	    // if it was required in every member where it does appear, since the union type
304	    // doesn't guarantee its presence.
305	    let mut merged_props: BTreeMap<String, ParsedProp> = BTreeMap::new();
306	    let mut prop_types: BTreeMap<String, Vec<PropType>> = BTreeMap::new();
307	    let mut seen_count: BTreeMap<String, usize> = BTreeMap::new();
308	    let mut required_in_all: BTreeMap<String, bool> = BTreeMap::new();
309	    let mut total_variants: usize = 0;
310	
311	    for (_, member_props) in &named_members {
312	        total_variants += 1;
313	        record_variant_props(member_props, &mut merged_props, &mut prop_types, &mut seen_count, &mut required_in_all);
314	    }
315	
316	    // Also merge non-Named members (inline objects, intersections, nested unions, etc.)
317	    // that were excluded from the discriminant analysis above.
318	    for member in members {
319	        if !matches!(member, CollectedType::Named { .. }) {
320	            let sub_chain = resolve_base_as_chain(member, file_path, mapping, ctx, state, depth);
321	            total_variants += 1;
322	            record_variant_props(
323	                &sub_chain.props,
324	                &mut merged_props,
325	                &mut prop_types,
326	                &mut seen_count,
327	                &mut required_in_all,
328	            );
329	        }
330	    }
331	
332	    for (name, mut types) in prop_types {
333	        let prop_type = match types.len() {
334	            0 | 1 => match types.pop() {
335	                Some(t) => t,
336	                None => continue,
337	            },
338	            _ => PropType::Union(types),
339	        };
340	
341	        if let Some(entry) = merged_props.get_mut(&name) {
342	            entry.prop_type = prop_type;
343	            let present_everywhere = seen_count.get(&name).copied().unwrap_or(0) == total_variants;
344	            let required_everywhere = required_in_all.get(&name).copied().unwrap_or(false);
345	            entry.required = present_everywhere && required_everywhere;
346	        }
347	    }
348	
349	    // If we found a discriminant, merge its type as a union of all its literal values.
350	    if let Some(ref disc_name) = discriminant {
351	        let disc_literals: Vec<PropType> = named_members
352	            .iter()
353	            .filter_map(|(_, props)| props.iter().find(|p| &p.name == disc_name).map(|p| p.prop_type.clone()))
354	            .collect();
355	
356	        if let Some(disc_prop) = merged_props.get_mut(disc_name) {
357	            disc_prop.prop_type = PropType::Union(disc_literals);
358	        }
359	    }
360	
361	    // Emit discriminated union diagnostic if applicable.
362	    if discriminant.is_some() {
363	        state.diagnostics.push(Diagnostic {
364	            severity: DiagnosticSeverity::Info,
365	            message: format!(
366	                "Discriminated union detected with discriminant prop '{}'",
367	                discriminant.as_deref().unwrap_or("")
368	            ),
369	            file: Some(file_path.to_string()),
370	            line: None,
371	            column: None,
372	            help: None,
373	            code: DiagnosticCode::DiscriminatedUnion,
374	        });
375	    }
376	
377	    ResolvedChain { props: merged_props.into_values().collect(), discriminant_prop: discriminant, ..Default::default() }
378	}
