380	/// Record one union member's props into the shared merge accumulators: the
381	/// first-seen `ParsedProp` (for name/description/parent/etc.), the set of
382	/// distinct types contributed for each prop name, how many members declared
383	/// it, and whether every member that declared it marked it required.
384	fn record_variant_props(
385	    props: &[ParsedProp],
386	    merged_props: &mut BTreeMap<String, ParsedProp>,
387	    prop_types: &mut BTreeMap<String, Vec<PropType>>,
388	    seen_count: &mut BTreeMap<String, usize>,
389	    required_in_all: &mut BTreeMap<String, bool>,
390	) {
391	    for prop in props {
392	        merged_props.entry(prop.name.clone()).or_insert_with(|| prop.clone());
393	
394	        let types = prop_types.entry(prop.name.clone()).or_default();
395	        if !types.contains(&prop.prop_type) {
396	            types.push(prop.prop_type.clone());
397	        }
398	
399	        *seen_count.entry(prop.name.clone()).or_insert(0) += 1;
400	
401	        required_in_all
402	            .entry(prop.name.clone())
403	            .and_modify(|required| *required = *required && prop.required)
404	            .or_insert(prop.required);
405	    }
406	}
