408	/// Resolve a `CollectedTypeAlias` to a `PropType` (at the type level, not chain level).
409	///
410	/// Members reference relative to `alias.file_path()` — the alias's OWN declaring
411	/// file — never the caller's `consuming_file`. A `type Combined = A | B` alias
412	/// imported cross-file still has `A`/`B` as same-file siblings of `Combined`
413	/// wherever it was actually declared, not siblings of whatever file imported it.
414	pub(super) fn resolve_type_alias_type(
415	    alias: &CollectedTypeAlias,
416	    ctx: &ResolutionContext,
417	    state: &mut ResolveState,
418	    depth: u8,
419	) -> PropType {
420	    let file_path = alias.file_path();
421	    match alias {
422	        CollectedTypeAlias::LiteralUnion { members, .. } => {
423	            PropType::LiteralUnion { members: members.clone(), has_default: false }
424	        }
425	        CollectedTypeAlias::Passthrough { target, .. } => {
426	            resolve_collected_type(target, file_path, ctx, state, depth + 1)
427	        }
428	        CollectedTypeAlias::Union { members, .. } => {
429	            let resolved: Vec<PropType> =
430	                members.iter().map(|m| resolve_collected_type(m, file_path, ctx, state, depth + 1)).collect();
431	            PropType::Union(resolved)
432	        }
433	        CollectedTypeAlias::Intersection { members, .. } => {
434	            let resolved: Vec<PropType> =
435	                members.iter().map(|m| resolve_collected_type(m, file_path, ctx, state, depth + 1)).collect();
436	            PropType::Intersection(resolved)
437	        }
438	        CollectedTypeAlias::Partial { base, .. } | CollectedTypeAlias::Required { base, .. } => {
439	            resolve_collected_type(base, file_path, ctx, state, depth + 1)
440	        }
441	        CollectedTypeAlias::Omit { base, .. } | CollectedTypeAlias::Pick { base, .. } => {
442	            // At the type level, just forward to the base type.
443	            resolve_collected_type(base, file_path, ctx, state, depth + 1)
444	        }
445	    }
446	}
