export const meta = {
  name: 'edge-case-root-cause-analysis',
  description: 'Phase 0: find architectural root causes behind the edge-case audit findings and propose fix-pattern clusters + enforcement mechanisms',
  phases: [
    { title: 'Cluster Analysis', detail: 'one agent per candidate root-cause cluster' },
    { title: 'Synthesize', detail: 'merge into a single Phase 0 report' },
  ],
}

const CLUSTER_SCHEMA = {
  type: 'object',
  required: ['clusterName', 'rootCause', 'mechanismProposal', 'findingIds', 'adrNeeded'],
  properties: {
    clusterName: { type: 'string' },
    rootCause: { type: 'string', description: 'the underlying architectural/process reason this pattern recurred, not a restatement of the symptom' },
    mechanismProposal: { type: 'string', description: 'a concrete, code-level proposal to prevent recurrence — a shared helper/wrapper type, a custom lint, a single source of truth, a panic boundary convention, etc. Name exact files/functions where it would live.' },
    findingIds: { type: 'array', items: { type: 'string' }, description: 'which finding IDs from docs/edge-cases.md actually belong to this cluster (confirm or correct the rough assignment given in the prompt)' },
    misassignedNotes: { type: 'string', description: 'any findings originally assigned here that actually belong to a different cluster, or vice versa, and why' },
    adrNeeded: { type: 'boolean' },
    adrRationale: { type: 'string', description: 'if adrNeeded, what hard-to-reverse decision this ADR would record; if not, why the existing non-negotiables/ADRs already cover it' },
  },
}

const CONTEXT = `Read /Users/gabe/Projects/oxc-react-codegen/docs/edge-cases.md first for full context — it's a comprehensive audit of oxc-react-docgen (a Rust tool that parses TSX/TS with OXC and extracts React component prop metadata, a drop-in replacement for react-docgen-typescript) covering crash risks, silent data loss, and correctness bugs across the whole pipeline. Also read /Users/gabe/Projects/oxc-react-codegen/CLAUDE.md and /Users/gabe/Projects/oxc-react-codegen/crates/core/CLAUDE.md for the project's non-negotiables (no unwrap() outside tests, always emit a Diagnostic when degrading, FxHashMap/BTreeMap discipline) and /Users/gabe/Projects/oxc-react-codegen/docs/adr/ for existing architectural decisions (0001-0004) so you don't propose a duplicate.

This is a root-cause analysis, not a re-audit — the findings are already catalogued. Your job is to read the ACTUAL CODE at the cited locations (not just trust the doc's summary) and answer: why did this pattern happen repeatedly instead of being caught once? Is there a missing shared abstraction, a missing lint/CI check, a missing code-review checklist item, duplicated logic that drifted out of sync, or something else? Then propose a concrete, specific mechanism that would fix the existing instances AND prevent new ones — not just "add a diagnostic here," but "here is the one place a shared helper/lint/type should live so every call site is forced to comply."`

const CLUSTERS = [
  {
    name: 'silent-degrade',
    prompt: `${CONTEXT}

Your cluster: the "give up silently" pattern — a give-up/degrade path returns None, ResolvedChain::default(), or otherwise drops data with no Diagnostic emitted, violating the project's own non-negotiable #6 ("always emit a Diagnostic when degrading — never fail silently").

